window.SDG4_GRADES = {"1": [{"ch": 0, "q": "第4目标是关于什么的？", "options": ["为每个人提供好学校", "快车", "大城市", "只有体育"], "answer": 0, "explain": "第4目标名为“优质教育”，希望每个孩子都能在好学校里学习。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "世界有多少个目标？", "options": ["5", "17", "10", "50"], "answer": 1, "explain": "世界共有17个可持续发展目标。第4目标关乎教育。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "是谁商定了这些目标？", "options": ["一位老师", "只有孩子", "世界各国共同商定", "一家大公司"], "answer": 2, "explain": "所有联合国成员国共同商定了这些目标。联合国是由各国组成的组织。", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "每个孩子都能上学吗？", "options": ["是的，每个孩子都能", "只在城市里", "只在夏天", "不，数百万孩子不能"], "answer": 3, "explain": "数百万儿童和青少年无法上学。第4目标希望每个孩子都有学上。", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "为什么有些孩子不能上学？", "options": ["他们住得远，或家庭贫穷", "他们太高了", "学校总是关门", "他们不喜欢学习"], "answer": 0, "explain": "长途跋涉、费用和贫困使一些孩子无法上学。第4目标希望消除这些障碍。", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "每个孩子应该拥有什么？", "options": ["一辆汽车", "家附近一所好学校的学位", "一部手机", "天上的一座房子"], "answer": 1, "explain": "每个孩子都应该在离家不远的好学校里有一个学位。", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "读完学校是什么意思？", "options": ["第一天就离开", "逃掉所有的课", "读完所有年级并学到东西", "再也不回来"], "answer": 2, "explain": "读完学校就是把所有年级读完。许多孩子在结束前就离开了。", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "为什么孩子读完学校是件好事？", "options": ["它让他们很累", "这并不重要", "它会中断他们的学习", "它帮助他们学习，并让他们以后能找到工作"], "answer": 3, "explain": "读完学校能让孩子拥有更多技能，在人生中有更多机会。", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "在每个国家，大多数孩子都能读完学校吗？", "options": ["不，许多人很早就离开了", "是的，所有人都读完", "没有人上学", "只有女孩读完"], "answer": 0, "explain": "许多孩子没有读完学校，因此第4目标希望更多孩子坚持到最后。", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "孩子们在学校学什么？", "options": ["只是睡觉", "阅读、写字和算数", "只是玩游戏", "没有什么用处"], "answer": 1, "explain": "孩子们在学校学习阅读、写字和算数。这些技能会陪伴他们一生。", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "孩子只要上学就够了吗？", "options": ["是的，上学就够了", "只有老师需要学习", "不够，他们必须真正学到东西", "没关系"], "answer": 2, "explain": "只是待在学校里是不够的，孩子必须真正学到有用的东西。", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "什么能帮助孩子学会阅读？", "options": ["只有大声的音乐", "整天看电视", "待在家里", "书籍和好老师"], "answer": 3, "explain": "书籍、好老师和练习都能帮助孩子学会阅读。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "什么是技能？", "options": ["你能做得很好的事情，比如画画或数数", "放学后与朋友玩耍的地方", "老师每天早上写在黑板上的规则", "你家附近卖糖果和玩具的商店"], "answer": 0, "explain": "技能是我们学会做好的事情。第4目标希望年轻人学习工作和生活所需的技能。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "为什么年轻人需要技能？", "options": ["为了辍学", "为了找到工作，帮助社区", "为了无聊", "他们不需要"], "answer": 1, "explain": "技能能帮助年轻人找到工作，也能帮助他们的家庭和社区。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "以下哪一项是有用的技能？", "options": ["弄坏东西", "躲避朋友", "安全地使用电脑", "无视规则"], "answer": 2, "explain": "学习电脑和其他有用的技能，能帮助年轻人在工作和生活中取得成功。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "女孩和男孩应该有同样的上学机会吗？", "options": ["不，只有男孩", "不，只有女孩", "只在某些国家", "是的，两者都应该"], "answer": 3, "explain": "女孩和男孩应该有同样的学习机会。第4目标希望消除两者之间不公平的差异。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "对学校来说，“公平”是什么意思？", "options": ["每个人都有学习的机会", "只有富裕的孩子能学习", "有些孩子什么都得不到", "只有部分孩子受欢迎"], "answer": 0, "explain": "公平意味着每个孩子都有学习的机会，无论他们的家庭、住处或背景如何。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "谁应该能够上学？", "options": ["只有有钱人家的孩子", "每个孩子，无论家庭条件如何", "只有住在城市的孩子", "没有任何孩子"], "answer": 1, "explain": "第4目标指出，优质教育必须面向所有人，包括贫困或住得远的孩子。", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "什么最能帮助一所学校？", "options": ["一个大游泳池", "停车场里的豪华汽车", "优秀且受过培训的老师", "空荡荡的教室"], "answer": 2, "explain": "好老师能帮助孩子学习。第4目标希望有更多受过培训的老师。", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "老师需要什么来帮助孩子学习？", "options": ["完全没有帮助", "不拿工资工作", "不去上课", "培训和支持"], "answer": 3, "explain": "老师需要良好的培训和支持，才能帮助每个孩子学习。", "src": "UN 2030 Agenda (2015)"}, {"ch": 7, "q": "小学和中学应该免费吗？", "options": ["是的，第4目标希望学校免费", "不，学校必须收很多钱", "只为男孩", "只在城市"], "answer": 0, "explain": "第4目标希望为所有人提供免费的小学和中学教育。", "src": "UN 2030 Agenda (2015)"}, {"ch": 7, "q": "谁让每个孩子都能上学成为可能？", "options": ["只有有钱的父母", "政府和社区", "没有人", "只有孩子"], "answer": 1, "explain": "政府和社区帮助建设学校、支付教师工资，让每个孩子都能上学。", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "各国是在哪一年商定这些目标的？", "options": ["1900", "1950", "2015", "2050"], "answer": 2, "explain": "各国于2015年商定了这些目标，并将2030年定为实现目标的年份。", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "目标应该在哪一年实现？", "options": ["2010", "1990", "2100", "2030"], "answer": 3, "explain": "各国将2030年定为实现这些目标的年份。", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "为什么小孩子应该上学前班？", "options": ["为了做好上小学的准备", "因为放假", "为了停止学习", "没有用"], "answer": 0, "explain": "早期学习能帮助幼儿为上小学做好准备，并促进成长。", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "早期学习发生在什么时候？", "options": ["只在15岁", "小学之前", "只在30岁", "从不"], "answer": 1, "explain": "幼儿早期学习针对的是小学之前的几年。", "src": "UN 2030 Agenda (2015)"}, {"ch": 10, "q": "什么是读写能力？", "options": ["会游泳", "会画画", "会阅读和写字", "跑得快"], "answer": 2, "explain": "读写能力指阅读和写字。第4目标希望所有年轻人都具备读写能力。", "src": "UN 2030 Agenda (2015)"}, {"ch": 10, "q": "什么是计算能力？", "options": ["会唱歌", "会做饭", "会画画", "会数数和做加减法"], "answer": 3, "explain": "计算能力指使用数字的能力，比如数数和加法。", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "残疾儿童应该和其他孩子一起上学吗？", "options": ["是的，学校应该接纳他们", "不，他们应该待在家里", "只在周末", "只在特殊场所"], "answer": 0, "explain": "第4目标希望学校接纳并包容每个孩子，包括残疾儿童。", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "什么使学校具有包容性？", "options": ["只允许部分孩子进入", "每个人都受欢迎并能够学习", "孩子们被隔开", "没有人能进来"], "answer": 1, "explain": "包容性学校接纳每个孩子，让所有人都能一起学习。", "src": "UN 2030 Agenda (2015)"}], "2": [{"ch": 0, "q": "哪个数字代表优质教育？", "options": ["4", "2", "9", "12"], "answer": 0, "explain": "优质教育是17项全球目标中的第4目标。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "第4目标是关于什么的？", "options": ["只有体育", "为所有人提供良好的学习机会", "只有假期", "只有大城市"], "answer": 1, "explain": "第4目标希望每个孩子和成年人都能接受良好的教育。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "各国是在哪一年商定全球目标的？", "options": ["1945", "2001", "2015", "2040"], "answer": 2, "explain": "2015年，世界领导人商定了17项全球目标，并计划在2030年前实现。", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "为什么孩子应该上学？", "options": ["为了睡觉", "为了迟到", "为了独自一人", "为了学习和成长"], "answer": 3, "explain": "学校帮助孩子学习阅读、计算，并交到朋友。", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 1, "q": "每个孩子都有权上学吗？", "options": ["有", "没有", "只有男孩", "只在城市"], "answer": 0, "explain": "每个孩子都有接受教育的权利。", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 1, "q": "一个孩子因为离学校太远而无法到校。这是哪种问题？", "options": ["颜色", "可及性", "睡眠", "音乐"], "answer": 1, "explain": "可及性是指能够到达学校并走进去。", "src": "UNESCO"}, {"ch": 1, "q": "哪个地方能帮助孩子们一起学习？", "options": ["鞋店", "停车场", "学校", "杂货货架"], "answer": 2, "explain": "学校是孩子们与老师一起学习的地方。", "src": "UNESCO"}, {"ch": 2, "q": "为什么家长希望孩子读完学校？", "options": ["这会让孩子不喜欢在家看书", "这意味着学费再也不用交了", "这让孩子读完学校后不再需要学习", "读完学校能改善孩子未来的工作和健康"], "answer": 3, "explain": "读完学校与将来更好的工作、收入和健康相关。", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "为什么有些孩子会提前辍学？", "options": ["金钱、距离或疾病可能使他们无法继续", "他们不喜欢学习", "学校时间太短", "他们的书太多"], "answer": 0, "explain": "许多孩子因为钱、路程或生病而提前离开学校。", "src": "UNESCO"}, {"ch": 2, "q": "为什么留在学校很有好处？", "options": ["你会觉得无聊", "你每年都能学到更多", "你会失去朋友", "你会停止学习"], "answer": 1, "explain": "在学校的每一年都能帮助你学到更多，培养技能。", "src": "UNESCO"}, {"ch": 2, "q": "以下哪一项能帮助学生读完学校？", "options": ["错过每一节课", "不吃饭", "家人和老师的支持", "从不提问"], "answer": 2, "explain": "家人和老师的支持能帮助学生坚持下去。", "src": "UNESCO"}, {"ch": 3, "q": "什么是阅读？", "options": ["吃文字", "只会画画", "跑得快", "理解书页上的文字"], "answer": 3, "explain": "阅读是指理解文字及其表达的意思。", "src": "UNESCO"}, {"ch": 3, "q": "哪种技能能帮你算出2加3？", "options": ["数数", "游泳", "只会唱歌", "烹饪"], "answer": 0, "explain": "数数能帮助我们算出一共有多少东西。", "src": "UNESCO"}, {"ch": 3, "q": "哪种活动能帮助幼儿培养早期阅读能力？", "options": ["每天看很多小时电视", "大声朗读故事并讨论图片", "安静地抄写很长的随机单词列表", "只读数学题，从不读故事"], "answer": 1, "explain": "共同阅读和交谈能积累词汇，培养早期读写能力。", "src": "UNESCO"}, {"ch": 3, "q": "什么是图书馆？", "options": ["一个卖汽车的地方", "一个只有玩具的地方", "一个有很多书的地方", "一个游泳的地方"], "answer": 2, "explain": "图书馆是人们可以阅读和借书的地方。", "src": "UNESCO"}, {"ch": 4, "q": "什么是团队合作？", "options": ["总是独自工作", "独自赢得每场比赛", "躲避朋友", "与他人一起合作"], "answer": 3, "explain": "团队合作是指大家一起努力实现目标。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "哪种技能能帮你表达自己的感受？", "options": ["沟通", "单脚跳", "睡觉", "粉刷墙壁"], "answer": 0, "explain": "沟通是指表达自己的想法，并倾听他人。", "src": "UNESCO"}, {"ch": 4, "q": "什么是有创造力？", "options": ["一模一样地复制", "想出新的点子或作品", "从不尝试", "只会花钱"], "answer": 1, "explain": "有创造力是指创作出新的东西，比如一幅画或一个故事。", "src": "UNESCO"}, {"ch": 4, "q": "哪种技能能帮你解决问题？", "options": ["闭上眼睛", "逃走", "仔细思考", "无视它"], "answer": 2, "explain": "仔细思考能帮助我们找到问题的解决办法。", "src": "UNESCO"}, {"ch": 5, "q": "女孩和男孩都应该上学吗？", "options": ["只有男孩", "只有女孩", "两者都不应该", "是的，两者都应该"], "answer": 3, "explain": "女孩和男孩都应该有平等的上学机会。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "在教育中“平等”是什么意思？", "options": ["每个人都有公平的机会", "每个人穿同样的鞋", "有些孩子没有老师", "只有富家子弟能学习"], "answer": 0, "explain": "平等的教育意味着每个人都有公平的学习机会。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "学校里怎样公平地分享书本？", "options": ["只给跑得最快的孩子", "每个人都轮流使用", "只由老师保管", "只给最高的孩子"], "answer": 1, "explain": "公平分享是指每个孩子都有机会使用书本。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "哪些孩子有权上学？", "options": ["只有父母交最高学费的孩子", "只有住在首都的男孩", "每个孩子，无论其家庭或背景如何", "只有已经读得很好的孩子"], "answer": 2, "explain": "每个孩子都有接受教育的权利，不论其背景如何。", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 6, "q": "老师做什么？", "options": ["只卖食物", "只开公共汽车", "清扫天空", "帮助孩子学习"], "answer": 3, "explain": "老师帮助孩子学习新事物并成长。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "为什么学校需要优秀的老师？", "options": ["老师帮助孩子学好", "老师会阻止一切学习", "老师只布置家庭作业", "不需要老师"], "answer": 0, "explain": "优秀的老师帮助孩子学习，并让他们在学校感到安全。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么能帮助老师提高教学水平？", "options": ["每个人都减薪", "培训和支持", "关闭所有学校", "忽视孩子"], "answer": 1, "explain": "培训能帮助老师学习新的教学方法。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "一位优秀的老师能向孩子展示什么？", "options": ["如何残忍", "如何懒惰", "如何善良和好奇", "如何躲藏"], "answer": 2, "explain": "优秀的老师帮助孩子变得善良、好奇、勇敢。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "学校要正常运转需要什么？", "options": ["只需要电脑", "只需要大声的音乐", "只需要游泳池", "书本、课桌和老师"], "answer": 3, "explain": "学校需要很多东西，包括书本、课桌和老师。", "src": "UNESCO"}, {"ch": 7, "q": "什么能帮助孩子在学校保持安全和健康？", "options": ["干净的水和厕所", "大汽车", "没有屋顶", "只有大声的喇叭"], "answer": 0, "explain": "干净的水和厕所能帮助孩子在学校保持健康。", "src": "UN 2030 Agenda (2015)"}, {"ch": 7, "q": "为什么有些学校没有书？", "options": ["书是不需要的", "他们没有足够的钱", "孩子们不读书", "书太重了"], "answer": 1, "explain": "购买书本和其他学校用品需要钱。", "src": "UNESCO"}, {"ch": 7, "q": "为什么学校需要钱？", "options": ["只用于买汽车", "只用于支付假期费用", "用于购买学习用品", "学校不需要钱"], "answer": 2, "explain": "钱用于支付书本、老师的工资、课桌和其他学校用品。", "src": "UNESCO"}, {"ch": 8, "q": "哪份文件规定每个人都有受教育的权利？", "options": ["一本有家庭食谱的烹饪书", "一张月球环形山和海洋的地图", "整个学期的学校课表", "《世界人权宣言》"], "answer": 3, "explain": "《世界人权宣言》规定每个人都有受教育的权利。", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "《世界人权宣言》是哪一年通过的？", "options": ["1948", "1900", "1975", "2030"], "answer": 0, "explain": "它于1948年由联合国大会通过。", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "哪个组织成立于推动各国为和平与教育携手合作？", "options": ["马戏团", "联合国", "体育俱乐部", "汽车公司"], "answer": 1, "explain": "联合国在第二次世界大战后成立，旨在帮助各国携手合作。", "src": "United Nations"}, {"ch": 9, "q": "幼儿学习的好方法是什么？", "options": ["整天坐着不动", "保持沉默", "玩耍和交谈", "夜间工作"], "answer": 2, "explain": "幼儿通过玩耍，以及与成年人交谈，学到很多东西。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "什么能帮助婴儿学习？", "options": ["让他们待在黑暗中", "从不抱他们", "只给他们糖果", "跟他们说话和唱歌"], "answer": 3, "explain": "与婴儿说话、唱歌和玩耍能帮助他们学习语言。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "什么能帮助孩子在上学前健康成长？", "options": ["成年人的爱和照顾", "被独自留下", "吃太多糖果", "不睡觉"], "answer": 0, "explain": "幼年时期的爱、照顾和游戏能帮助孩子强壮，并为学习做好准备。", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "扫盲是什么意思？", "options": ["会跳舞", "会阅读和写字", "会游泳", "只会画画"], "answer": 1, "explain": "扫盲是指会阅读和写字。", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "字母表中A之后是哪个字母？", "options": ["Z", "D", "B", "Q"], "answer": 2, "explain": "B在字母表中排在A之后。", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "以下哪一项能帮助人们更好地阅读？", "options": ["从不翻开书", "只看视频", "忘记字母", "每天读一点"], "answer": 3, "explain": "每天读一点能帮助人们提高阅读能力。", "src": "UNESCO, International Literacy Day"}, {"ch": 11, "q": "学校中的包容是什么意思？", "options": ["每个人都受欢迎并能够学习", "只有部分孩子能加入", "孩子们必须都一样", "孩子们必须待在家里"], "answer": 0, "explain": "包容意味着每个孩子都能在学校学习，包括残疾儿童。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "残疾儿童应该能够上学吗？", "options": ["不是", "是的", "只在星期日", "只有没有朋友的时候"], "answer": 1, "explain": "残疾儿童有权与其他孩子一起上学。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "什么能帮助坐轮椅的孩子在学校学习？", "options": ["没有门的学校", "只有楼梯的学校", "有坡道的学校", "很远的学校"], "answer": 2, "explain": "坡道和无台阶的教室能帮助坐轮椅的孩子在学校里行动。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "对待与众不同的同学，什么是友善的做法？", "options": ["把他们排除在外", "给他们起绰号", "无视他们", "邀请他们一起玩"], "answer": 3, "explain": "接纳同学能让每个人都感到受欢迎。", "src": "UN CRPD (2006), Article 24"}, {"ch": 0, "q": "全球目标计划在哪一年实现？", "options": ["2030", "1990", "2000", "2060"], "answer": 0, "explain": "全球目标计划在2030年前实现。", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "什么能帮助孩子安全地上学？", "options": ["封闭的道路", "安全的道路和小路", "独自穿过繁忙的马路", "待在家里"], "answer": 1, "explain": "安全的道路和小路能帮助孩子安全地到达学校。", "src": "UNESCO"}, {"ch": 2, "q": "当学习变得困难时，继续坚持的好理由是什么？", "options": ["没人会注意", "学校从来没有帮助", "你能学习并实现目标", "学习毫无用处"], "answer": 2, "explain": "坚持下去能帮你实现目标，学习新的东西。", "src": "UNESCO"}, {"ch": 8, "q": "缩写 UN 代表什么？", "options": ["联合护士", "独特笔记", "名称之下", "联合国"], "answer": 3, "explain": "UN 代表“联合国”（United Nations）。", "src": "United Nations"}, {"ch": 9, "q": "为什么玩耍对幼儿有益？", "options": ["能帮助他们学习和成长", "浪费时间", "只会让他们累", "不被允许"], "answer": 0, "explain": "玩耍能培养思维、语言和社交能力。", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "字母表中的第一个字母是什么？", "options": ["Z", "A", "M", "K"], "answer": 1, "explain": "A 是英文字母表的第一个字母。", "src": "UNESCO, International Literacy Day"}], "3": [{"ch": 0, "q": "SDG 代表什么？", "options": ["可持续发展目标", "超级狗狗游戏", "简单桌面指南", "甜蜜晚餐小组"], "answer": 0, "explain": "SDG 代表可持续发展目标。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "全球目标共有多少个？", "options": ["7", "17", "12", "27"], "answer": 1, "explain": "全球目标共有17个，其中第4目标关乎教育。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "哪个词最能形容第4目标？", "options": ["速度", "安静", "质量", "价格"], "answer": 2, "explain": "第4目标名为“优质教育”。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "哪个目标编号对应清洁水和卫生设施？", "options": ["2", "9", "15", "6"], "answer": 3, "explain": "第6目标是“清洁饮水和卫生设施”。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "全球目标中的“具体目标”是什么？", "options": ["需要达成的具体目标", "一种纸张", "一种体育运动", "一种食物"], "answer": 0, "explain": "每项目标都有具体目标，明确说明要达成什么。", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "什么障碍会阻止女孩上学？", "options": ["书太多", "在不安全的道路上走很远的路", "阳光太多", "老师太多"], "answer": 1, "explain": "距离远和道路不安全会使孩子无法抵达学校。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 1, "q": "学校免费入学是什么意思？", "options": ["孩子必须交钱才能入学", "孩子每节课都要带钱", "孩子入学不用缴费", "孩子只能在周末上学"], "answer": 2, "explain": "免费上学意味着孩子上学不必缴纳费用。", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "哪项权利规定每个孩子都应能上学？", "options": ["拥有汽车的权利", "享受假期的权利", "加入体育队的权利", "受教育权"], "answer": 3, "explain": "受教育权意味着每个孩子都可以上学。", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 1, "q": "什么是偏远地区？", "options": ["远离城镇和城市的地方", "没有天空的地方", "海底的地方", "完全没有人的地方"], "answer": 0, "explain": "偏远地区远离城镇，孩子可能很难到达学校。", "src": "UNESCO"}, {"ch": 2, "q": "什么是辍学者？", "options": ["提前完成学业的学生", "在完成学业前离开学校的学生", "离职的老师", "阅读很快的学生"], "answer": 1, "explain": "辍学者在完成学业前离开了学校。", "src": "UNESCO"}, {"ch": 2, "q": "为什么让孩子完成小学教育很重要？", "options": ["意味着以后再也不用学习", "只是为了好玩", "让他们掌握基本的阅读、写作和数学能力", "意味着不用再做作业"], "answer": 2, "explain": "完成小学教育能培养终身受用的基本技能。", "src": "UNESCO"}, {"ch": 2, "q": "什么能帮助学生留在学校？", "options": ["缺课", "提前离校", "无视老师", "辅导和支持"], "answer": 3, "explain": "辅导和支持能帮助学生留在学校继续学习。", "src": "UNESCO"}, {"ch": 2, "q": "什么是出勤？", "options": ["在学校上课", "赢得奖品", "写信", "买书"], "answer": 0, "explain": "出勤指的是按时到校上课。", "src": "UNESCO"}, {"ch": 2, "q": "当孩子长期缺席时，学校应该怎么做？", "options": ["不理会他们", "查明原因并帮助他们返校", "无故把他们从名单上删除", "要求他们缴纳罚款"], "answer": 1, "explain": "学校可以支持家庭，帮助孩子重返校园。", "src": "UNESCO"}, {"ch": 3, "q": "算术能力主要关乎哪种技能？", "options": ["用鲜艳的颜色和画笔画画", "唱关于动物和季节的歌", "在日常生活中使用数字和基础数学", "背诵世界各国的名字"], "answer": 2, "explain": "算术能力指在日常生活中自信地运用数字。", "src": "UNESCO"}, {"ch": 3, "q": "检验自己学习的好方法是什么？", "options": ["从不再尝试", "不假思索地抄写", "上课睡觉", "提问并练习"], "answer": 3, "explain": "练习和提问能帮助你理解新事物。", "src": "UNESCO"}, {"ch": 3, "q": "什么是学习成果？", "options": ["学习者在学习之后能做到什么", "学校的学费", "考试当天的天气", "桌子的数量"], "answer": 0, "explain": "学习成果是学习者获得的技能或知识。", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "考试是用来做什么的？", "options": ["决定天气", "检查某人学到了什么", "让太阳升起", "选择午餐菜单"], "answer": 1, "explain": "考试帮助老师和学习者了解学到了什么。", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "什么是阅读理解？", "options": ["读得非常快", "大声朗读", "理解你所读的内容", "只看图片"], "answer": 2, "explain": "阅读理解指理解文本的含义。", "src": "UNESCO"}, {"ch": 4, "q": "哪种技能能帮助你与来自其他地方的人融洽合作？", "options": ["无视他人", "对别人大喊", "躲避别人", "尊重他人"], "answer": 3, "explain": "尊重能帮助来自不同背景的人一起工作和学习。", "src": "UNESCO"}, {"ch": 4, "q": "什么是批判性思维？", "options": ["检验一个想法是否合理", "同时相信所有想法", "从不提问", "忘记读过的内容"], "answer": 0, "explain": "批判性思维意味着提问并核实事实。", "src": "UNESCO"}, {"ch": 4, "q": "哪种技能将来可以帮你找工作？", "options": ["在上课时间长时间睡觉", "计算机或维修等实用技能", "逃避所有课程和在家练习", "完全拒绝学习任何新东西"], "answer": 1, "explain": "实用技能和职业技能能帮助人们工作并养活自己。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "哪种技能能帮助团队做决定？", "options": ["大声喊叫", "无视团队", "倾听每个人的意见", "离开房间"], "answer": 2, "explain": "倾听每个人的意见有助于团队做出好的选择。", "src": "UNESCO"}, {"ch": 4, "q": "什么是数字技能？", "options": ["只用铅笔", "弄坏电脑", "从不使用互联网", "安全地使用电脑和互联网"], "answer": 3, "explain": "数字技能能帮助人们安全、有效地使用科技。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "教育中的“公平”是什么意思？", "options": ["为每个孩子提供公平的支持，让他们能学习", "每个孩子得到完全相同的东西", "只有最优秀的学生才能得到帮助", "学校不需要提供帮助"], "answer": 0, "explain": "公平是指给每个孩子他们学习所需的支持。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "哪类儿童经常被排除在学校之外？", "options": ["喜欢在午休时踢足球的孩子", "贫困家庭或偏远地区的孩子", "喜欢在学校合唱团唱歌的孩子", "总是坐在前排的孩子"], "answer": 1, "explain": "贫困家庭和偏远地区的孩子更可能不在学校上学。", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "学校中的性别差距是什么？", "options": ["操场上孩子们玩耍的空地", "每天两节课之间的短暂休息", "学校里女孩和男孩之间的差异", "学校墙上需要修补的洞"], "answer": 2, "explain": "性别差距是指女孩和男孩在入学或学习方面的差异。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "为什么学校应接纳各种语言和背景的孩子？", "options": ["只能使用一种语言", "只允许一种背景的人", "孩子应该被赶走", "每个人都应获得公平的学习机会"], "answer": 3, "explain": "教育应当公平地包容所有孩子，不论其背景如何。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "哪类学生在学校可能需要额外帮助以确保安全？", "options": ["弱势儿童", "总是快乐的孩子", "会飞的孩子", "从不缺课的孩子"], "answer": 0, "explain": "弱势儿童可能更容易被忽视或受到伤害，因此需要额外帮助。", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "什么是教师短缺？", "options": ["教师对孩子来说太多", "没有足够的受过培训的教师", "从不工作的教师", "假期太多的教师"], "answer": 1, "explain": "短缺是指受过培训的教师数量不足。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么能帮助新教师做得好？", "options": ["完全没有支持", "被派往另一个国家", "辅导和培训", "长时间无薪休假"], "answer": 2, "explain": "辅导和培训能帮助新教师成长。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "教师的工作条件为什么重要？", "options": ["没有任何影响", "只和教师的汽车有关", "只在城市里重要", "它们影响孩子的学习效果"], "answer": 3, "explain": "良好的工作条件有助于教师留下来并教好书。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "教师备课需要什么？", "options": ["明确的目标和良好的计划", "对学科一无所知", "一把坏掉的椅子", "一个假期"], "answer": 0, "explain": "明确的目标和计划能帮助教师教好书。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "教师需要什么来持续学习？", "options": ["再也不用学习", "持续的培训", "只要假期", "只要金钱"], "answer": 1, "explain": "教师通过持续的培训继续学习。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "什么是学费？", "options": ["好成绩的奖品", "老师送的礼物", "为入学而支付的费用", "迟到的罚款"], "answer": 2, "explain": "学费是家庭有时为孩子入学而支付的费用。", "src": "UNESCO"}, {"ch": 7, "q": "政府为什么要在学校上投入资金？", "options": ["只为了增加假期", "只为了修更多的路", "为了减少上学天数", "帮助孩子学习和成长"], "answer": 3, "explain": "公共资金用于支付教师、校舍和书本，让孩子能够学习。", "src": "UNESCO"}, {"ch": 7, "q": "教室需要什么才能成为安全的学习场所？", "options": ["良好的照明、新鲜的空气和牢固的屋顶", "完全没有窗户，让房间保持黑暗", "整节课都有街上传来的嘈杂声", "每周都有坏椅子和漏水的屋顶"], "answer": 0, "explain": "良好的校舍能帮助孩子舒适、安全地学习。", "src": "UN 2030 Agenda (2015)"}, {"ch": 7, "q": "如果学校没有钱买书，会发生什么？", "options": ["孩子学得更快", "孩子的学习机会减少", "孩子不再需要上学", "孩子获得额外假期"], "answer": 1, "explain": "没有书，孩子可能更难学习。", "src": "UNESCO"}, {"ch": 8, "q": "联合国《儿童权利公约》是哪一年通过的？", "options": ["1948", "1990", "1989", "2015"], "answer": 2, "explain": "该公约于1989年由联合国大会通过。", "src": "UN Convention on the Rights of the Child, 1989"}, {"ch": 8, "q": "什么是千年发展目标？", "options": ["1900年的一套目标", "为月球制定的一套目标", "为体育制定的一套目标", "2000年至2015年的一套目标"], "answer": 3, "explain": "千年发展目标实施于2000年至2015年，早于全球目标。", "src": "UN Millennium Development Goals (2000)"}, {"ch": 8, "q": "1990年哪次会议重点讨论了“全民教育”？", "options": ["在泰国朱莫提恩召开的世界全民教育大会", "当年在纽约举办的国际贸易博览会", "当年夏天在戛纳举办的全球电影节", "在巴西举行的关于足球规则的世界峰会"], "answer": 0, "explain": "1990年，各国在泰国朱莫提恩集会，承诺实现全民教育。", "src": "UNESCO"}, {"ch": 8, "q": "哪一天每年都庆祝教师？", "options": ["1月1日", "世界教师日，10月5日", "12月25日", "9月8日"], "answer": 1, "explain": "联合国教科文组织每年10月5日庆祝世界教师日。", "src": "UNESCO"}, {"ch": 9, "q": "什么是幼儿期？", "options": ["只有青少年时期", "只有大学时期", "从出生到大约八岁的年龄段", "只有最后一年学校生活"], "answer": 2, "explain": "幼儿期通常指从出生到大约八岁的年龄段。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "为什么早期学习很重要？", "options": ["早年不重要", "只有后期才重要", "早期学习只对体育有帮助", "早期经历会影响大脑的发育"], "answer": 3, "explain": "早期经历会塑造大脑的生长和学习方式。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "哪项是好的早期学习活动？", "options": ["一起阅读图画书", "整天看电视", "让孩子独自待几个小时", "只吃糖果"], "answer": 0, "explain": "一起阅读能促进语言和早期学习。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "什么是以游戏为基础的学习？", "options": ["通过静坐来学习", "通过玩耍来学习", "只通过抄写来学习", "从不提问地学习"], "answer": 1, "explain": "以游戏为基础的学习帮助幼儿通过动手实践来学习。", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "国际扫盲日是哪一天？", "options": ["1月1日", "12月25日", "9月8日", "4月30日"], "answer": 2, "explain": "联合国教科文组织每年的9月8日纪念国际扫盲日。", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "什么能帮助成年人学会阅读？", "options": ["被迫停止阅读", "多睡觉", "避免看书", "成人扫盲班"], "answer": 3, "explain": "成人扫盲班能帮助成年人学习阅读和写作。", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "为什么有些人阅读困难？", "options": ["他们没有受教育的机会", "阅读是违法的", "书是有毒的", "字太大了"], "answer": 0, "explain": "许多人在学校没有机会学习阅读，因此错过了这项学习。", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "国际母语日是哪一天？", "options": ["5月1日", "2月21日", "10月31日", "7月14日"], "answer": 1, "explain": "联合国教科文组织每年的2月21日纪念国际母语日。", "src": "UNESCO, International Mother Language Day"}, {"ch": 11, "q": "学校应该为残障儿童做什么？", "options": ["让他们与其他人分开", "拒绝让他们入学", "接纳他们并提供支持", "把他们送回家"], "answer": 2, "explain": "包容性学校欢迎残障儿童，并为他们提供支持。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "学校中的“合理便利”是什么？", "options": ["逃避教学的办法", "通往城市的专车", "一种考试费用", "帮助孩子参与学习的调整"], "answer": 3, "explain": "合理便利是帮助孩子参与学校活动的一种调整。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "以下哪项是包容的例子？", "options": ["图书馆里的盲文书", "没有入口的学校", "无视所有学生的老师", "只有部分孩子可以进入的房间"], "answer": 0, "explain": "盲文书帮助盲童在课堂上阅读。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "“包容”是什么意思？", "options": ["把某些人排除在外", "欢迎每一个人", "只欢迎一个群体", "让人们离开"], "answer": 1, "explain": "包容意味着欢迎每一个人，并为每个人留出空间。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "什么是入学名额？", "options": ["汽车里的座位", "睡觉的地方", "学校里为孩子保留的座位", "一家书店"], "answer": 2, "explain": "入学名额是为孩子保留的学习座位。", "src": "UNESCO"}], "4": [{"ch": 0, "q": "第4目标旨在实现什么？", "options": ["为所有人提供优质和终身学习", "只为儿童提供体育", "只为成年人提供工作", "让所有人减少上学"], "answer": 0, "explain": "第4目标旨在为所有人提供包容、优质和终身的学习。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "第4目标有多少个具体目标？", "options": ["5", "10", "17", "169"], "answer": 1, "explain": "第4目标共有10个具体目标：7个成果目标和3个实施手段目标。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "全部17项全球目标共有多少个具体目标？", "options": ["17", "50", "169", "300"], "answer": 2, "explain": "17项全球目标共有169个具体目标。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "哪个目标是关于无贫穷的？", "options": ["目标4", "目标9", "目标12", "目标1"], "answer": 3, "explain": "目标1是“无贫穷”。", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "农村儿童不能上学的常见原因是什么？", "options": ["学校离家太远", "学校离家太近", "公交车太多", "朋友太多"], "answer": 0, "explain": "距离远是上学的常见障碍。", "src": "UNESCO"}, {"ch": 1, "q": "为什么有些家庭让孩子留在家里？", "options": ["他们不想接受教育", "他们需要帮忙干活或挣钱", "上学是非法的", "他们有太多汽车"], "answer": 1, "explain": "有些家庭需要孩子帮忙挣钱或在家里干活。", "src": "UNESCO"}, {"ch": 1, "q": "以下哪一项能帮助农村儿童上学？", "options": ["封闭道路", "没有帮助独自过河", "校车或安全的道路", "待在家里"], "answer": 2, "explain": "交通工具和安全的道路能让农村儿童更容易上学。", "src": "UNESCO"}, {"ch": 1, "q": "什么是学前教育？", "options": ["大学之后的学习", "只在周末的学习", "只在工作场所的学习", "小学之前的学习"], "answer": 3, "explain": "学前教育是小学之前为幼儿提供的学习。", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "为什么安全的校舍很重要？", "options": ["它能保护儿童免受伤害", "它会让上学时间变长", "它会阻碍儿童学习", "它只是用来装饰的"], "answer": 0, "explain": "安全的校舍保护儿童，并让学习成为可能。", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "什么是小学？", "options": ["大学的最后阶段", "学校教育的第一个主要阶段", "只为教师开设", "一种假日营地"], "answer": 1, "explain": "小学通常是正规教育的第一个主要阶段。", "src": "UNESCO"}, {"ch": 2, "q": "什么是中学？", "options": ["幼儿园之前的阶段", "一种体育营地", "小学之后的阶段", "只为成年人开设的地方"], "answer": 2, "explain": "中学紧随小学之后。", "src": "UNESCO"}, {"ch": 2, "q": "哪个因素常常增加早期辍学？", "options": ["好天气", "书太多", "赢得奖项", "贫困"], "answer": 3, "explain": "贫困是儿童早早离开学校的最大原因之一。", "src": "UNESCO"}, {"ch": 2, "q": "完成率是什么意思？", "options": ["完成某一学习阶段的儿童所占的比例", "睡觉的教师所占的比例", "学校铃声的数量", "书包的价格"], "answer": 0, "explain": "完成率是完成某一学习阶段的儿童所占的比例。", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "什么能帮助儿童完成学业？", "options": ["提早关闭学校", "帮助家庭承担费用和交通", "去掉书本", "每天延长考试时间"], "answer": 1, "explain": "对费用和交通的支持有助于儿童留在学校。", "src": "UNESCO"}, {"ch": 2, "q": "学校可以怎么做来保持学生出勤？", "options": ["无视缺勤学生，等他们自己回来", "给缺课的学生减少课程", "跟踪出勤情况并与家庭联系", "每个星期五都提前关校"], "answer": 2, "explain": "学校可以跟踪出勤情况，并与家庭合作以支持学生。", "src": "UNESCO"}, {"ch": 3, "q": "什么是良好的阅读水平？", "options": ["只能阅读数字", "从不朗读", "阅读速度比汽车还快", "能阅读并理解与自己年龄相符的文本"], "answer": 3, "explain": "良好的阅读水平是指能理解与自己年龄相符的简单文本。", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "哪门学科涉及数字、规律和图形？", "options": ["数学", "音乐", "戏剧", "艺术史"], "answer": 0, "explain": "数学是研究数字、规律和图形的学科。", "src": "UNESCO"}, {"ch": 3, "q": "什么是课程？", "options": ["一种校服", "学科的集合以及学生所学的内容", "学校停车场", "一份假期清单"], "answer": 1, "explain": "课程列出了学生在每门学科中应当学习的内容。", "src": "UNESCO"}, {"ch": 3, "q": "为什么用母语学习有帮助？", "options": ["从来没有帮助", "意味着学得更少", "儿童能更好地理解课程", "让学校变短"], "answer": 2, "explain": "当儿童理解课堂所用的语言时，学习会更容易。", "src": "UNESCO, International Mother Language Day"}, {"ch": 3, "q": "教育中的“技能”是什么？", "options": ["会失去的东西", "一种食物", "仅指一门学科", "一个人能做好的事情"], "answer": 3, "explain": "技能是一种可以练习和提高的能力。", "src": "UNESCO"}, {"ch": 4, "q": "解决问题是什么意思？", "options": ["找到解决一个难题的方法", "无视问题", "让问题变得更大", "永远等待他人"], "answer": 0, "explain": "解决问题是指找出回答或修复某件事情的方法。", "src": "UNESCO"}, {"ch": 4, "q": "哪种技能能帮助你向小组清楚地分享自己的想法？", "options": ["藏起你的声音", "向小组清晰地发言", "说话非常小声", "从不发言"], "answer": 1, "explain": "演示能帮助你向他人清楚地分享自己的想法。", "src": "UNESCO"}, {"ch": 4, "q": "什么是领导力？", "options": ["命令他人保持安静", "独占所有功劳", "以有益的方式引导他人", "逃避责任"], "answer": 2, "explain": "领导力是帮助和引导他人朝着一个目标前进。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "什么是数字素养？", "options": ["利用科技去破坏东西", "从不使用电脑", "只写信", "利用科技查找和分享信息"], "answer": 3, "explain": "数字素养是指安全地使用数字工具来学习和交流。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "什么是职业技能？", "options": ["木工等实用的职业技能", "睡觉的技能", "逃避工作的技能", "躲藏的技能"], "answer": 0, "explain": "职业技能是在工作或行业中使用的实用技能。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "学校中的性别平等是什么意思？", "options": ["只有男孩能学习", "女孩和男孩拥有平等的机会", "只有女孩能学习", "女孩必须待在家里"], "answer": 1, "explain": "性别平等是指女孩和男孩在教育中拥有平等的权利和机会。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "第4目标提到哪个群体需要平等的入学机会？", "options": ["只有个子高的人", "只有城市里的人", "残疾人", "只有喜欢运动的人"], "answer": 2, "explain": "第4目标提到残疾人是需要平等获得教育机会的群体之一。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "为什么女孩有时会缺课？", "options": ["女孩不喜欢学习", "学校时间太短", "女孩的书太多", "早婚、做家务或出行不安全"], "answer": 3, "explain": "早婚、家务劳动和不安全的出行都可能使女孩无法上学。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "教育中的弱势群体是什么？", "options": ["面临更多学习障碍的群体", "从不学习的群体", "只会阅读的群体", "非常富有的群体"], "answer": 0, "explain": "弱势群体面临更多障碍，因此可能需要额外的支持。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "什么是原住民社区？", "options": ["一种校舍", "最早在某地生活的人群", "一种教师", "一种书包"], "answer": 1, "explain": "原住民是某一地区的原始居民，通常拥有自己的语言和文化。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "什么是对女孩友好的学校？", "options": ["城市里专为女孩开设的学校", "不允许女孩入学的学校", "有安全厕所且没有骚扰的学校", "只教舞蹈的学校"], "answer": 2, "explain": "对女孩友好的学校安全、设施完善，教师也尊重学生。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 6, "q": "为什么学校需要足够的教师？", "options": ["不需要教师", "让儿童停止学习", "让学校提早结束", "让每个班级都有教师授课"], "answer": 3, "explain": "教师充足意味着每个班级都能得到良好的教学。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是合格教师？", "options": ["接受过教学培训的教师", "没有接受过培训的教师", "只会讲笑话的教师", "从不教课的教师"], "answer": 0, "explain": "合格教师具备履行其工作所需的培训。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么能帮助教师留在岗位上？", "options": ["长时间工作且没有休息", "公平的薪酬和良好的工作条件", "完全没有支持", "每天被调到很远的地方"], "answer": 1, "explain": "公平的薪酬和良好的工作条件有助于教师留在这一职业。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是导师型教师？", "options": ["逃跑的教师", "只是坐着的教师", "帮助新教师的经验丰富的教师", "只写诗的教师"], "answer": 2, "explain": "导师指导新教师，帮助他们不断提高。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "为什么教师需要了解学生？", "options": ["为了布置更多家庭作业", "为了停止教学", "为了避开家长", "为了以帮助每个孩子的方式教学"], "answer": 3, "explain": "了解学生有助于教师规划适合他们的课程。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "什么是公立学校？", "options": ["由政府资金资助的学校", "只卖食物的学校", "只由一个家庭经营的学校", "没有学生的学校"], "answer": 0, "explain": "公立学校主要由公共资金资助。", "src": "UNESCO"}, {"ch": 7, "q": "什么是教育预算？", "options": ["假期日期清单", "为教育规划的资金", "一种关于金钱的游戏", "校服的价格"], "answer": 1, "explain": "教育预算是政府计划用于学校的资金。", "src": "UNESCO"}, {"ch": 7, "q": "学校资金太少时会发生什么？", "options": ["出现更多教师", "书变得更便宜", "教师和书籍减少", "学校变得更大"], "answer": 2, "explain": "资金有限可能意味着教师和学习材料减少。", "src": "UNESCO"}, {"ch": 7, "q": "即使学费免费，家庭仍可能承担哪些费用？", "options": ["完全没有", "只有空气", "只有阳光", "校服、交通和学习用品"], "answer": 3, "explain": "即使学费免费，家庭仍可能需要支付校服、交通和学习用品的费用。", "src": "UNESCO"}, {"ch": 7, "q": "什么是学校补助金？", "options": ["为帮助学校或学生而提供的资金", "迟交家庭作业的罚款", "一种考试", "仅指校车车票"], "answer": 0, "explain": "补助金是为帮助学校或学生而提供的资金，通常无需偿还。", "src": "UNESCO"}, {"ch": 8, "q": "千年发展目标是哪一年开始的？", "options": ["1948", "2000", "1990", "2015"], "answer": 1, "explain": "千年发展目标始于2000年。", "src": "UN Millennium Development Goals (2000)"}, {"ch": 8, "q": "1990年各国在哪里集会，启动了“全民教育”运动？", "options": ["法国巴黎", "埃及开罗", "泰国朱莫提恩（Jomtien）", "日本东京"], "answer": 2, "explain": "1990年各国在泰国朱莫提恩集会，启动了“全民教育”。", "src": "UNESCO"}, {"ch": 8, "q": "2000年在达喀尔设定教育目标的框架是什么？", "options": ["达喀尔足球规则", "达喀尔路线图", "达喀尔食品计划", "《达喀尔行动框架》"], "answer": 3, "explain": "《达喀尔行动框架》于2000年在世界教育论坛上通过。", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "哪份文件规定小学教育应当是义务且免费的？", "options": ["《联合国儿童权利公约》", "列出一周午餐选择的学校菜单", "巴厘岛最佳海滩的旅游指南", "学校足球比赛的体育规则手册"], "answer": 0, "explain": "第28条规定，小学教育应当对所有人实行义务和免费。", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 8, "q": "2015年的教育协议叫什么名字？", "options": ["《东京宣言》", "《仁川宣言》", "《开罗公约》", "《利马计划》"], "answer": 1, "explain": "2015年的《仁川宣言》确定了2030年的教育目标。", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 9, "q": "年幼的儿童通常如何学习？", "options": ["通过长时间的考试", "通过数小时的安静", "通过游戏、歌曲和故事", "通过夜班工作"], "answer": 2, "explain": "早期学习通常通过游戏、歌曲和故事进行。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "为什么生命的头几年对大脑很重要？", "options": ["大脑停止生长", "大脑不会改变", "大脑只在夜间生长", "大脑生长非常迅速"], "answer": 3, "explain": "大脑在早年发育非常迅速。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "幼儿照护包括什么？", "options": ["健康、营养和学习", "只包括睡眠", "只包括体育", "只包括金钱"], "answer": 0, "explain": "幼儿照护同时支持健康、饮食和学习。", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "什么是托儿所？", "options": ["只用来种树的地方", "照护非常幼小儿童的地方", "用来寄信的地方", "用来造汽车的地方"], "answer": 1, "explain": "托儿所照护非常幼小的儿童，并帮助他们学习。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "什么活动能帮助幼儿学习词语？", "options": ["整天保持安静", "只看广告", "给物品命名并与之交谈", "被关在黑暗的房间里"], "answer": 2, "explain": "交谈和为事物命名有助于幼儿建立语言能力。", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "什么是识字率？", "options": ["书的价格", "图书馆的数量", "教师的数量", "能读写的人所占的比例"], "answer": 3, "explain": "识字率表示能读写的人所占的比例。", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "为什么成年人需要识字？", "options": ["为了阅读工作说明和健康信息", "为了在工厂里完全不工作", "为了赢得学校比赛的每一场胜利", "为了毕业后不再学习新事物"], "answer": 0, "explain": "阅读能帮助成年人工作、保持健康并参与社会生活。", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "教室里的阅读角是什么？", "options": ["放鞋子的地方", "摆放书籍供阅读的空间", "只用来吃午饭的地方", "存放自行车的地方"], "answer": 1, "explain": "阅读角为儿童提供阅读和享受书籍的地方。", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "什么能帮助阅读有困难的孩子？", "options": ["减少阅读时间", "被告知他们不聪明", "额外的阅读帮助和练习", "从不给他们书"], "answer": 2, "explain": "额外的帮助和练习可以帮助孩子赶上进度。", "src": "UNESCO GEM Report 2026"}, {"ch": 11, "q": "什么是包容性教育？", "options": ["只为最优秀学生提供的教育", "只为一个群体提供的教育", "没有教师的教育", "欢迎所有学习者的教育"], "answer": 3, "explain": "包容性教育欢迎所有学习者，并为他们提供支持。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "为什么学校需要坡道和无障碍卫生间？", "options": ["让每个人都能使用学校", "让儿童跑得更快", "让学校看起来更高", "让课堂时间更短"], "answer": 0, "explain": "无障碍建筑让每个人都能使用学校设施。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "手语在学校里用来做什么？", "options": ["只用于跳舞", "与聋哑学生沟通", "只用于烹饪", "只用于数学测验"], "answer": 1, "explain": "手语帮助聋哑学生沟通和学习。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "谁能从包容性学校中受益？", "options": ["只有教师", "只有家长", "学校里的每个人", "只有校长"], "answer": 2, "explain": "包容性学校帮助每个孩子共同学习和成长。", "src": "UN CRPD (2006), Article 24"}, {"ch": 3, "q": "什么是教案？", "options": ["夏季家庭假期的计划", "学校食堂出售的零食清单", "显示学校教室和走廊的地图", "显示将教什么以及如何教的计划"], "answer": 3, "explain": "教案规定了一节课的目标和步骤。", "src": "UNESCO Global Report on Teachers (2024)"}], "5": [{"ch": 0, "q": "第4目标有多少个成果目标？", "options": ["七个", "三个", "十个", "十七个"], "answer": 0, "explain": "第4目标有七个成果目标，编号为4.1至4.7。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "第4目标的三个“实施手段”目标叫什么？", "options": ["4.1、4.2和4.3", "4.a、4.b和4.c", "4.5、4.6和4.7", "4.8、4.9和4.10"], "answer": 1, "explain": "目标4.a、4.b和4.c涵盖设施、奖学金和教师。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "哪项全球目标是性别平等？", "options": ["目标2", "目标8", "目标5", "目标11"], "answer": 2, "explain": "目标5是性别平等。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "“不让任何人掉队”是什么意思？", "options": ["把进展最慢的人排除在外", "只帮助富裕国家", "停止一切援助", "包括最被忽视的人群"], "answer": 3, "explain": "《2030年议程》承诺优先惠及最落后的人群。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "为什么全球目标被称为“全球”？", "options": ["适用于所有国家", "只适用于一个国家", "只适用于学校", "只适用于体育"], "answer": 0, "explain": "全球目标适用于每一个国家，无论贫富。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "全球目标的目标年份是哪一年？", "options": ["2015", "2030", "2050", "2100"], "answer": 1, "explain": "全球目标计划在2030年前实现。", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "在许多国家，哪类儿童最有可能不在学校上学？", "options": ["喜欢阅读的儿童", "踢足球的儿童", "冲突地区的儿童", "经常去图书馆的儿童"], "answer": 2, "explain": "冲突和危机地区的儿童往往最难上学。", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "“失学”是什么意思？", "options": ["在图书馆学习", "周日去上学", "赢得学校奖项", "没有在任何学校注册"], "answer": 3, "explain": "失学儿童是指没有在任何学校注册的儿童。", "src": "UNESCO"}, {"ch": 1, "q": "为什么许多儿童不去上学而去工作？", "options": ["家庭需要他们的收入", "他们更喜欢工作", "学校是免费的", "学校里教授工作技能"], "answer": 0, "explain": "贫困家庭可能需要儿童工作以赚取收入。", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "什么是童工？", "options": ["放学后在家与朋友安静地玩耍", "损害儿童健康或中断其学业的工作", "在家帮助父母做作业和简单的家务", "为年幼的弟弟或妹妹大声朗读故事"], "answer": 1, "explain": "童工是损害儿童并使其无法学习的工作。", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "什么是学校供餐计划？", "options": ["在商店出售的食物", "一种学校体育项目", "在学校为儿童提供的餐食", "一个美食节"], "answer": 2, "explain": "学校餐食可以鼓励儿童上学和学习。", "src": "UNESCO"}, {"ch": 1, "q": "为什么学校餐食能帮助儿童？", "options": ["它们使儿童停止学习", "它们拿走了所有的钱", "它们取代了书本", "它们鼓励儿童上学"], "answer": 3, "explain": "餐食可以让儿童更容易到校并集中注意力。", "src": "UNESCO"}, {"ch": 2, "q": "从小学过渡到中学是什么意思？", "options": ["从一个学段升入下一个学段", "只是搬家", "在同一个班级里换座位", "永远离开学校"], "answer": 0, "explain": "过渡是指从学校的一个阶段进入下一个阶段。", "src": "UNESCO"}, {"ch": 2, "q": "为什么有些儿童要留级？", "options": ["留级总是像放假", "他们需要更多时间来掌握学习内容", "留级是一种奖励", "他们朋友太多"], "answer": 1, "explain": "当儿童需要更多时间学习时，有些人会留级一年。", "src": "UNESCO"}, {"ch": 2, "q": "“毕业”是什么意思？", "options": ["开始去新学校", "搬到另一个国家", "完成某个教育阶段", "停止上课"], "answer": 2, "explain": "毕业是指成功完成某个学习阶段。", "src": "UNESCO"}, {"ch": 2, "q": "完成中学教育的目的是什么？", "options": ["只是为了获得假期", "只是为了逃避考试", "只是为了停止阅读", "获得工作和继续深造所需的技能"], "answer": 3, "explain": "中等教育培养工作和继续深造所需的技能。", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "学校里的“留校率”是什么意思？", "options": ["让学生留在学校直到完成学业", "把学生关在箱子里", "永久保存书本", "让学校一直关闭"], "answer": 0, "explain": "留校率是指学生留在学校直到完成该学段。", "src": "UNESCO"}, {"ch": 2, "q": "哪个因素有助于学生留在学校？", "options": ["被迫离开学校", "安全的上学路线", "没有书本", "错过每一次考试"], "answer": 1, "explain": "安全的路线让儿童更容易留在学校。", "src": "UNESCO"}, {"ch": 3, "q": "“学习评估”是什么意思？", "options": ["测量学校建筑", "数桌子", "衡量学生学到了什么", "数教师的汽车"], "answer": 2, "explain": "学习评估检查学生知道什么、能做什么。", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "什么是“学习贫困”？", "options": ["课堂作业没有铅笔或笔记本", "家里没有电脑做作业", "住得离最近的图书馆很远", "到十岁时无法阅读一篇简单的文章"], "answer": 3, "explain": "学习贫困是指儿童到十岁时无法阅读和理解一篇简单的文章。", "src": "World Bank, learning poverty"}, {"ch": 3, "q": "什么是基础技能？", "options": ["阅读或计数等基本技能", "一门困难的大学课程", "一种体育运动", "一种音乐"], "answer": 0, "explain": "阅读和计数等基础技能支撑着此后的所有学习。", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "为什么早期阅读很重要？", "options": ["它只对美术有帮助", "它支持每个学科的学习", "学校里不需要它", "它只对体育有帮助"], "answer": 1, "explain": "阅读能力强的儿童在每个学科中都能更轻松地学习。", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "什么是形成性评价？", "options": ["只有期末考试", "测量学生身高的测试", "在课堂中检查学习情况", "测试烹饪技能"], "answer": 2, "explain": "形成性评价帮助教师检查进度并调整课程。", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "什么是总结性评价？", "options": ["只在开始时提出的问题", "不计分的游戏", "每天早上进行的测试", "单元或学年结束时的测试"], "answer": 3, "explain": "总结性评价在一个阶段结束时衡量学习成果。", "src": "UNESCO GEM Report 2026"}, {"ch": 4, "q": "学习中的“创造力”是什么？", "options": ["提出新颖而有用的想法", "一模一样地照搬", "只使用旧的想法", "避免所有想法"], "answer": 0, "explain": "创造力是指找到新颖而有用的思考和做事方式。", "src": "UNESCO"}, {"ch": 4, "q": "哪种技能能帮你与不同文化背景的人合作？", "options": ["躲避差异", "跨文化理解", "拒绝交流", "无视其他语言"], "answer": 1, "explain": "跨文化理解有助于人们尊重他人并与之合作。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "什么是“韧性”？", "options": ["在第一个挑战面前放弃", "从不面对问题", "在困难之后重新振作", "避免一切新事物"], "answer": 2, "explain": "韧性是指从困难时刻中恢复并学习。", "src": "UNESCO"}, {"ch": 4, "q": "为什么一些学校教授生活技能？", "options": ["用美术课取代所有数学课", "让所有人的上学时间变长", "取消学年中的所有考试", "帮助学生应对日常挑战"], "answer": 3, "explain": "生活技能帮助学生做出良好决定并处理日常问题。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "什么是财务素养？", "options": ["理解金钱以及如何管理金钱", "仅为了好玩而收集硬币", "忽视价格", "一次性花光所有钱"], "answer": 0, "explain": "财务素养意味着懂得如何明智地使用和储蓄金钱。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "哪种技能能帮你利用来自多种来源的信息？", "options": ["唱歌", "研究能力", "杂耍", "只会园艺"], "answer": 1, "explain": "研究能力帮助学生查找并核实信息。", "src": "UNESCO"}, {"ch": 5, "q": "什么是性别均等指数？", "options": ["衡量学校高度的指标", "统计教师宠物的数量", "比较女孩与男孩入学人数的数字", "学校校色的列表"], "answer": 2, "explain": "性别均等指数接近1，意味着女孩和男孩的入学人数相当。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "性别均等指数为1意味着什么？", "options": ["没有女孩上学", "只有女孩上学", "男孩人数是女孩的两倍", "女孩和男孩人数相等"], "answer": 3, "explain": "数值为1表示女孩和男孩的入学人数相等。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "哪个群体可能因残疾而面临额外障碍？", "options": ["残障儿童", "喜欢画画的儿童", "喜欢玩游戏的儿童", "戴眼镜的儿童"], "answer": 0, "explain": "没有支持的情况下，残障儿童可能面临额外的障碍。", "src": "UN CRPD (2006), Article 24"}, {"ch": 5, "q": "学校中的“歧视”是什么？", "options": ["对每个人的公平对待", "因某人的身份而受到的不公平对待", "根据颜色选择书本", "给所有人布置相同的作业"], "answer": 1, "explain": "歧视是基于一个人所属群体或背景的不公平对待。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "为什么学校应当远离暴力？", "options": ["暴力帮助儿童集中注意力", "暴力是学校生活的正常部分", "暴力会阻碍儿童学习", "暴力会让儿童变得更强大"], "answer": 2, "explain": "儿童在感到不安全时无法很好地学习。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "包容性政策起什么作用？", "options": ["对某些群体关闭学校", "让学校只为富人开设", "取消所有教师", "让所有群体都能接受教育"], "answer": 3, "explain": "包容性政策帮助所有群体获得教育并从中受益。", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "什么是“师生比”？", "options": ["每位教师教多少名学生", "有多少教师领取工资", "一间房里有多少张课桌", "一位教师走访多少所学校"], "answer": 0, "explain": "师生比表示一位教师需要照顾多少名学习者。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "为什么较低的师生比很重要？", "options": ["教师无事可做", "教师能够更多地关注每个孩子", "意味着课堂更吵", "让教师更富有"], "answer": 1, "explain": "班级规模较小，教师能更好地帮助每个孩子。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是教师的积极性？", "options": ["睡觉就能拿工资", "尽可能少工作", "把课教好的动力和热情", "回避学生"], "answer": 2, "explain": "有积极性的教师更有可能留下来并把课教好。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "为什么教师培训很重要？", "options": ["它取代课程", "它消除了对学生的需要", "它只增加假期", "它提高教学质量"], "answer": 3, "explain": "良好的培训帮助教师以有效的方式教学。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是教师教育学院？", "options": ["培训教师的地方", "只出售教学材料的地方", "为宠物开设的学校", "修建道路的地方"], "answer": 0, "explain": "教师教育学院培养人们成为教师。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么能支持农村地区的教师？", "options": ["完全没有支持", "住房、交通和培训", "每天被调走", "更少的工资和更多的工作"], "answer": 1, "explain": "住房和交通等支持有助于教师服务农村社区。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "什么是教育的公共支出？", "options": ["家庭在玩具上的花费", "只花在体育上的资金", "政府在学校上花费的资金", "只花在道路上的资金"], "answer": 2, "explain": "教育公共支出是政府用于经营学校的资金。", "src": "UNESCO"}, {"ch": 7, "q": "什么是学校教育券？", "options": ["一种校服", "博物馆门票", "公交线路图", "一种支付学费的帮助形式"], "answer": 3, "explain": "在一些国家，教育券可以帮助家庭支付学校费用。", "src": "UNESCO"}, {"ch": 7, "q": "哪项费用可能使贫困儿童无法上学？", "options": ["学费和校服", "免费的书本", "免费的餐食", "免费的交通"], "answer": 0, "explain": "学费和校服对一些家庭来说可能过于昂贵。", "src": "UNESCO"}, {"ch": 7, "q": "免费教育通常意味着什么？", "options": ["免费假期", "没有学费", "免费汽车", "免费糖果"], "answer": 1, "explain": "免费教育通常意味着没有学费，但可能仍有其他费用。", "src": "UNESCO"}, {"ch": 8, "q": "“全民教育”是哪一年在朱莫提恩达成共识的？", "options": ["1948", "1989", "1990", "2000"], "answer": 2, "explain": "“全民教育”于1990年在朱莫提恩达成共识。", "src": "UNESCO"}, {"ch": 8, "q": "2000年的达喀尔框架旨在实现什么？", "options": ["只为成年人提供教育", "完全没有学校", "只在城市提供教育", "到2015年实现全民教育"], "answer": 3, "explain": "达喀尔框架设定了到2015年实现全民教育的目标。", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "哪项千年发展目标涉及普及小学教育？", "options": ["目标2", "目标1", "目标5", "目标8"], "answer": 0, "explain": "千年发展目标2旨在实现普及小学教育。", "src": "UN Millennium Development Goals (2000)"}, {"ch": 8, "q": "什么是世界教育论坛？", "options": ["亚洲两支国家队之间的足球比赛", "各国和合作伙伴讨论教育的聚会", "面向学生和家庭的烹饪比赛", "面向年轻导演和演员的电影节"], "answer": 1, "explain": "世界教育论坛汇集各国和合作伙伴，共同讨论教育问题。", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "哪项框架支持《仁川宣言》？", "options": ["《2030体育框架》", "《2030烹饪计划》", "《2030教育行动框架》", "《2030音乐计划》"], "answer": 2, "explain": "《2030教育行动框架》指导各国实现可持续发展目标4。", "src": "Incheon Framework for Action (2015)"}, {"ch": 8, "q": "千年发展目标是哪一年结束的？", "options": ["2000", "2030", "2010", "2015"], "answer": 3, "explain": "千年发展目标于2015年结束，之后由全球目标接替。", "src": "UN Millennium Development Goals (2000)"}, {"ch": 9, "q": "什么是幼儿发展？", "options": ["从出生起在健康、学习和福祉方面的成长", "只是身高和体重年复一年地增长", "多年后才在大学里学习", "每天只在户外玩耍"], "answer": 0, "explain": "幼儿发展涵盖从出生起的健康、学习和福祉。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "幼儿期的“回应式互动”是什么？", "options": ["夏天在草地球场上进行的一种网球比赛", "儿童与成人之间的来回互动", "把玩具送回当地慈善商店的方式", "婴儿每天下午都会有的一种长时间睡眠"], "answer": 1, "explain": "回应式互动是建立大脑的来回互动。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "为什么幼儿需要有回应的成年人？", "options": ["不需要成年人", "成年人只会发号施令", "他们从中学习语言和情感", "成年人应该保持沉默"], "answer": 2, "explain": "有回应的成年人帮助儿童建立语言、情感和思维能力。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "SDG 4 的哪项具体目标涉及幼儿期？", "options": ["目标4.1", "目标4.6", "目标4.c", "目标4.2"], "answer": 3, "explain": "目标4.2涉及幼儿发展、照护和学前教育。", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "学前教育的作用是什么？", "options": ["为幼儿进入小学做准备", "为他们进入大学做准备", "取代小学教育", "让儿童去工作"], "answer": 0, "explain": "学前教育让幼儿在进入小学之前获得技能。", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "为什么营养在幼儿期很重要？", "options": ["食物对大脑没有影响", "良好的饮食支持健康的大脑发育", "儿童只需要糖果", "儿童每周只应进食一次"], "answer": 1, "explain": "健康的食物在快速成长期间支持大脑和身体。", "src": "UN 2030 Agenda (2015)"}, {"ch": 10, "q": "什么是功能性识字？", "options": ["只为了好玩而阅读杂志和漫画", "只为学校演出而写诗和歌曲", "读写能力足以应对日常生活", "只阅读账单和票据上印的数字"], "answer": 2, "explain": "功能性识字是指读写能力足以完成日常事务。", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "目标4.6的核心是哪两项基本技能？", "options": ["唱歌和绘画", "烹饪和驾驶", "步行和跑步", "读写和计算"], "answer": 3, "explain": "目标4.6旨在使青年和成年人掌握读写和计算能力。", "src": "UN 2030 Agenda (2015)"}, {"ch": 10, "q": "图书馆为什么有助于提高读写能力？", "options": ["免费提供书籍", "只出售昂贵的书", "对儿童关闭", "只存放家具"], "answer": 0, "explain": "图书馆让人们免费获取书籍和阅读场所。", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "什么是阅读流畅度？", "options": ["读而不理解", "流利而准确地阅读", "倒着读", "只能默读"], "answer": 1, "explain": "流畅度是指阅读时流利、准确并富有表现力。", "src": "UNESCO GEM Report 2026"}, {"ch": 11, "q": "学校里的资源室是什么？", "options": ["只存放旧家具的房间", "出售校服的房间", "为需要帮助的学生提供额外帮助的房间", "存放体育奖杯的房间"], "answer": 2, "explain": "资源室为有学习或残疾需求的学生提供额外支持。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "“通用设计”对学校意味着什么？", "options": ["一座城市只有一种建筑", "没有门的建筑", "只供动物使用的建筑", "适合所有人使用的建筑和工具"], "answer": 3, "explain": "通用设计使建筑和工具能被尽可能多的人使用。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "为什么残障儿童有时需要辅助设备？", "options": ["帮助儿童听、看或活动", "让儿童入睡", "取代教师", "阻碍儿童学习"], "answer": 0, "explain": "助听器或轮椅等辅助设备帮助儿童参与学校生活。", "src": "UN CRPD (2006), Article 24"}], "6": [{"ch": 0, "q": "下列哪个具体目标涉及免费、公平且优质的小学和中学教育？", "options": ["目标4.1", "目标4.2", "目标4.4", "目标4.7"], "answer": 0, "explain": "目标4.1旨在提供免费、公平且优质的小学和中学教育。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "哪个目标提到了就业所需的技术和职业技能？", "options": ["目标4.1", "目标4.4", "目标4.5", "目标4.b"], "answer": 1, "explain": "目标4.4关注技能，包括就业所需的技术和职业技能。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "哪个目标涉及发展中国家学生的奖学金？", "options": ["目标4.a", "目标4.c", "目标4.b", "目标4.6"], "answer": 2, "explain": "目标4.b呼吁为发展中国家学生提供更多奖学金。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "哪个目标涉及合格教师的供应？", "options": ["目标4.b", "目标4.2", "目标4.7", "目标4.c"], "answer": 3, "explain": "目标4.c旨在增加合格教师的供应。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "哪个目标涉及教育设施的建设和改善？", "options": ["目标4.a", "目标4.1", "目标4.3", "目标4.5"], "answer": 0, "explain": "目标4.a呼吁建设安全、包容和有效的学习设施。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "目标4.7是关于什么的？", "options": ["只涉及整个学年的体育、游戏和体能", "可持续发展和全球公民身份所需的知识与技能", "只涉及成年人的金钱、银行和企业账户", "只涉及学校食堂的烹饪、食品和营养"], "answer": 1, "explain": "目标4.7涵盖可持续发展、人权、性别平等和全球公民身份。", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "哪个目标关注幼儿早期发展和学前教育？", "options": ["目标4.1", "目标4.6", "目标4.2", "目标4.c"], "answer": 2, "explain": "目标4.2涉及幼儿早期发展、保育和学前教育。", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "目标4.1中的“公平”是什么意思？", "options": ["只针对国家最富裕的家庭", "只针对生活在大城市的人", "只针对已经完成学业的成年人", "对所有人公平，包括最弱势群体"], "answer": 3, "explain": "公平的教育惠及每个人，包括处于不利地位的人。", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "目标4.5中哪个群体被列为需要平等获得教育的对象？", "options": ["原住民", "只有有钱人", "只有大城市的人", "只有会说一种语言的人"], "answer": 0, "explain": "目标4.5提到残疾人、原住民以及处于弱势境地的儿童。", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "为什么免费小学教育很重要？", "options": ["它会提高学费", "它消除了贫困家庭的一大障碍", "它会让孩子停止学习", "它会让学校变得没用"], "answer": 1, "explain": "免费小学教育帮助无力支付费用的家庭。", "src": "UNESCO"}, {"ch": 1, "q": "普及小学教育是什么意思？", "options": ["只有部分孩子上小学", "只有成年人上小学", "每个孩子都能上小学", "小学对所有人都是可选的"], "answer": 2, "explain": "普及小学教育意味着每个孩子都有小学的学位。", "src": "UN Millennium Development Goals (2000)"}, {"ch": 1, "q": "即使免除了学费，哪些孩子可能仍然失学？", "options": ["个子很高的儿童", "喜欢阅读的儿童", "从不吃饭的儿童", "残疾儿童或偏远地区的儿童"], "answer": 3, "explain": "费用并非唯一障碍；残疾、距离和歧视也会让孩子失学。", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "追踪完成率的目的是什么？", "options": ["了解孩子是否完成学业", "为学校远足选择最好的度假地点", "在当地商店卖出更多教科书", "测量每间教室里课桌的大小"], "answer": 0, "explain": "完成率显示孩子是否读完了每个学段。", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "为什么中学完成率很重要？", "options": ["它显示有多少教师在睡觉", "它显示朝目标4.1的进展", "它显示书包的价格", "它显示天气"], "answer": 1, "explain": "完成率有助于追踪第4目标的进展。", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "什么是第二次机会教育？", "options": ["只有完成大学学位后才能学习", "只通过场上的体育和游戏学习", "为错过学业的人提供的学习机会", "当今大多数国家禁止的学习"], "answer": 2, "explain": "第二次机会教育帮助人们补上错过的学习内容。", "src": "UNESCO"}, {"ch": 2, "q": "什么是衔接项目？", "options": ["在河流和道路上建造桥梁的项目", "每年关闭偏远村庄学校的项目", "为所有人提供的周末体育和游戏项目", "帮助学习者在不同学段或体系之间过渡的项目"], "answer": 3, "explain": "衔接项目帮助学习者在学校与培训之间顺利过渡。", "src": "UNESCO"}, {"ch": 2, "q": "为什么学生会在初中辍学？", "options": ["费用、工作和距离", "他们学得太快了", "他们得到的奖品太多", "他们没有家庭作业"], "answer": 0, "explain": "费用、工作和距离是学生提前离开学校的常见原因。", "src": "UNESCO"}, {"ch": 2, "q": "什么能帮助辍学的学生重返学校？", "options": ["永久开除", "灵活的课程和支持", "被迫留级重读同一学年", "教师的惩罚"], "answer": 1, "explain": "灵活的课程和支持帮助学生重新开始学习。", "src": "UNESCO"}, {"ch": 3, "q": "目标4.1旨在实现哪种学习？", "options": ["只要字迹工整", "只要体育成绩好", "相关且有效的学习", "只要阅读更快"], "answer": 2, "explain": "目标4.1追求相关且有效的学习成果，而不只是出勤。", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "为什么衡量学习比统计出勤更难？", "options": ["学习总是很容易统计", "出勤永远无法统计", "学习只能通过身高来衡量", "学习必须加以评估，而不只是统计"], "answer": 3, "explain": "出勤只能说明人在场，而学习需要评估技能和理解。", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "什么是最低熟练水平？", "options": ["学习者应该达到的最低水平", "学习的最高水平", "仅供教师使用的水平", "针对学校建筑的水平"], "answer": 0, "explain": "最低熟练水平是所有学习者都应达到的基本技能水平。", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "为什么许多国家要测试阅读和数学？", "options": ["用来选择午餐", "查看学习者是否达到基本技能", "用来查看天气", "用来决定假期"], "answer": 1, "explain": "测试显示学习者是否达到了必要的基本技能。", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "什么是学习公平？", "options": ["只有最优秀的学生才能学习", "无论需要什么，每个人都得到完全相同的支持", "每位学习者都有公平的机会学好", "学习只发生在部分学校"], "answer": 2, "explain": "学习公平意味着在需要的地方提供更多支持。", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "哪种技能能把字母与读音联系起来，帮助儿童阅读？", "options": ["杂耍", "绘画", "只会跳舞", "拼读法"], "answer": 3, "explain": "拼读法把字母与读音联系起来，帮助儿童阅读。", "src": "UNESCO GEM Report 2026"}, {"ch": 4, "q": "什么是计算思维？", "options": ["把问题分解成步骤来解决", "凡事都用计算器", "靠猜测得出答案", "回避谜题"], "answer": 0, "explain": "计算思维把问题分解为步骤，这是编程及其他领域都有用的技能。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "什么是创业教育？", "options": ["学习睡个好觉并在白天休息", "学习创办和经营企业或项目", "学习逃避工作并待在家里", "学习每周在合唱团唱歌"], "answer": 1, "explain": "创业教育帮助学习者创造并管理自己的想法。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "什么是全球公民身份？", "options": ["只生活在一个小镇", "拒绝了解其他国家", "理解并关心更广阔的世界", "无视他人"], "answer": 2, "explain": "全球公民身份鼓励人们理解并尊重更广阔的世界。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "哪种技能能帮助人判断新闻是否属实？", "options": ["杂耍", "园艺", "烹饪", "媒介素养"], "answer": 3, "explain": "媒介素养帮助人们核查来自不同来源的信息。", "src": "UNESCO"}, {"ch": 4, "q": "学习中的协作是什么？", "options": ["为了共同目标而合作", "独自努力以击败他人", "抄袭同学", "回避小组任务"], "answer": 0, "explain": "协作意味着学习者共同努力并分担责任。", "src": "UNESCO"}, {"ch": 4, "q": "目标4.7中的和平文化是什么意思？", "options": ["与他人隔绝地生活", "不使用暴力地共同生活", "赢得每一场争论", "忽视其他文化"], "answer": 1, "explain": "和平文化倡导非暴力、尊重和理解。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "哪个因素可能使女孩无法完成中等教育？", "options": ["好天气", "免费书籍", "早婚和家务劳动", "教师太多"], "answer": 2, "explain": "早婚和家务劳动可能妨碍女孩完成中等教育。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "什么是分类数据？", "options": ["永远对公众保密的数据", "从来不用于做决策的数据", "每天该地区天气的数据", "按性别或残疾等群体划分的数据"], "answer": 3, "explain": "分类数据有助于揭示谁被落下了。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "为什么分类数据有用？", "options": ["它显示哪些群体需要帮助", "它掩盖问题", "它从来都不准确", "它只帮助企业"], "answer": 0, "explain": "按群体划分数据可以看出需要支持的地方。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "什么是与学校有关的基于性别的暴力？", "options": ["体育比赛中关于如何铲抢的规则", "发生在学校内外、与性别相关的暴力", "年底进行的一种考试", "持续两整周的学校假期"], "answer": 1, "explain": "这种暴力与性别有关，会损害儿童的学习。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "学校可以做些什么来保护儿童免受暴力？", "options": ["无视学生和家长的投诉", "惩罚向工作人员报告问题的儿童", "建立安全的举报制度并培训员工", "每次有投诉就关闭学校"], "answer": 2, "explain": "安全的举报制度和员工培训有助于保护儿童。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "什么是安全的学习环境？", "options": ["没有教师的地方", "完全没有规则的地方", "学生总是独自一人的地方", "学生感到安全、可以放心学习的地方"], "answer": 3, "explain": "安全的学习环境让学生无所畏惧地学习。", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "为什么公平支付教师薪酬很重要？", "options": ["它有助于让合格教师留在学校", "它会让学校变得更穷", "它会减少学习", "它会让教师不再关心"], "answer": 0, "explain": "公平的薪酬有助于留住受过培训的教师。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是教师流失？", "options": ["教师获得晋升", "教师离开这一职业", "教师休假", "教师获得奖项"], "answer": 1, "explain": "教师流失指教师离开这一职业，这会损害学习。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是教师职业发展路径？", "options": ["只通向校门的道路", "只为学生设计的道路", "一条通向成长和晋升的道路", "没有薪水的道路"], "answer": 2, "explain": "职业发展路径为教师提供成长和进步的途径。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是教师的持续专业发展？", "options": ["一生只有一天的培训", "毕业后不再接受培训", "只针对校长的培训", "教学生涯中持续进行的培训"], "answer": 3, "explain": "持续的专业发展使教师在整个职业生涯中保持技能。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "为什么教师质量很重要？", "options": ["它是影响儿童学习成效的关键因素之一", "它对儿童的学习完全没有影响", "它只关系到体育和体育教育", "它只关系到校舍的外观"], "answer": 0, "explain": "教师质量是影响儿童学习成效的关键因素之一。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "为什么偏远地区往往难以留住教师？", "options": ["偏远地区的教师太多", "愿意到那里工作的教师太少", "教师更喜欢假期", "教师从不外出"], "answer": 1, "explain": "偏远地区往往难以吸引并留住足够的教师。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "什么是教育的国内融资？", "options": ["来自月球的资金", "只来自体育俱乐部的资金", "国家自行为学校筹集的资金", "只来自校服的资金"], "answer": 2, "explain": "国内融资是国家通过自身税收和收入筹集的资金。", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "《仁川行动框架》建议教育支出占国内生产总值的比例是多少？", "options": ["0.5%至1%", "20%至30%", "50%至60%", "4%至6%"], "answer": 3, "explain": "《仁川行动框架》建议教育支出占国内生产总值的4%至6%和/或占公共支出的15%至20%。", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "《仁川行动框架》建议教育支出占公共支出的比例是多少？", "options": ["15%至20%", "1%至2%", "40%至50%", "90%至100%"], "answer": 0, "explain": "仁川建议教育支出占公共支出总额的15%至20%。", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "什么是教育融资缺口？", "options": ["为家庭度假和夏季旅行存下的钱", "所需资金与可用资金之间的差额", "城市里两座学校建筑之间的距离", "如今在任何学校都没有实际用途的钱"], "answer": 1, "explain": "融资缺口是为实现教育目标仍需筹措的金额。", "src": "UNESCO"}, {"ch": 7, "q": "为什么贫困地区的学校往往经费较少？", "options": ["他们的学生太多", "他们选择不接受资金", "税收收入较少，经费分配不平等", "他们不需要书籍"], "answer": 2, "explain": "经费分配不平等会使较贫困地区缺乏资源。", "src": "UNESCO GEM Report 2026"}, {"ch": 7, "q": "什么是按生拨款？", "options": ["为每位教师的汽车拨付的资金", "为每辆校车拨付的资金", "为每个体育奖杯拨付的资金", "按每名学生向学校拨付的资金"], "answer": 3, "explain": "按生拨款根据学生人数向学校付款。", "src": "UNESCO"}, {"ch": 8, "q": "哪些目标取代了千年发展目标？", "options": ["可持续发展目标", "奥运目标", "贸易目标", "太空目标"], "answer": 0, "explain": "可持续发展目标（全球目标）于2015年取代了千年发展目标。", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "《教育2030行动框架》是哪一年通过的？", "options": ["1990年", "2015年", "2000年", "2030年"], "answer": 1, "explain": "《教育2030行动框架》于2015年通过。", "src": "Incheon Framework for Action (2015)"}, {"ch": 8, "q": "1948年的宣言对教育有何规定？", "options": ["学校应当关闭", "教育只针对成年人", "人人都有受教育的权利", "教育是奢侈品"], "answer": 2, "explain": "《世界人权宣言》称教育是一项人权。", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "《世界人权宣言》第26条对小学教育有何规定？", "options": ["应当收费高昂", "对所有人都应是可选的", "只应面向男孩", "应当免费且义务"], "answer": 3, "explain": "第26条规定，初级教育应是义务的并且免费。", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "2015年仁川世界教育论坛上发生了什么？", "options": ["各国就2030年教育目标达成一致", "各国关闭了所有学校", "各国就一项新的体育活动达成一致", "各国结束了扫盲计划"], "answer": 0, "explain": "《仁川宣言》确定了2030年的教育目标。", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "1990年的宗滕会议呼吁什么？", "options": ["只有富人才能受教育", "人人享有教育", "只用英语教育", "没有教师的学校"], "answer": 1, "explain": "1990年宗滕会议呼吁人人享有教育。", "src": "UNESCO"}, {"ch": 9, "q": "为什么幼儿早期照护与日后的学习有关？", "options": ["早年没有任何关联", "只有成人学习才重要", "早期技能支持日后的学业成功", "日后的学习与此无关"], "answer": 2, "explain": "扎实的早期基础使日后学习更容易。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "什么是入学准备？", "options": ["已准备好离开学校", "身高足以坐进课桌", "会开车", "在入学时已准备好学习"], "answer": 3, "explain": "入学准备意味着儿童具备开始上学所需的技能和健康状况。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "游戏在早期学习中起什么作用？", "options": ["培养思维、语言和社交能力", "没有任何作用", "永远取代所有学习", "只是浪费时间"], "answer": 0, "explain": "游戏帮助儿童培养思维、语言和社交能力。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "为什么婴儿需要积极回应式的照护？", "options": ["它会把他们宠坏", "它有助于他们的大脑和情绪发育", "不需要它", "它只会让他们睡觉"], "answer": 1, "explain": "积极回应式的照护支持健康的大脑和情绪发展。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "什么是最初的一千天？", "options": ["入学的第一天", "假期的第一周", "从怀孕到两岁的时期", "大学的第一年"], "answer": 2, "explain": "从怀孕到两岁的最初一千天对发育非常重要。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "哪种幼儿活动有助于大脑发育？", "options": ["完全安静", "只让他们长时间看屏幕", "把他们独自留几个小时", "与孩子交谈和阅读"], "answer": 3, "explain": "与孩子交谈和阅读有助于语言和大脑发育。", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "什么是后扫盲？", "options": ["建立在基础识字能力之上的学习", "只读漫画", "只有教师才需要识字", "只读杂志"], "answer": 0, "explain": "后扫盲帮助人们保持并提升基本的读写能力。", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "什么是人人识字？", "options": ["只针对儿童的识字", "为每个人提供识字的机会", "只针对富人的识字", "只限一种语言的识字"], "answer": 1, "explain": "人人识字旨在让每个人都有机会读写。", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "为什么多语种识字项目很有用？", "options": ["它们阻碍学习第二语言", "它们消除了对书籍的需要", "它们帮助学习者先用自己的母语阅读", "它们只在体育中有效"], "answer": 2, "explain": "用孩子能理解的语言学习阅读，有助于日后的学习。", "src": "UNESCO, International Mother Language Day"}, {"ch": 10, "q": "识字与健康之间有什么联系？", "options": ["阅读会让人生病", "两者之间没有联系", "健康只取决于体育运动", "阅读有助于人们理解健康建议"], "answer": 3, "explain": "识字能帮助人们阅读药品标签和健康指南。", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "扫盲运动的目标是什么？", "options": ["教会许多人读书写字", "每周向忙碌的家庭多卖报纸", "阻止人们阅读书籍和杂志", "在全国修建更多道路和桥梁"], "answer": 0, "explain": "扫盲运动致力于减少各社区的文盲现象。", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "哪项技能是识字的基础？", "options": ["玩抛接球", "认识字母和读音", "驾驶公共汽车", "煮米饭"], "answer": 1, "explain": "认识字母和读音是基本的识字技能。", "src": "UNESCO GEM Report 2026"}, {"ch": 11, "q": "目标4.5为弱势群体确保什么？", "options": ["只为最优秀的学生提供机会", "只为富裕家庭提供机会", "平等获得教育的机会", "只在大城市提供机会"], "answer": 2, "explain": "目标4.5确保弱势群体平等获得教育。", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "什么是学生的个别化教育计划？", "options": ["用于假期的计划", "用来逃避上课的计划", "把学生转到另一所学校的计划", "根据学习者需求量身定制的计划"], "answer": 3, "explain": "个别化教育计划帮助教师满足每个学生的特定需求。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "合理便利要求学校做什么？", "options": ["提供帮助学习者参与的调整", "忽视学习者的需求", "收取额外费用", "取消所有支持"], "answer": 0, "explain": "学校必须做出合理调整，使残疾学习者能够参与。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "为什么无障碍材料很重要？", "options": ["它让所有人的学习都更困难", "它让所有学习者都能使用相同的内容", "它只为教师准备", "它取代了教师"], "answer": 1, "explain": "大字版或盲文等无障碍材料帮助学习者跟上课程。", "src": "UN CRPD (2006), Article 24"}], "7": [{"ch": 0, "q": "哪项全球目标涉及气候行动？", "options": ["目标13", "目标3", "目标14", "目标10"], "answer": 0, "explain": "目标13是气候行动。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "哪个具体目标旨在消除教育中的性别差距？", "options": ["目标4.1", "目标4.5", "目标4.4", "目标4.a"], "answer": 1, "explain": "目标4.5旨在消除性别差距并确保平等获得教育的机会。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "为什么衡量学习成果很重要？", "options": ["它只统计城里有多少校舍", "它决定每家书店里教科书的价格", "它显示儿童实际学到了什么，而不仅仅是入学人数", "它测量每个学生的身高和体重"], "answer": 2, "explain": "监测学习成果可以显示儿童是否真正在学习。", "src": "UNESCO GEM Report 2026"}, {"ch": 0, "q": "第4目标指标的用途是什么？", "options": ["选择学校的颜色", "按身高给教师排名", "确定假期日期", "衡量每个目标的进展"], "answer": 3, "explain": "指标用于衡量朝每个目标取得的进展。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "为什么第4目标与其他全球目标相关联？", "options": ["教育支持健康、就业和平等", "教育与其他目标没有任何联系", "教育只对体育有意义", "教育只适用于城市"], "answer": 0, "explain": "教育支持多个目标的进展，例如健康、工作和性别平等。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "哪个具体目标旨在让青年和成年人掌握读写和算术能力？", "options": ["目标4.1", "目标4.6", "目标4.5", "目标4.c"], "answer": 1, "explain": "目标4.6旨在让所有青年和相当一部分成年人掌握读写和算术能力。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "指标4.1.1追踪的是什么？", "options": ["每条主干道上运行的校车数量", "每个城镇校服的平均价格", "达到阅读和数学最低熟练水平的儿童", "学校每间教室的平均高度"], "answer": 2, "explain": "指标4.1.1追踪达到最低熟练水平的儿童所占比例。", "src": "UN SDG Report 2026"}, {"ch": 1, "q": "什么是数字鸿沟？", "options": ["同一座大型校舍里两间教室之间的隔阂", "繁忙的上学日里两节长课之间的间隔", "仅在家中使用的两种语言之间的分隔", "能上网的人与不能上网的人之间的差距"], "answer": 3, "explain": "数字鸿沟指获取设备和互联网机会方面的差距。", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "为什么远程教育能帮助一些学习者？", "options": ["它能惠及偏远地区的学习者", "它能取代所有教师", "它会让学习停止", "它只适用于成年人"], "answer": 0, "explain": "远程和在线学习可以惠及居住在学校远处的人。", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "偏远社区的学习中心是什么？", "options": ["有很多商店和咖啡馆的购物中心", "学习者可以在有支持的情况下学习的场所", "病人休息和康复的医院病房", "用于大型足球比赛的体育场"], "answer": 1, "explain": "学习中心为偏远地区的学习者提供学习和获得帮助的场所。", "src": "UNESCO"}, {"ch": 1, "q": "什么是学校地图绘制？", "options": ["绘制家庭出国旅行的假期路线图", "标出用于校际比赛的运动场地", "查明在哪里需要学校以及谁能够到达学校", "为每所学校设计新的标志和海报"], "answer": 2, "explain": "学校地图绘制帮助政府规划在哪里需要新学校和交通服务。", "src": "UNESCO"}, {"ch": 1, "q": "城市中常见的就学障碍是什么？", "options": ["绿地太多", "图书馆太多", "教师太多", "贫困家庭的生活成本高"], "answer": 3, "explain": "在城市里，贫困家庭可能难以承担交通和生活费用。", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "对残疾学习者而言，“无障碍”意味着什么？", "options": ["能够进入并使用学校设施", "能够随时离开学校", "能够逃课", "能够躲避考试"], "answer": 0, "explain": "无障碍意味着残疾学习者能够进入并使用学校场所和学习材料。", "src": "UN CRPD (2006), Article 24"}, {"ch": 2, "q": "什么是完成率差距？", "options": ["校墙上需要紧急维修的裂缝", "不同群体之间完成学业的差异", "拥挤教室里两张课桌之间的空隙", "每周五下午课表里的空档"], "answer": 1, "explain": "完成率差距表明某些群体完成学业的比例低于其他群体。", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "为什么高收入家庭的孩子通常更容易完成学业？", "options": ["他们的孩子不够聪明", "他们的孩子从不参加考试", "他们的家庭能够负担费用和交通", "他们的孩子不做家庭作业"], "answer": 2, "explain": "收入帮助家庭承担费用和交通，使完成学业的可能性更大。", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "最后一个年级的存活率衡量的是什么？", "options": ["赢得比赛的人所占比例", "拥有自行车的人所占比例", "会说两种语言的人所占比例", "达到最后一个年级的儿童所占比例"], "answer": 3, "explain": "存活率衡量一个阶段中有多少学生达到最后一个年级。", "src": "UNESCO"}, {"ch": 2, "q": "早婚为何会影响学业完成？", "options": ["它可能使女孩的学业中断", "它能提高出勤率", "它完全没有影响", "它只影响男孩"], "answer": 0, "explain": "早婚常常使女孩在完成学业前就失去接受教育的机会。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 2, "q": "什么是重返学校？", "options": ["第一次进入学校", "离校后再次返回学校", "永远离开学校", "更换校服"], "answer": 1, "explain": "重返学校政策帮助辍学的年轻人重新回到学校。", "src": "UNESCO"}, {"ch": 2, "q": "什么是从学校到工作的过渡？", "options": ["搬迁校舍", "更换教师", "从学校进入就业或培训", "仅仅搬到另一个国家"], "answer": 2, "explain": "从学校到工作的过渡是从教育进入就业或培训的过程。", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "什么是学习损失？", "options": ["每天早上在公交车上丢了铅笔盒", "忘记了学校电脑的密码", "在与对手学校的足球比赛中输掉比赛", "长时间中断学习后技能的流失"], "answer": 3, "explain": "学习损失是指学校停课或学习中断后，技能逐渐消退。", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "什么能帮助学生从学习损失中恢复？", "options": ["有针对性的辅导和补习课程", "减少教学", "取消所有考试", "只延长假期"], "answer": 0, "explain": "有针对性的支持能帮助学习者补上落下的内容。", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "什么是掌握式学习？", "options": ["学习者从不重复学习某个主题", "学习者只有在理解某个主题后才继续前进", "学习者跳过所有难的主题", "学习者只背诵答案"], "answer": 1, "explain": "掌握式学习确保学习者在继续前进之前已经理解。", "src": "UNESCO"}, {"ch": 3, "q": "教学语言为什么重要？", "options": ["它没有任何影响", "只应该使用一种语言", "学习者最能理解自己熟悉的语言所授的课程", "它只在体育中才重要"], "answer": 2, "explain": "使用学习者能够理解的语言有助于学习。", "src": "UNESCO, International Mother Language Day"}, {"ch": 3, "q": "什么是双语教育？", "options": ["只通过游戏进行教学", "不使用任何语言进行教学", "为舞蹈而用一种语言教学", "用两种语言进行教学"], "answer": 3, "explain": "双语教育使用两种语言帮助学习者理解并成长。", "src": "UNESCO, International Mother Language Day"}, {"ch": 3, "q": "什么是批判性阅读？", "options": ["对文本进行质疑和评估", "不经思考地阅读", "只读标题", "只看图片"], "answer": 0, "explain": "批判性阅读会追问文本是否准确、公正并且论证充分。", "src": "UNESCO"}, {"ch": 4, "q": "教育中的ICT代表什么？", "options": ["国际烹饪信托", "信息与通信技术", "有趣的校园参观", "重要的课堂测试"], "answer": 1, "explain": "ICT指信息与通信技术。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "什么是职业教育？", "options": ["没有实用技能或实践培训的教育", "只面向已经在当教师的人的教育", "为特定行业或工作做准备的教育", "只面向将来上大学的学生的教育"], "answer": 2, "explain": "职业教育为特定工作培养实用技能。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "TVET代表什么？", "options": ["教师视频考试测试", "全面视觉教育工具", "高等视频教育主题", "技术与职业教育培训"], "answer": 3, "explain": "TVET指技术与职业教育培训。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "为什么一些学校教授编程？", "options": ["它培养解决问题的能力和数字技能", "它取代了所有其他科目", "它只用于游戏", "它会让学习停止"], "answer": 0, "explain": "编程教授逻辑和数字技能，这些技能在许多工作中都很有用。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "什么是数字公民素养？", "options": ["利用科技伤害他人", "安全、负责、尊重地使用科技", "完全不使用科技", "只用科技玩游戏"], "answer": 1, "explain": "数字公民素养指在网上表现得体并尊重他人。", "src": "UNESCO"}, {"ch": 4, "q": "什么是新兴技能？", "options": ["已不再需要的技能", "只用于古老语言的技能", "在新工作中变得重要的技能", "用于睡觉的技能"], "answer": 2, "explain": "随着新型工作的出现，新兴技能变得越来越重要。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "STEM教育中的性别差距是什么？", "options": ["如今在几乎所有国家，女孩学习数学都比男孩多", "任何地方的科学课上都不存在任何差距", "学校里只允许男孩学习理科科目", "学习科学、技术、工程和数学的女孩少于男孩"], "answer": 3, "explain": "许多国家的女孩在STEM科目中人数较少，这限制了她们的选择。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "为什么女教师在某些地方很重要？", "options": ["她们可以成为榜样，帮助女孩留在学校", "世界上任何学校都不需要她们", "她们只教体育和户外体育活动", "她们会阻止儿童学习任何新科目"], "answer": 0, "explain": "女教师可以鼓励女孩，并帮助营造安全的环境。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "什么是性别回应型学校？", "options": ["只招收女生的学校", "满足女孩和男孩需求的学校", "无视性别的学校", "没有厕所的学校"], "answer": 1, "explain": "性别回应型学校会针对女孩和男孩的不同需求进行规划。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "“边缘化”是什么意思？", "options": ["被置于关注的中心", "自动获得额外的资金", "被推到社会边缘并被排斥", "被允许制定所有规则"], "answer": 2, "explain": "被边缘化的群体常常被排除在教育和机会之外。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "为什么少数民族语言使用者有被落下的风险？", "options": ["他们总是最优秀的学习者", "他们的语言从不被使用", "他们从不上学", "学校可能不使用他们的语言授课"], "answer": 3, "explain": "当课堂使用儿童不会说的语言时，许多人会落后。", "src": "UNESCO, International Mother Language Day"}, {"ch": 5, "q": "教育中的平权行动是什么？", "options": ["为处于不利地位的群体提供额外支持", "惩罚表现好的群体", "忽视所有差异", "为某些群体关闭学校"], "answer": 0, "explain": "平权行动提供额外支持，帮助弱势群体赶上来。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "社会经济地位是什么意思？", "options": ["一种学校考试", "一个人的社会和经济地位", "书包的颜色", "体育比赛的胜利次数"], "answer": 1, "explain": "社会经济地位描述一个家庭的收入、教育程度和社会地位。", "src": "UNESCO GEM Report 2026"}, {"ch": 6, "q": "什么是教师缺口？", "options": ["不做任何事的额外教师", "没有课上的教师", "满足需求所需的额外教师数量", "从不离开学校的教师"], "answer": 2, "explain": "教师缺口是为实现教育目标所需的额外教师数量。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "为什么许多国家的教师供应都是一大挑战？", "options": ["想当教师的人太多", "从来不需要教师", "教师只需要面对太多学生", "愿意接受培训或留任教师的人太少"], "answer": 3, "explain": "短缺的原因是接受培训的人太少、薪资低以及人员流动率高。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是教师地位？", "options": ["社会如何看待教师", "教师的身高", "教师的汽车", "教师的书包"], "answer": 0, "explain": "教师地位会影响人们是否选择从事教学工作并继续留任。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是危机地区的教师？", "options": ["只在城市工作的教师", "在冲突或灾难发生地工作的教师", "从不授课的教师", "只在假期工作的教师"], "answer": 1, "explain": "危机地区的教师在艰苦的条件下工作，以确保儿童继续学习。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "为什么一些教师离开这一职业？", "options": ["薪资过高，带薪假期过多", "工作太少，空闲日太多", "薪资低、工作负担重或支持不足", "奖项太多，赞扬太多"], "answer": 2, "explain": "薪资低和工作负担重使一些教师离开了这一职业。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是教师的工作量？", "options": ["教师书包的重量", "教师假期的天数", "教师汽车的价格", "教师需要完成的工作量"], "answer": 3, "explain": "工作量包括教学、备课、批改作业以及其他职责。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "学习贫困率用于什么？", "options": ["追踪十岁时仍无法阅读的儿童", "追踪校舍", "追踪钢笔的价格", "追踪教师的假期"], "answer": 0, "explain": "学习贫困率显示十岁时无法读懂简单文本的儿童所占比例。", "src": "World Bank, learning poverty"}, {"ch": 7, "q": "为什么公共教育支出很重要？", "options": ["它毫无用处", "它支付教师、校舍和教材的费用", "它只支付假期的费用", "它只用来购买体育器材"], "answer": 1, "explain": "公共资金维持学校运转，使所有人都能获得学习机会。", "src": "UNESCO"}, {"ch": 7, "q": "教育领域的预算执行是什么？", "options": ["取消所有课程", "停止所有学校郊游", "按计划使用资金", "出售校舍"], "answer": 2, "explain": "预算执行检查计划中的教育资金是否确实被使用。", "src": "UNESCO"}, {"ch": 7, "q": "教育中的费用分担是什么？", "options": ["学校向家庭付款", "教师向学生付款", "学生向教师付款", "家庭支付学校费用的一部分"], "answer": 3, "explain": "费用分担意味着家庭需要出资，这可能会限制贫困儿童的入学机会。", "src": "UNESCO"}, {"ch": 7, "q": "什么是教育税？", "options": ["用于资助学校的税收", "仅用于参加考试的费用", "仅针对教科书的税", "因缺课而被处以的罚款"], "answer": 0, "explain": "一些国家征收教育税以资助学校。", "src": "UNESCO"}, {"ch": 7, "q": "为什么学校需要定期维修？", "options": ["新建筑总是需要维修", "老旧的建筑可能变得不安全", "维修会让学校变得更大", "维修会让儿童停止学习"], "answer": 1, "explain": "定期维修可以使建筑保持安全，并适合学习。", "src": "UNESCO"}, {"ch": 7, "q": "教育支出中的物有所值是什么意思？", "options": ["每年尽可能多地花钱", "只把钱花在体育器材上", "用所花的钱取得良好的学习成果", "每年一分钱都不花"], "answer": 2, "explain": "物有所值意味着明智地花钱，以提高学习成效。", "src": "UNESCO"}, {"ch": 8, "q": "哪次会议通过了2030年议程？", "options": ["2005年在东京举行的地区会议", "1994年在开罗举行的人口会议", "2014年在利马举行的农业会议", "2015年在纽约举行的联合国峰会"], "answer": 3, "explain": "世界领导人于2015年在纽约联合国峰会上通过了2030年议程。", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "宗滕世界全民教育会议是何时举行的？", "options": ["1990年", "1975年", "2005年", "2020年"], "answer": 0, "explain": "宗滕会议于1990年举行。", "src": "UNESCO"}, {"ch": 8, "q": "达喀尔世界教育论坛是在哪一年举行的？", "options": ["1995年", "2000年", "2010年", "2015年"], "answer": 1, "explain": "达喀尔世界教育论坛于2000年举行。", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "1990年的宗滕宣言侧重于什么？", "options": ["仅限大学学习", "仅限体育", "满足所有人的基本学习需求", "仅限考试"], "answer": 2, "explain": "1990年宣言侧重于满足所有人的基本学习需求。", "src": "UNESCO"}, {"ch": 8, "q": "千年发展目标在教育方面侧重于什么？", "options": ["免费汽车", "仅限大学奖学金", "体育联赛", "普及初等教育"], "answer": 3, "explain": "千年发展目标第2项侧重于普及初等教育。", "src": "UN Millennium Development Goals (2000)"}, {"ch": 8, "q": "全球教育报告的目的是什么？", "options": ["追踪进展并分享证据", "关闭学校", "选择假期", "出售教科书"], "answer": 0, "explain": "全球报告追踪进展并分享证据，以指导政策。", "src": "UNESCO GEM Report 2026"}, {"ch": 9, "q": "幼儿早期发展涵盖哪些方面？", "options": ["只关注身高的成长", "身体、思维和社交能力的成长", "只关注金钱的增长", "只关注速度的提升"], "answer": 1, "explain": "儿童发展涵盖身体、思维、语言和社交能力的成长。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "什么是幼儿期的毒性压力？", "options": ["成长中的儿童每天吃的一种健康食物", "孩子们常在公园玩的一种有趣游戏", "长期、强烈且会损害发育的压力", "幼儿阶段教授的一门学校课程"], "answer": 2, "explain": "如果压力长期存在且得不到支持，毒性压力会损害正在发育的大脑。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "为什么幼儿项目能帮助弱势儿童？", "options": ["它们制造差距", "它们只为富裕家庭的儿童服务", "它们取代家庭", "它们能在入学前缩小差距"], "answer": 3, "explain": "早期项目可以让来自弱势家庭的儿童拥有相对平等的起点。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "育儿支持对早期学习有什么作用？", "options": ["帮助家长支持孩子的学习", "完全取代孩子生活中的父母", "阻止孩子在家和学校学习", "只是为孩子买玩具"], "answer": 0, "explain": "育儿支持为成年人提供与幼儿交谈、游戏和照顾的方法。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "家庭学习环境包括什么？", "options": ["只有电视", "家中的书籍、交谈和游戏", "只有安静", "只有家庭作业"], "answer": 1, "explain": "良好的家庭学习环境鼓励阅读、交谈和游戏。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "为什么幼儿保育对女孩很重要？", "options": ["女孩不需要它", "它只在入学后才重要", "它帮助她们做好入学准备", "它只对男孩重要"], "answer": 2, "explain": "早期照护有助于女孩的健康、学习和自信。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 10, "q": "什么是家庭识字？", "options": ["只针对祖父母的识字教育", "不带孩子的阅读", "只针对老年人的写作", "父母和孩子一起学习阅读"], "answer": 3, "explain": "家庭识字帮助父母和孩子共同提升阅读能力。", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "各国之间的阅读差距是什么？", "options": ["各国阅读水平的差异", "书架上书本之间的空隙", "学校课桌之间的距离", "两所学校之间的距离"], "answer": 0, "explain": "阅读差距显示不同地区的阅读水平相差多少。", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "什么是书写流畅度？", "options": ["写作时不使用文字", "清晰而快速地书写", "只用大写字母书写", "只用电脑书写"], "answer": 1, "explain": "书写流畅度指写作足够顺畅，能够表达想法。", "src": "UNESCO"}, {"ch": 10, "q": "什么是口语？", "options": ["只有书面语言", "只在书中使用的语言", "口头语言", "只有动物使用的语言"], "answer": 2, "explain": "口语是儿童最先学会的口头语言。", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "为什么阅读前的口语能力很重要？", "options": ["它与阅读毫无关系", "它会阻碍儿童阅读", "它只用于唱歌", "它积累了支持阅读的词汇"], "answer": 3, "explain": "良好的口语能力帮助儿童理解他们所读的内容。", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "国际扫盲日的目的是什么？", "options": ["提高人们对扫盲及其益处的认识", "关闭全国所有的图书馆", "在全国商店里卖出更多书籍", "停止小学的所有阅读课"], "answer": 0, "explain": "国际扫盲日提高人们对扫盲及其所能带来的成果的认识。", "src": "UNESCO, International Literacy Day"}, {"ch": 11, "q": "全纳教育要求教师做什么？", "options": ["只教授成绩最好的学生", "根据不同学习者调整课程", "忽视需要帮助的学习者", "拒绝额外的培训"], "answer": 1, "explain": "全纳教学会调整方法，使每个学习者都能参与其中。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "什么是学习的通用设计？", "options": ["没有教室的校舍设计", "对每个学习者只采用一种方式的教学", "设计得适合多种学习者的教学", "每天都由所有学生穿着的一种校服"], "answer": 2, "explain": "学习的通用设计提供多种学习方式，并让学习者展示其理解。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "为什么残疾学习者需要合理便利？", "options": ["为了免除工作", "为了避免考试", "为了放假", "为了平等参与课堂学习"], "answer": 3, "explain": "合理便利让残疾学习者能够平等地参与学习。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "手语翻译员在课堂上做什么？", "options": ["在手语和口语之间进行翻译", "向全班教授舞蹈和音乐", "向学生出售书籍和文具", "驾驶早晨路线上的校车"], "answer": 0, "explain": "手语翻译员帮助听障学习者跟上课程。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "盲文能帮助学习者做什么？", "options": ["听音乐", "通过触摸阅读", "游得更快", "长得更高"], "answer": 1, "explain": "盲文让盲人通过触摸凸起的点来阅读。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "为什么全纳对学校里的每个人都有好处？", "options": ["它无故让班级变小", "它减少学习", "它培养理解和尊重", "它阻碍友谊"], "answer": 2, "explain": "全纳课堂教导所有学习者之间相互尊重和理解。", "src": "UN CRPD (2006), Article 24"}], "8": [{"ch": 0, "q": "第4目标中有多少个具体目标涉及实施手段？", "options": ["三个", "七个", "十个", "四个"], "answer": 0, "explain": "目标4.a至4.c是三个实施手段。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "目标4.c的内容是什么？", "options": ["建设新的运动场", "增加合格教师的供应", "向成年人免费提供书籍", "把学校规模缩小"], "answer": 1, "explain": "目标4.c呼吁增加合格教师，包括通过培训来实现。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "哪个目标侧重于可持续发展和全球公民身份？", "options": ["目标4.1", "目标4.2", "目标4.7", "目标4.b"], "answer": 2, "explain": "目标4.7涵盖可持续发展和全球公民身份所需的知识。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "能力指标侧重于什么？", "options": ["学校有多少栋建筑", "每年有多少个假期", "学习者有多高", "学习者是否在关键技能上达到设定的水平"], "answer": 3, "explain": "能力指标检查学习者是否在阅读和数学等技能上达到设定的水平。", "src": "UN SDG Report 2026"}, {"ch": 0, "q": "按性别、年龄和残疾对数据进行分类是什么意思？", "options": ["将数据按每个这些群体进行拆分", "将数据保密", "只收集男性的数据", "只收集关于建筑的数据"], "answer": 0, "explain": "分类数据可以显示进展是否惠及每个群体。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "哪个目标涉及减少不平等？", "options": ["目标6", "目标10", "目标13", "目标15"], "answer": 1, "explain": "目标10是减少不平等。", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "辍学率是什么？", "options": ["跳过午餐的学生比例", "没有屋顶的学校比例", "适龄儿童中没有上学的比例", "请假的教师比例"], "answer": 2, "explain": "辍学率衡量适龄但未入学的儿童。", "src": "UNESCO"}, {"ch": 1, "q": "什么使学校在距离上具有可达性？", "options": ["远离所有住户", "只能乘飞机到达", "工作日关闭", "位于儿童住所的安全可达范围内"], "answer": 3, "explain": "可达性意味着儿童能够安全、经常地到达学校。", "src": "UNESCO"}, {"ch": 1, "q": "哪种成本对贫困家庭来说往往是隐性的？", "options": ["孩子打工所损失的收入", "免费的练习本", "免费的学校午餐", "免费的交通"], "answer": 0, "explain": "当孩子去上学而不是工作时，贫困家庭可能会损失收入。", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "教育中的“最后一公里”挑战是什么？", "options": ["跑最长的赛程", "触及最偏远的儿童", "参加最后一场考试", "关闭最后一所学校"], "answer": 1, "explain": "“最后一公里”挑战侧重于触及最难接触到的儿童。", "src": "UNESCO"}, {"ch": 1, "q": "政府为什么要追踪入学数据？", "options": ["为了选择学校的颜色", "为了按身高给学生排名", "为了规划教师、校舍和学位", "为了选择假期日期"], "answer": 2, "explain": "入学数据帮助政府规划教师、教室和交通。", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "过渡率衡量的是什么？", "options": ["主干道上校车的行驶速度", "一整天响起的上下课铃声次数", "食堂出售的笔记本和钢笔的价格", "从一个学段升入下一学段的学生比例"], "answer": 3, "explain": "过渡率显示有多少学生升入下一学段。", "src": "UNESCO"}, {"ch": 2, "q": "为什么一些学生无法升入中学？", "options": ["费用、距离以及早期学习薄弱", "中学总是免费的", "中学没有任何入学规定", "学生个子太高"], "answer": 0, "explain": "费用、距离以及小学学习的欠缺，都可能使学生无法升学。", "src": "UNESCO"}, {"ch": 2, "q": "高中阶段完成是什么意思？", "options": ["完成幼儿园的第一年", "完成中学的最后阶段", "完成一门体育课程", "完成一个假期夏令营"], "answer": 1, "explain": "高中阶段完成意味着完成中学的最后阶段。", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "哪个群体最可能同时面临多重完成学业的障碍？", "options": ["来自富裕城市家庭的男孩", "没有任何障碍的儿童", "来自贫困农村家庭的残疾女孩", "只有成年人"], "answer": 2, "explain": "多重劣势相互叠加，使一些学习者更难完成学业。", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "什么是替代性学习路径？", "options": ["无需任何笔试即可获得学历的路线", "只对合格教师开放的路线", "使学习者无法完成学业的路线", "通过不同途径获得同等学历的路线"], "answer": 3, "explain": "替代性路径让学习者以灵活的方式获得学历。", "src": "UNESCO"}, {"ch": 2, "q": "学校中的早期预警系统是什么？", "options": ["尽早发现有辍学风险的学习者，以便及时提供帮助", "在学年末提醒学生注意期末考试", "在午餐时间拉响刺耳的警报，把学生召回", "在集会时把学校铃声敲得更响、更久"], "answer": 0, "explain": "早期预警系统标记出出勤和学习方面的问题，以便学校采取行动。", "src": "UNESCO"}, {"ch": 3, "q": "什么是国际学习评估？", "options": ["学校体育竞赛", "比较各国学习情况的测试", "教师招聘考试", "政府预算计划"], "answer": 1, "explain": "PISA、TIMSS和PIRLS等国际评估用于比较各国的学习情况。", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "什么是PISA？", "options": ["为农村儿童运营的校车系统", "城市学生所穿的一种校服", "对15岁学生阅读、数学和科学能力的测试", "每年为青年运动员举办的全球体育锦标赛"], "answer": 2, "explain": "PISA是经合组织针对15岁学生在阅读、数学和科学方面进行的测试。", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "为什么学习评估需要精心设计？", "options": ["为了永远不需要测试", "为了让测试更长", "为了让学生永远看不到测试", "为了在不同语言和文化之间公平地测量"], "answer": 3, "explain": "良好的评估会被设计得公平，并能在不同群体之间进行比较。", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "什么是学习危机？", "options": ["许多儿童上了学却没有学到东西", "儿童学得太快了", "学校的书太多了", "儿童从来不上学"], "answer": 0, "explain": "学习危机指的是儿童虽然上学，却没有掌握基本技能。", "src": "World Bank, learning poverty"}, {"ch": 3, "q": "什么是低年级阅读评估？", "options": ["只针对成年人的考试，在工作日结束后进行", "对入学最初几年阅读能力的测试", "为学校足球队设计的体育技能测试", "为在家的年幼学习者设计的烹饪技能测试"], "answer": 1, "explain": "低年级阅读评估检查幼儿是否正在学习阅读。", "src": "UNESCO"}, {"ch": 3, "q": "理解能力如何帮助学习者解答数学应用题？", "options": ["不读题就猜答案", "跳过这道题", "理解题目的要求", "抄同学的答案"], "answer": 2, "explain": "理解能力帮助学习者在解题之前先弄清问题。", "src": "UNESCO"}, {"ch": 4, "q": "什么是数据素养？", "options": ["收集关于宠物的数据", "对他人隐藏数据", "只把数据保存在纸上", "阅读、理解和使用数据的能力"], "answer": 3, "explain": "数据素养指理解并运用数据做出决策。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "为什么学生需要理解人工智能？", "options": ["为了明智地使用它并了解其局限", "为了取代所有教师", "为了停止使用电脑", "为了避免一切科技"], "answer": 0, "explain": "学习者需要负责任地使用人工智能工具，并了解它能做什么、不能做什么。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "什么是创业思维？", "options": ["避免一切风险，始终待在一个地方", "发现机会并承担合理的风险", "只为别人工作，从不为自己工作", "一生从不尝试新事物或新想法"], "answer": 1, "explain": "创业思维指注意到机会并负责任地加以行动。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "什么是软技能？", "options": ["搬运重物的能力", "只限烤面包的技能", "团队合作、同理心和沟通等能力", "睡眠的能力"], "answer": 2, "explain": "软技能帮助人们与他人良好地工作和生活。", "src": "UNESCO"}, {"ch": 4, "q": "什么是终身学习？", "options": ["只学到十岁", "只在大学学习", "只在星期日学习", "贯穿一生的学习，而不仅限于学校"], "answer": 3, "explain": "终身学习指在整个人生中持续学习。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "为什么终身学习对工作很重要？", "options": ["工作在变化，因此人们需要新技能", "工作从不改变", "学校之后的学习毫无用处", "工作不需要任何技能"], "answer": 0, "explain": "新技术和新行业使人们不断学习新技能。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "“学会学习”是什么意思？", "options": ["什么都不记，却指望仍然能通过考试", "了解自己最有效的学习方式并规划学习", "很快地抄写同学笔记本上的答案", "课堂上和家里从不提问"], "answer": 1, "explain": "学会学习帮助人们成为独立的学习者。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "教育中的交叉性是什么？", "options": ["一种有许多层楼和房间的校舍", "所有班级都使用的一种课表", "重叠的身份如何加剧劣势", "按照每个孩子的身高来分班的方式"], "answer": 2, "explain": "交叉性承认性别、贫困、残疾和其他因素可能相互重叠。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "性别转化型教育的目标是什么？", "options": ["保持性别规范不变", "只教一种性别", "在所有科目中忽略性别", "改变有害的性别规范"], "answer": 3, "explain": "性别转化型教育挑战刻板印象和不平等的角色。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "为什么一些女孩在冲突期间面临更高的辍学风险？", "options": ["不安全、流离失所和性别暴力", "女孩总是更安全", "冲突对学校没有影响", "女孩偏爱冲突"], "answer": 0, "explain": "冲突会增加流离失所和暴力等风险，把女孩推出校园。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "什么有助于预防学校中的性别暴力？", "options": ["对家长和公众隐瞒事件", "政策、行为准则和培训", "责怪受害者遭受的一切", "无视学校收到的每一份举报"], "answer": 1, "explain": "预防包括明确的行为准则、培训和举报制度。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "课堂上的平等参与是什么？", "options": ["只有声音最大的学习者发言", "课堂上只有男孩发言", "所有学习者都能参与并被倾听", "只有老师发言"], "answer": 2, "explain": "平等参与意味着每位学习者都有公平的机会做出贡献。", "src": "UNESCO"}, {"ch": 5, "q": "学校中的歧视性语言是什么？", "options": ["赞扬努力工作的言语", "解释课程内容的言语", "描述天气的言语", "因人的身份而贬低他人的言语"], "answer": 3, "explain": "歧视性语言会伤害学习者，并营造不安全的环境。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "污名化对学习者意味着什么？", "options": ["排斥他人的负面评判", "一种学校奖项", "一种校服", "一种赞美的形式"], "answer": 0, "explain": "污名化会导致人们受到不公平的对待，从而可能使他们无法学习。", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "什么是教师职业标准？", "options": ["教师假期清单", "对教师应当知道和能够做到的事情的期望", "学校零食清单", "仅仅是教师工资清单"], "answer": 1, "explain": "职业标准描述优秀教学应有的样子。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "为什么教师招聘是一项政策挑战？", "options": ["只需要雇用亲属", "不需要任何规划", "需要吸引并选拔有能力的人", "需要关闭学校"], "answer": 2, "explain": "良好的招聘能找到有能力的人，并把他们安排到最需要的地方。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是教师调配？", "options": ["送教师去度假", "只把教师派往其他国家", "把教师从学校调走", "把教师安排到最需要的地方"], "answer": 3, "explain": "调配是指把教师分配到最需要他们的学校和地区。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是教师留任？", "options": ["让教师留在这一职业中", "让教师不间断地待在课堂上", "不让学生成为教师", "让教师远离儿童"], "answer": 0, "explain": "留任策略让受过培训的教师留在工作岗位上。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "教师为什么需要一定的自主权？", "options": ["以便避开所有规则", "以便根据学生情况调整课程", "以便什么都不教", "以便在没有支持的情况下工作"], "answer": 1, "explain": "一定的自主权有助于教师根据课堂的实际需要调整教学。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是教师工会？", "options": ["关闭学校的团体", "出售教科书的团体", "代表教师利益的组织", "单独确定考试日期的团体"], "answer": 2, "explain": "教师工会在有关薪酬和工作条件的讨论中代表教师。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是教师缺勤？", "options": ["教师参加培训", "教师协助社团活动", "教师阅读书籍", "教师无正当理由缺席工作"], "answer": 3, "explain": "缺勤会减少学习时间，因此是政策关注的问题。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "教师福祉影响什么？", "options": ["教师的教学效果以及他们能否留在工作岗位", "只影响校车的价格", "只影响天气", "没有什么重要影响"], "answer": 0, "explain": "教师福祉影响教学质量和留任。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "教育领域的预算透明是什么？", "options": ["对公众隐瞒支出", "公开教育经费的使用情况", "秘密地花钱", "无视预算"], "answer": 1, "explain": "透明让公民能够核查教育经费的使用情况。", "src": "UNESCO"}, {"ch": 7, "q": "教育的定向拨款是什么？", "options": ["无论需求如何，给每所学校相同的资金", "只用于体育、游戏和学校郊游的资金", "为需求最大的学校或学生额外拨付的资金", "只拨给本已非常富裕的学校的资金"], "answer": 2, "explain": "定向拨款把更多资源投向最需要的地方。", "src": "UNESCO GEM Report 2026"}, {"ch": 7, "q": "学校支出中的效率是什么？", "options": ["尽可能多地花钱", "把钱花在最没用的东西上", "只花在校舍上", "用所花的钱获得最大的学习成效"], "answer": 3, "explain": "高效的支出能用同样的钱取得更好的学习成果。", "src": "UNESCO"}, {"ch": 7, "q": "为什么许多国家通过地方税为学校提供资金？", "options": ["让当地社区对支出有发言权", "地方税是非法的", "地方税取代了政府的全部资金", "地方税只用于体育"], "answer": 0, "explain": "地方筹资可以使学校更具回应性，但也可能加剧不平等。", "src": "UNESCO"}, {"ch": 7, "q": "仅依赖地方税的风险是什么？", "options": ["较贫穷的地区总能获得更多资金", "较富裕的地区可能能为学校提供更好的资金", "学校从不需要资金", "地方税总能消除不平等"], "answer": 1, "explain": "只依赖地方税会扩大富裕地区与贫困地区之间的差距。", "src": "UNESCO GEM Report 2026"}, {"ch": 7, "q": "学校的资本预算是什么？", "options": ["只用于教师工资的资金", "用于假期的资金", "用于校舍和设备的资金", "只用于校服的资金"], "answer": 2, "explain": "资本预算用于支付校舍和设备等长期资产。", "src": "UNESCO"}, {"ch": 7, "q": "学校的经常性预算是什么？", "options": ["用于建设一所新学校的资金", "用于一次考试的资金", "用于一次性体育活动的资金", "用于工资等日常运营开支的资金"], "answer": 3, "explain": "经常性预算涵盖教师工资和教材等持续性开支。", "src": "UNESCO"}, {"ch": 7, "q": "教育中的单位成本是什么？", "options": ["教育一名学生一年的成本", "一辆校车的成本", "一套完整校服的成本", "仅一张试卷的成本"], "answer": 0, "explain": "单位成本帮助政府规划每位学习者需要多少资金。", "src": "UNESCO"}, {"ch": 8, "q": "世界教育论坛是哪一年在仁川召开的？", "options": ["1990年", "2015年", "2000年", "2030年"], "answer": 1, "explain": "世界教育论坛于2015年在大韩民国仁川举行。", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "2015年世界教育论坛在哪里举行？", "options": ["塞内加尔达喀尔", "泰国宗滕", "大韩民国仁川", "法国巴黎"], "answer": 2, "explain": "2015年论坛由大韩民国的仁川主办。", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "2000年世界教育论坛在哪里举行？", "options": ["大韩民国仁川", "泰国宗滕", "肯尼亚内罗毕", "塞内加尔达喀尔"], "answer": 3, "explain": "2000年的达喀尔论坛通过了《达喀尔行动框架》。", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "《世界人权宣言》第26条涵盖什么？", "options": ["受教育的权利", "拥有汽车的权利", "享受假期的权利", "在学校投票的权利"], "answer": 0, "explain": "第26条规定了受教育的权利。", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "《教育2030》以什么为基础？", "options": ["只有奥林匹克运动会及运动员规则", "千年发展目标和全民教育", "只有太空探索和火箭科学研究", "只有体育规则和足球锦标赛成绩"], "answer": 1, "explain": "《教育2030》建立在早先的全球教育承诺之上。", "src": "Incheon Framework for Action (2015)"}, {"ch": 8, "q": "世界为什么从千年发展目标转向可持续发展目标？", "options": ["取消下一个十年的所有教育目标", "只关注一个国家而忽视其他国家", "为所有国家涵盖更广泛的问题", "删除各国所设定的每一个目标"], "answer": 2, "explain": "可持续发展目标具有普遍性，涵盖的问题比千年发展目标更多。", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "千年发展目标涵盖的时期是什么？", "options": ["1990年至2000年", "2015年至2030年", "2000年至2030年", "2000年至2015年"], "answer": 3, "explain": "千年发展目标的实施时间为2000年至2015年。", "src": "UN Millennium Development Goals (2000)"}, {"ch": 9, "q": "什么是回应式照护？", "options": ["成年人对孩子的信号做出温暖而恰当的反应", "无视孩子的信号，任其哭闹", "只发号施令，从不倾听孩子", "在所有场合都让孩子远离成年人"], "answer": 0, "explain": "回应式照护建立信任，并支持学习。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "儿童健康为什么对学习很重要？", "options": ["健康对学习没有影响", "疾病和饥饿会使儿童无法学习", "只有运动才需要健康", "健康的儿童从不需要上学"], "answer": 1, "explain": "良好的健康和营养有助于儿童学习并集中注意力。", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "什么是发育迟缓？", "options": ["长得非常快，比大多数同伴高很多", "学校对所有人关于校服、头发和鞋子的纪律规定", "因营养不良而比同龄人明显矮小", "按年龄来看非常高，并且比大多数同伴长得更快"], "answer": 2, "explain": "发育迟缓是长期营养不良的一个信号，可能影响学习。", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "什么是早期刺激？", "options": ["每天让婴儿长时间处于完全安静之中", "每顿饭只给幼儿糖果和零食", "让婴儿几乎整天待在黑暗的房间里", "能激发婴儿感官和思维的活动"], "answer": 3, "explain": "早期刺激包括交谈、唱歌、触摸和游戏。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "为什么幼儿服务需要受过培训的工作人员？", "options": ["受过培训的工作人员最能支持儿童的发展", "不需要工作人员", "培训是浪费钱", "受过培训的工作人员会使儿童停止学习"], "answer": 0, "explain": "训练有素的幼儿工作人员了解幼儿是如何学习的。", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "什么是从幼儿阶段到小学的过渡项目？", "options": ["河上的一座桥", "帮助儿童适应的项目", "校车的道路", "一个运动场"], "answer": 1, "explain": "过渡项目帮助幼儿适应小学生活。", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "什么是音素意识？", "options": ["知道颜色的名称", "只用大写字母书写", "注意到口语单词中的声音", "阅读书的封底"], "answer": 2, "explain": "音素意识帮助儿童把声音与字母联系起来。", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "早期阅读中的词汇是什么？", "options": ["书的价格", "页数", "字母的大小", "儿童所知道并使用的词语"], "answer": 3, "explain": "丰富的词汇帮助儿童理解他们所读的内容。", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "什么是成人基础教育？", "options": ["为成年人提供的基础阅读、写作和计算教育", "大学的物理和法律高级课程", "为当地足球队提供的体育训练", "为想拿驾照的成年人提供的驾驶课程"], "answer": 0, "explain": "成人基础教育帮助成年人学习必需的读写和计算能力。", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "什么是印刷品丰富的环境？", "options": ["没有任何印刷文字的地方", "有大量印刷文字可供阅读的地方", "所有书籍都被锁起来的地方", "只有图片的地方"], "answer": 1, "explain": "印刷品丰富的环境让儿童在日常生活中接触字母和文字。", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "为什么农村地区的识字水平往往较低？", "options": ["农村居民从不阅读", "法律规定农村地区不教授识字", "附近的学校、书籍和阅读场所较少", "农村居民不需要阅读"], "answer": 2, "explain": "许多国家显示农村地区的识字水平较低，因为那里的学校和书籍较难获得。", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "为什么为乐趣而阅读很重要？", "options": ["它浪费时间", "它只适用于教师", "它会使儿童以后不再阅读", "它培养阅读习惯并拓宽知识面"], "answer": 3, "explain": "为乐趣而阅读所形成的习惯有助于终身学习。", "src": "UNESCO, International Literacy Day"}, {"ch": 11, "q": "通用学习设计鼓励什么？", "options": ["以多种方式呈现、吸引学习者并评估学习", "每个学习者都必须遵循的一种教学方式", "取消学年中的所有评估", "完全安静地教学，没有任何讨论"], "answer": 0, "explain": "通用设计提供多种选择，使学习者能够获取学习内容并展示所学。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "什么是学习支持计划？", "options": ["为所有学生制定的学校假期计划", "为学习者的需求制定支持措施的计划", "每天都提前结束课程的计划", "把部分学习者从学校中移除的计划"], "answer": 1, "explain": "学习支持计划为个别学习者规定调整措施和帮助。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "为什么残疾学习者的家庭应当参与其中？", "options": ["家庭不应参与", "家庭只需交费", "他们最了解学习者的需求", "家庭会制造问题"], "answer": 2, "explain": "家庭提供的知识有助于学校为学习者提供支持。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "什么是全纳性评估？", "options": ["只有最优秀的人才能通过的测试", "从不实施的测试", "只测量速度的测试", "让所有学习者都能展示所知所能的测试"], "answer": 3, "explain": "全纳性评估调整学习成果的呈现方式，使所有学习者都能展示其学习。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "全纳学校中的同伴支持是什么？", "options": ["同学之间互相帮助学习", "同学之间竞争以排斥他人", "同学只独自工作", "同学之间相互回避"], "answer": 0, "explain": "同伴支持帮助学习者感到被接纳，并共同学习。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "全纳学校为什么能减少歧视？", "options": ["它们按能力把儿童分开", "它们教导尊重，并使差异成为常态", "它们消除了一切多样性", "它们增加了恐惧"], "answer": 1, "explain": "当儿童一起学习时，他们会建立尊重和理解。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "学校中的隔离是什么？", "options": ["每天把所有儿童安排在同一间教室", "在学生之间平均分配书籍和材料", "按残疾、性别或背景把儿童分开", "让每个人在操场上公平地轮流"], "answer": 2, "explain": "隔离不公平地将学习者分开，而全纳教育反对这种做法。", "src": "UN CRPD (2006), Article 24"}, {"ch": 1, "q": "学校的招生范围是什么？", "options": ["一种学校体育项目", "学校的屋顶", "学校的一顿饭", "学校计划服务的地区"], "answer": 3, "explain": "招生范围是学校计划服务的儿童所在的区域。", "src": "UNESCO"}], "9": [{"ch": 0, "q": "哪个可持续发展目标涉及实现目标的伙伴关系？", "options": ["第17目标", "第7目标", "第12目标", "第1目标"], "answer": 0, "explain": "第17目标是“促进目标实现的伙伴关系”。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "“实施手段”指的是什么？", "options": ["写在大海报上的所有目标名称", "实现目标所需的资源和工具", "每年在市政厅举行会议的日期", "挂在学校礼堂里的海报颜色"], "answer": 1, "explain": "实施手段包括资金、技术、能力建设和伙伴关系。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "可持续发展目标监测中的数据缺口问题是什么？", "options": ["数据太多，没有人能真正读完", "数据只保存在旧文件柜的纸质文件中", "许多国家缺乏可靠数据来跟踪进展", "数据总是完美的，从不需要核查"], "answer": 2, "explain": "数据缺口使衡量进展和识别被落下的人群变得困难。", "src": "UN SDG Report 2026"}, {"ch": 0, "q": "为什么可持续发展目标要使用指标？", "options": ["为了安排学校课程表", "为了选择国歌", "为了取代教师", "为了以一致的方式衡量进展"], "answer": 3, "explain": "指标使各国之间以及不同时期的进展可以比较。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "《2030年议程》是什么？", "options": ["2015年通过的、旨在2030年前实现各目标的计划", "2030年在巴黎举办的奥运会计划", "一份持续到2030年每个学期的学校课程表", "2030年全年每所学校的假期安排"], "answer": 0, "explain": "《2030年议程》是联合国于2015年通过的全球目标计划。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "第4目标的国家计划有什么作用？", "options": ["关闭所有学校", "规定一个国家将如何实现第4目标", "取消所有考试", "仅凭一项法令就取消学费"], "answer": 1, "explain": "国家计划规定了实现第4目标的优先事项、预算和行动。", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "什么是学生被排斥在校外？", "options": ["获得奖励", "自主选择转到新学校", "被排除在学校之外或无法入学", "获得额外的辅导课"], "answer": 2, "explain": "排斥使儿童无法学习，侵犯了他们的受教育权。", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 1, "q": "童婚对学校有什么影响？", "options": ["总是改善学校教育", "没有影响", "使学校免费", "常常导致过早辍学"], "answer": 3, "explain": "童婚是女童过早离开学校的主要原因。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 1, "q": "因教育而流离失所是什么意思？", "options": ["被迫离开家园，这常常打断学业", "把课桌搬到教室的另一边", "每年为下一学期选择新学校", "学期开始时进行的一种学校考试"], "answer": 0, "explain": "流离失所的儿童如果得不到支持，可能会失去多年的学业。", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "什么是难民教育？", "options": ["只为某一所学校的教师提供的教育", "为逃离家园的儿童和青年提供的教育", "仅通过体育和户外活动为全校提供的教育", "只为之后重返校园的成年人提供的教育"], "answer": 1, "explain": "难民教育帮助流离失所的学习者继续学习。", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "为什么紧急情况下的教育很重要？", "options": ["在危机中没有价值", "只为游客服务", "它为儿童提供稳定和保护", "可以取代所有粮食援助"], "answer": 2, "explain": "紧急情况下的学校为儿童提供安全、规律和希望。", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "什么是临时学习空间？", "options": ["用于存放汽车和重型机械的建筑", "向所有学生出售书本、钢笔和纸张的商店", "供成年人每天下午休息的场所", "危机后迅速设立的安全学习场所"], "answer": 3, "explain": "当正式学校无法使用时，临时学习空间让儿童继续学习。", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "上学距离通常用什么来衡量？", "options": ["儿童必须走的时间或距离", "书的数量", "学校的颜色", "城里教师的人数"], "answer": 0, "explain": "通行时间和距离是衡量入学机会的常用指标。", "src": "UNESCO"}, {"ch": 1, "q": "为什么残疾儿童常常缺课？", "options": ["他们不想学习", "学校无障碍设施不足，也缺乏支持", "他们太聪明，学校不适合他们", "他们的玩具太多"], "answer": 1, "explain": "缺少无障碍建筑、适应性教学和支持，使许多儿童无法上学。", "src": "UN CRPD (2006), Article 24"}, {"ch": 2, "q": "什么是留级率？", "options": ["赢得比赛的学生所占的比例", "提早入学的学生所占的比例", "留级学生所占的比例", "学习音乐的学生所占的比例"], "answer": 2, "explain": "留级率显示学生留级的频繁程度。", "src": "UNESCO"}, {"ch": 2, "q": "为什么留级通常是一个糟糕的解决办法？", "options": ["它总能提高学习成绩", "对每个人都是免费的", "它能消除所有差距", "它可能增加辍学的风险"], "answer": 3, "explain": "留级一年往往会增加学生离开学校的可能性。", "src": "UNESCO"}, {"ch": 2, "q": "什么是升级？", "options": ["升入下一个年级", "销售校服", "搬到另一个国家", "退学"], "answer": 0, "explain": "升级意味着学生可以进入下一个年级。", "src": "UNESCO"}, {"ch": 2, "q": "什么是毕业证书？", "options": ["国家体育场一场大型足球赛的门票", "证明学生已完成某一学段的文件", "对经常旷课的学生处以的罚款", "显示城里每所学校位置的地图"], "answer": 1, "explain": "毕业证书记录了某一教育阶段的完成情况。", "src": "UNESCO"}, {"ch": 2, "q": "国家完成率目标旨在做什么？", "options": ["减少全国学校的总数", "阻止儿童升入下一学段", "提高完成每个学段的儿童比例", "减少全校每个学生的考试次数"], "answer": 2, "explain": "国家目标侧重于帮助更多儿童完成每个学段。", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "什么是技能认证？", "options": ["一种带有许多小口袋的书包", "每年夏天全家的假期安排", "一道特别家庭晚餐的烹饪食谱", "对一个人所具备技能的正式认可"], "answer": 3, "explain": "认证向雇主和其他人证明一个人具备某项技能。", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "什么是先前学习成果认定？", "options": ["承认在校外已获得的学习成果", "忽略所有过去的学习，每次都从零开始", "只计算在大学或学院参加的考试", "取消人们已经获得的资格"], "answer": 0, "explain": "认定先前学习成果可以帮助人们不必重复已掌握的内容而继续前进。", "src": "UNESCO"}, {"ch": 3, "q": "什么是学习标准？", "options": ["一种有许多教室的学校建筑", "对学习者应知应会内容的说明", "每天早上运行的一种校车", "学生和教师的着装规范"], "answer": 1, "explain": "学习标准描述了每个学段的预期学习成果。", "src": "UNESCO"}, {"ch": 3, "q": "《全球教育监测报告》关注什么？", "options": ["销售教科书", "选择学校体育项目", "跟踪全球教育的进展", "规划假期"], "answer": 2, "explain": "《全球教育监测报告》跟踪教育进展并分享证据。", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "什么是学习档案？", "options": ["学生的照片", "学校假期的清单", "学校的平面图", "记录学习者的优势和需求"], "answer": 3, "explain": "学习档案帮助教师为每位学习者规划支持。", "src": "UNESCO"}, {"ch": 3, "q": "教师为什么使用诊断性评估？", "options": ["为了了解学习者已经掌握什么以及需要什么", "只在每学年结束时给出成绩", "为了避免整天给全班上课", "每当儿童犯错时就惩罚他们"], "answer": 0, "explain": "诊断性评估帮助教师规划符合学习者需求的课程。", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "什么是课程改革？", "options": ["改变学校的颜色", "改变教什么以及怎样教", "关闭所有学校", "取消所有科目"], "answer": 1, "explain": "课程改革更新科目、技能和教学方法。", "src": "UNESCO"}, {"ch": 3, "q": "什么是能力本位学习？", "options": ["只关注记忆事实", "只关注体育", "关注学习者能够做什么", "只关注课堂上花费的时间"], "answer": 2, "explain": "能力本位学习衡量的是技能和能力，而不仅仅是知识。", "src": "UNESCO"}, {"ch": 3, "q": "为什么科学素养很重要？", "options": ["它取代了所有阅读和写作技能", "它只帮助实验室里的科学家", "它在日常生活中毫无实际用途", "它帮助人们理解和判断证据"], "answer": 3, "explain": "科学素养有助于人们就健康和环境做出明智的决定。", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "什么是数学推理？", "options": ["解释一种方法为什么有效", "猜测答案", "抄写答案", "跳过演算过程"], "answer": 0, "explain": "推理表明学习者理解的是方法，而不仅仅是答案。", "src": "UNESCO"}, {"ch": 3, "q": "什么是学习增益？", "options": ["体重的增加", "学习者在一段时间内取得的进步", "学校义卖的利润", "假期的增加"], "answer": 1, "explain": "学习增益衡量学习者随时间推移的进步幅度。", "src": "UNESCO GEM Report 2026"}, {"ch": 4, "q": "什么是绿色技能？", "options": ["把墙刷成绿色的技能", "只用于种草的技能", "有助于保护环境的技能", "玩绿色游戏的技能"], "answer": 2, "explain": "绿色技能支持环境保护和可持续就业。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "为什么气候教育与目标4.7有关？", "options": ["气候与学习没有关系", "气候教育被禁止", "气候教育取代数学", "它支持可持续发展教育"], "answer": 3, "explain": "目标4.7包括可持续发展教育，其中涵盖气候问题。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "什么是和平教育？", "options": ["学习如何不用暴力解决冲突", "学习如何挑起冲突", "只学习战争史", "学习如何回避他人"], "answer": 0, "explain": "和平教育教授尊重、对话和非暴力。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "人权教育教什么？", "options": ["只教游戏规则", "学习者的权利和责任", "只讲火车的历史", "只教烹饪"], "answer": 1, "explain": "人权教育帮助学习者了解并尊重权利。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "什么是公民教育？", "options": ["只学汽车知识", "只学树木知识", "学习公民身份和公共生活", "只学体育知识"], "answer": 2, "explain": "公民教育帮助学习者负责任地参与社区生活。", "src": "UNESCO"}, {"ch": 4, "q": "为什么要教授跨文化理解？", "options": ["它阻止人们旅行", "它使所有文化变得相同", "它只为游客而设", "它帮助人们尊重不同的生活方式"], "answer": 3, "explain": "跨文化理解减少偏见，增进尊重。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "什么是问题导向学习？", "options": ["通过解决真实问题来学习", "通过死记清单来学习", "通过回避问题来学习", "只通过抄写笔记来学习"], "answer": 0, "explain": "问题导向学习通过应对真实挑战来培养思维能力。", "src": "UNESCO"}, {"ch": 5, "q": "教育中的贫困指什么？", "options": ["教室书架上的书太多", "缺钱限制了获得学习的机会", "相对于学生人数，教师太多", "学年中假期太多"], "answer": 1, "explain": "贫困会限制获得学校教育、食物、交通和学习用品的机会。", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "教育中的民族差距是什么？", "options": ["书包颜色的差异", "仅在于假期的差异", "不同民族群体之间学业成绩的差异", "鞋子的差异"], "answer": 2, "explain": "民族差距表明某些群体成绩较低，这可能反映了不公平的障碍。", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "城乡差距是什么？", "options": ["城市公园数量的差异", "降雨量的差异", "校服的差异", "农村和城市地区学习状况的差异"], "answer": 3, "explain": "农村地区往往资源较少，这可能扩大学习差距。", "src": "UNESCO"}, {"ch": 5, "q": "财富五分位数衡量的是什么？", "options": ["按财富将家庭分为五组", "全城使用的五种校车", "每年为整班设计考试的五种方式", "每间教室都用的五种粉笔颜色"], "answer": 0, "explain": "财富五分位数将家庭分为五组，以比较教育结果。", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "教育中的扶贫政策是什么？", "options": ["只帮助最富裕人群的政策", "以最贫困学习者为对象的政策", "关闭贫困地区学校的政策", "提高穷人学费的政策"], "answer": 1, "explain": "扶贫政策将资源集中用于最需要的人。", "src": "UNESCO"}, {"ch": 5, "q": "教育中的机会均等是什么？", "options": ["只有最优秀的学习者才有机会", "机会取决于家庭财富", "无论出身如何，都有同样的成功机会", "机会只在城市提供"], "answer": 2, "explain": "机会均等意味着出身不应决定学习者能够取得什么成就。", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "什么是教师薪酬差距？", "options": ["教师的薪酬高于医生", "教师的薪酬是黄金", "教师从不领薪", "教师的薪酬低于同类职业"], "answer": 3, "explain": "薪酬差距意味着教师的收入低于同类工作者，使这一职业吸引力下降。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "教师薪酬为什么对学习重要？", "options": ["它影响谁成为教师并留任", "它与学习没有关系", "它只影响学校建筑", "它只影响假期"], "answer": 0, "explain": "薪酬影响有能力的人是否选择从教并继续留在这一行业。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是教师执照？", "options": ["出售学校食品的许可证", "正式的教学许可", "修建学校的许可证", "经营校车服务的许可证"], "answer": 1, "explain": "执照为从教人员设定了最低标准。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是教师入职辅导计划？", "options": ["为校车司机提供的培训", "为厨师提供的培训", "为教师入职头几年提供的支持", "只为家长提供的培训"], "answer": 2, "explain": "入职辅导帮助新教师适应并不断提升。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是教师流动？", "options": ["教师乘飞机出行", "教师参加赛跑", "教师永远待在同一间教室", "教师在学校或地区之间调动"], "answer": 3, "explain": "教师流动影响哪些地区拥有足够的合格教师。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是教师多元化？", "options": ["学校中来自不同背景的教师", "外表都相同的教师", "只会说一种语言的教师", "没有受过培训的教师"], "answer": 0, "explain": "多元化的教师队伍可以帮助学生在教师身上看到自己。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 6, "q": "什么是教学领导？", "options": ["校长只关注体育", "校长专注于教学和学习", "校长只关注假期", "校长回避教师"], "answer": 1, "explain": "教学领导者帮助教师改进课堂实践。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "为什么学校需要校长？", "options": ["他们取代每间教室里的教师", "他们只教体育和体育教育", "他们指导教学并管理学校", "在管理良好的学校中，他们并不需要"], "answer": 2, "explain": "校长支持教师，并为学习指明方向。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "什么是可持续的教育融资？", "options": ["一次性花完、再不会有的资金", "仅来自一次彩票的资金", "只用于建筑的资金", "长期持续的资金"], "answer": 3, "explain": "可持续融资指多年持续、可靠的资金来源。", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "什么是教育援助？", "options": ["其他国家或组织提供的资金或支持", "教师为自己学校的用品而捐出的钱", "仅来自家长缴纳的学费的资金", "仅来自学校义卖、烘焙义卖和集市的资金"], "answer": 0, "explain": "教育援助来自捐助者，用于支持其他国家的学校。", "src": "UNESCO"}, {"ch": 7, "q": "ODA是什么的缩写？", "options": ["官方数字访问", "官方发展援助", "开放文档档案", "在线每日出勤"], "answer": 1, "explain": "ODA即官方发展援助，其中包括对教育的援助。", "src": "UNESCO"}, {"ch": 7, "q": "什么是国内资源动员？", "options": ["只向其他国家筹集资金", "通过出售学校筹集资金", "在国内为公共服务筹集资金", "从月球上筹集资金"], "answer": 2, "explain": "各国通过税收和其他国内收入为学校筹集资金。", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "为什么一些国家依赖外部教育援助？", "options": ["它们拥有无限的资金", "它们不想要学校", "它们无法花钱", "它们自身的资源有限"], "answer": 3, "explain": "国内资源有限可能导致依赖外部支持。", "src": "UNESCO"}, {"ch": 7, "q": "教育基金用来做什么？", "options": ["支付学校教育和学习项目的费用", "支付家庭假期和夏季旅行的费用", "为学校工作人员购买新车", "购买大型体育赛事的门票"], "answer": 0, "explain": "教育基金用于支付学校教育、教材和各项项目的费用。", "src": "UNESCO"}, {"ch": 8, "q": "1990年的宗滕会议产生了什么？", "options": ["只用于学校比赛的足球规则手册", "关于满足基本学习需求的宣言", "每一年学校假期的清单", "当年在整个地区推出的新货币"], "answer": 1, "explain": "《全民教育世界宣言》于1990年在宗滕通过。", "src": "UNESCO"}, {"ch": 8, "q": "什么是《全民教育世界宣言》？", "options": ["2030年为所有国家队制定的体育计划", "适用于所有学生的校服规范", "1990年承诺为所有人提供教育的宣言", "议会去年通过的教师薪酬法"], "answer": 2, "explain": "该宣言于1990年在宗滕通过，确立了全民教育。", "src": "UNESCO"}, {"ch": 8, "q": "2000年哪一项活动通过了《达喀尔行动框架》？", "options": ["足球世界杯", "奥运会", "贸易峰会", "世界教育论坛"], "answer": 3, "explain": "《达喀尔行动框架》于2000年在世界教育论坛上通过。", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "《仁川宣言》承诺什么？", "options": ["为终身学习提供包容、公平、优质的教育", "只为一小部分优秀学生提供大学教育", "每周只为学校球队提供体育和游戏", "只为所有学生提供假期和休息日"], "answer": 0, "explain": "《仁川宣言》促使各国提供终身学习的机会。", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "《达喀尔行动框架》除了儿童入学还包括什么？", "options": ["只为教师提供的识字教育", "成人识字和性别平等", "只在体育中进行的识字教育", "只为富裕国家提供的识字教育"], "answer": 1, "explain": "《达喀尔行动框架》包括成人识字和性别平等的目标。", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "哪一项千年发展目标旨在促进性别平等？", "options": ["目标1", "目标5", "目标3", "目标6"], "answer": 2, "explain": "千年发展目标3旨在促进性别平等和赋权妇女。", "src": "UN Millennium Development Goals (2000)"}, {"ch": 8, "q": "千年发展目标旨在减少什么？", "options": ["体育", "学校", "假期", "极端贫困和饥饿"], "answer": 3, "explain": "在其他目标中，千年发展目标旨在减少极端贫困和饥饿。", "src": "UN Millennium Development Goals (2000)"}, {"ch": 9, "q": "什么是优质的早期学习？", "options": ["回应性强、有趣且给予支持的学习", "严格而安静的学习", "只使用练习纸的学习", "避开成年人的学习"], "answer": 0, "explain": "优质的早期学习通过温暖、有趣的互动培养技能。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "为什么及早发现发育迟缓很重要？", "options": ["问题应等到上学时再处理", "在大脑快速发育的同时就可以开始提供支持", "应该给儿童贴上终身标签", "应该责怪家长"], "answer": 1, "explain": "及早发现使支持能够在大脑快速发育的同时开始。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "为什么幼儿教育工作者很重要？", "options": ["不需要工作人员", "工作人员只负责打扫房间", "有技能的工作人员对儿童有很大影响", "工作人员对儿童没有影响"], "answer": 2, "explain": "受过培训的幼教工作者塑造儿童的学习和福祉。", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "什么是儿童友好空间？", "options": ["只卖玩具和糖果给儿童的商店", "完全没有窗户和门、供学生使用的建筑", "儿童一整天与他人隔离的房间", "供儿童学习和玩耍的安全场所"], "answer": 3, "explain": "儿童友好空间为儿童提供安全的学习和玩耍场所，在危机中尤其重要。", "src": "UNESCO GEM Report 2026"}, {"ch": 9, "q": "对婴儿来说，刺激性环境是什么意思？", "options": ["大量的交谈、触摸和游戏", "完全安静", "昏暗的房间", "持续的大声噪音"], "answer": 0, "explain": "刺激性环境通过互动促进大脑发育。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "为什么幼儿阶段是政策优先事项？", "options": ["对儿童和家庭没有任何好处", "早期投资日后回报很高", "只花钱而不带来回报", "只帮助已经工作的成年人"], "answer": 1, "explain": "早期投资有助于儿童学习，并减少日后的成本。", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "什么是萌发性读写能力？", "options": ["只针对成年人的读写能力", "只在大学里阅读", "通往阅读和写作的早期技能", "只阅读数字"], "answer": 2, "explain": "萌发性读写能力包括字母认知和押韵等早期技能，它们通向阅读。", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "什么是韵律意识？", "options": ["在墙上画韵脚", "只唱大声的歌", "只在纸上写韵文", "听辨和说出押韵的声音"], "answer": 3, "explain": "韵律意识帮助儿童听到词语中的声音。", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "双语读写能力包括什么？", "options": ["用两种语言阅读和写作", "只读数字", "只画画", "只听"], "answer": 0, "explain": "双语读写能力培养用两种语言阅读的能力。", "src": "UNESCO, International Mother Language Day"}, {"ch": 10, "q": "为什么读写能力与就业有关？", "options": ["工作从不需要阅读", "许多工作要求阅读和写作", "读写能力只针对教师", "读写能力与工作没有关系"], "answer": 1, "explain": "读写能力帮助人们阅读说明、撰写报告并学习新技能。", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "什么是信息素养？", "options": ["对身边所有人隐藏信息", "背下读过的每本书的每一页", "善于查找、判断和使用信息", "无视新闻和所有时事"], "answer": 2, "explain": "信息素养帮助人们判断信息来源，并负责任地使用信息。", "src": "UNESCO"}, {"ch": 10, "q": "为什么许多国家在早期阅读中使用当地语言？", "options": ["不允许使用当地语言", "当地语言使阅读更困难", "当地语言只为成年人服务", "儿童最能在他们说的语言中学习"], "answer": 3, "explain": "当儿童理解所见的词语时，早期阅读会更容易。", "src": "UNESCO, International Mother Language Day"}, {"ch": 10, "q": "为什么写作练习很重要？", "options": ["它把阅读知识转化为沟通能力", "与阅读技能毫无关系", "只对学习艺术的学生重要", "只用画画取代阅读"], "answer": 0, "explain": "写作练习帮助学习者表达想法并深化阅读。", "src": "UNESCO GEM Report 2026"}, {"ch": 11, "q": "什么是包容性课程？", "options": ["排斥部分学习者的课程", "重视并包含所有学习者的课程", "只针对一个群体的课程", "没有任何科目的课程"], "answer": 1, "explain": "包容性课程反映所有学习者的需求和身份。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "什么是多感官教学？", "options": ["只使用声音", "在安静中教学", "在课堂上同时运用视觉、听觉和触觉", "只用眼罩进行教学"], "answer": 2, "explain": "多感官教学帮助以不同方式学习效果最好的学习者。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "教育中的辅助技术是什么？", "options": ["让所有学生的学习变得更难的游戏", "阻止学生阅读课本的工具", "只用于体育和游戏的设备", "帮助残疾学习者参与的工具"], "answer": 3, "explain": "辅助技术包括屏幕阅读器、助听设备和沟通辅助工具。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "考试的合理便利是什么？", "options": ["如延长时间或提供朗读人员等调整", "对所有人完全取消考试", "让部分学生的考试变得更难", "对考试额外收费"], "answer": 0, "explain": "便利措施使考试公平，同时不改变考查的内容。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "为什么学校应收集残疾数据？", "options": ["为了按残疾程度给儿童排名", "为了规划支持并监测融合情况", "为了阻止儿童入学", "为了出售学校设备"], "answer": 1, "explain": "残疾数据帮助学校规划支持，并核实儿童是否得到融合。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "教育中的刻板印象是什么？", "options": ["每年一次的学校考试", "经过农场的校车路线", "对某一群体固定且往往不公平的看法", "装满许多书的书包"], "answer": 2, "explain": "刻板印象会限制学习者认为自己能够达到的目标。", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "学校中的归属感是什么？", "options": ["在课堂上独自一人", "被排除在课程之外", "被迁到另一个城市", "感到被接纳和重视"], "answer": 3, "explain": "归属感帮助学习者投入学习并留在学校。", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "残疾人的无障碍通用是什么意思？", "options": ["为包括残疾人在内的每个人提供无障碍", "只为没有残疾的人提供无障碍", "只在一座建筑中提供无障碍", "只在特定日子提供无障碍"], "answer": 0, "explain": "无障碍通用意味着教育向所有人开放，并提供每个人所需的支持。", "src": "UN CRPD (2006), Article 24"}], "10": [{"ch": 0, "q": "哪条原则意味着《2030年议程》首先要惠及最落后的人群？", "options": ["不让任何人掉队", "适者生存", "不惜一切代价追求增长", "各国各自为政"], "answer": 0, "explain": "“不让任何人掉队”意味着优先考虑最弱势的人群。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "哪项SDG 4指标追踪小学入学前一年的有组织学习参与情况？", "options": ["指标4.1.1", "指标4.2.2", "指标4.5.1", "指标4.7.1"], "answer": 1, "explain": "指标4.2.2衡量的是正式小学入学年龄前一年的有组织学习参与情况。", "src": "UN SDG Report 2026"}, {"ch": 0, "q": "目标4.a至4.c的目的是什么？", "options": ["编写考试题目", "选择学校的颜色", "提供实施教育的手段", "关闭大学"], "answer": 2, "explain": "这些目标侧重于设施、奖学金和教师供应。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "为什么要用指标和数据来衡量SDG 4的目标？", "options": ["为了让报告变得更长", "为了避免做出决定", "为了取代教师", "为了检验进展是否真实、公平"], "answer": 3, "explain": "指标和分类数据能显示进展以及不平等状况。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "SDG 4与SDG 1（无贫穷）之间是什么关系？", "options": ["教育有助于减贫，而贫困也会限制教育", "两者在任何国家都毫无关联", "教育导致贫困，并使家庭每年更加贫穷", "贫困只影响儿童在学校的体育表现"], "answer": 0, "explain": "教育与贫困在两个方向上都紧密相连。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "SDG监测中的基线是什么？", "options": ["标志长跑结束的终点线", "衡量进展所依据的起点", "书包底部存放旧书的地方", "当地商店里一本全新教科书的价格"], "answer": 1, "explain": "基线是用于衡量变化的初始数据。", "src": "UN SDG Report 2026"}, {"ch": 1, "q": "义务教育是什么？", "options": ["人人都可以选择是否接受的教育", "只针对成年人的教育", "法律要求儿童必须接受的教育", "被禁止的教育"], "answer": 2, "explain": "义务教育意味着儿童必须在法定年龄之前上学。", "src": "UNESCO"}, {"ch": 1, "q": "教育方面的有条件现金转移是什么？", "options": ["给予教师用于度假的资金", "仅由捐助者支付的学费", "仅用于修建道路的资金", "若儿童上学则给予家庭的资金"], "answer": 3, "explain": "有条件现金转移鼓励家庭送子女上学。", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "政府为什么取消学费？", "options": ["为了扩大贫困家庭的入学机会", "为了减少学生人数", "为了让学校变得没那么有用", "为了停止支付教师工资"], "answer": 0, "explain": "取消学费有助于较贫困的儿童入学并坚持读下去。", "src": "UNESCO"}, {"ch": 1, "q": "什么是失学青少年？", "options": ["经常在家里网上学习的成年人", "未在学校就读的中学年龄青年", "整天在花园里玩耍的幼儿园儿童", "今年在本校休假的教师"], "answer": 1, "explain": "失学青少年是没有在任何学校注册入学的青少年。", "src": "UNESCO"}, {"ch": 1, "q": "对儿童来说，灵活学制是什么？", "options": ["对儿童完全没有规则或课表的上学方式", "仅在夜间为全镇居民开设的上学方式", "根据儿童的工作或家庭需要安排的上学方式", "任何时候教室里都没有教师的上学方式"], "answer": 2, "explain": "灵活学制帮助无法全日制上学的儿童。", "src": "UNESCO"}, {"ch": 1, "q": "为什么安全的交通对女童入学很重要？", "options": ["任何学校出行都不需要交通工具", "女童不能去家以外的任何地方", "女童更喜欢走很远的路去学校", "不安全或路途遥远的行程可能使女童留在家里"], "answer": 3, "explain": "安全的交通可以极大地改善女童的出勤率。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 1, "q": "什么是入学动员活动？", "options": ["让儿童进入学校的宣传运动", "赛车比赛", "仅为学校筹款的晚宴", "体育锦标赛"], "answer": 0, "explain": "入学动员活动鼓励家庭为子女办理入学登记。", "src": "UNESCO"}, {"ch": 2, "q": "完成初中学段是什么意思？", "options": ["完成幼儿园", "完成中等教育的第一阶段", "完成大学", "完成一个假期课程"], "answer": 1, "explain": "初中是中等教育的第一阶段。", "src": "UNESCO"}, {"ch": 2, "q": "为什么许多国家的青少年会辍学？", "options": ["他们每年都学得太快、太早结束学业", "他们都获得了进入最好学校的奖学金", "工作压力、费用，以及觉得学习没有用", "学期中有太多假期和休息日"], "answer": 2, "explain": "工作压力、费用以及觉得学习没有用，常常把学生推出校门。", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "对已经离开学校的年轻人来说，什么是学习路径？", "options": ["通往商店、向顾客销售商品的通道", "最终不获得任何资格的道路", "仅对合格教师和工作人员开放的道路", "通往获得认可资格的重返学习之路"], "answer": 3, "explain": "学习路径帮助年轻人重返学习并获得资格。", "src": "UNESCO"}, {"ch": 2, "q": "完成高中学段为什么与就业相关？", "options": ["它开辟了更多的工作和培训机会", "它取消了所有就业机会", "这意味着之后不再需要学习", "它只帮助艺术家"], "answer": 0, "explain": "完成高中学段扩大了就业和继续深造的机会。", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "什么是帮助儿童留在学校的校本干预？", "options": ["每周每天都提前关闭学校", "在校内开展的支持行动，如导师辅导", "每周从课表中删除所有课程", "无视已经缺课数周的学生"], "answer": 1, "explain": "校本支持帮助有辍学风险的学生。", "src": "UNESCO"}, {"ch": 2, "q": "为什么现金和食物支持与完成学业相关？", "options": ["它们取代了课堂上的全部教学", "它们使每年更多儿童提前辍学", "它们减轻了迫使儿童辍学的费用负担", "它们使上学的一天变得更长、更累"], "answer": 2, "explain": "对费用的支持可以帮助儿童坚持到完成学业。", "src": "UNESCO"}, {"ch": 2, "q": "为什么一些学生在多次考试不及格后辍学？", "options": ["考试从来不会不及格", "考试不及格对学生有帮助", "失败会得到奖励", "反复失败会打击学习者的积极性"], "answer": 3, "explain": "没有支持的反复失败会使学生失去信心并离开学校。", "src": "UNESCO"}, {"ch": 3, "q": "什么是“按适宜水平教学”？", "options": ["按能力水平而非年龄对学习者分组", "只教年龄最大的学习者", "只用英语教学", "没有计划地教学"], "answer": 0, "explain": "“按适宜水平教学”按学习者已经能做到的水平而非年龄来分组。", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "什么是基础学习？", "options": ["科学、法律和医学方面的高级大学研究", "支撑后续学习的基本读、写和算术能力", "整个学年只有体育和运动", "只有艺术史以及古代绘画和雕塑研究"], "answer": 1, "explain": "基础学习是此后所有教育的基石。", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "哪项国际研究测试小学阶段的阅读能力？", "options": ["PISA", "TIMSS", "PIRLS", "ICAO测试"], "answer": 2, "explain": "PIRLS，即国际阅读素养进展研究，测试小学阶段的阅读能力。", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "TIMSS衡量什么？", "options": ["音乐和舞蹈", "体育和健身", "烹饪技能", "数学和科学成就"], "answer": 3, "explain": "TIMSS，即国际数学与科学趋势研究，衡量数学和科学成就。", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "什么是低利害测试？", "options": ["结果不决定学生未来的测试", "决定谁被开除的测试", "没有任何题目的测试", "只用于招聘教师的测试"], "answer": 0, "explain": "低利害测试让教师在没有高压的情况下了解学习情况。", "src": "UNESCO"}, {"ch": 3, "q": "为什么同一国家内的学习成果存在差异？", "options": ["只有天气会造成不同学校之间的成绩差异", "收入、语言、地点和性别都会产生影响", "只有学校的颜色决定学生的表现", "只有校车时刻表决定学生的表现"], "answer": 1, "explain": "学习成果受到许多社会和经济因素的影响。", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "学习中的认知技能是什么？", "options": ["每晚睡得香的能力", "全年在校队踢足球的能力", "记忆、推理和解决问题等思维能力", "为家人在家做简单饭菜的能力"], "answer": 2, "explain": "认知技能支撑各学科的推理和学习。", "src": "UNESCO"}, {"ch": 3, "q": "为什么学习评估对政策很重要？", "options": ["它们取代全国每个社区的学校", "它们每年只给最优秀的学生颁奖", "它们消除了任何学校对教师的需求", "它们显示学习最薄弱、需要支持的地方"], "answer": 3, "explain": "评估数据帮助政府决定在哪里投资和提供支持。", "src": "UNESCO GEM Report 2026"}, {"ch": 4, "q": "21世纪技能的“四个C”是什么？", "options": ["创造力、批判性思维、沟通和协作", "每周在学校烹饪、清洁、骑车和涂色", "在计算机实验室里计算、计数、抄写和编程", "为校队加油、指导、比赛和做饭"], "answer": 0, "explain": "“四个C”被广泛用来描述现代工作和生活的关键技能。", "src": "UNESCO"}, {"ch": 4, "q": "STEM代表什么？", "options": ["体育、教学、考试和音乐", "科学、技术、工程和数学", "口语、戏剧、编辑和市场", "社会学、旅游、经济学和媒体"], "answer": 1, "explain": "STEM涵盖科学、技术、工程和数学。", "src": "UNESCO"}, {"ch": 4, "q": "学习者的数字安全是什么？", "options": ["每天与在网上认识的所有人分享密码", "无视网络隐私，分享每一张照片", "保护个人数据并识别网络风险", "与网上认识的陌生人面对面见面并保密"], "answer": 2, "explain": "数字安全帮助学习者保护自己的信息，并在网上保持安全。", "src": "UNESCO"}, {"ch": 4, "q": "在学习中合乎伦理地使用技术是什么？", "options": ["抄袭他人的作品而不注明出处", "在网上欺负同学", "分享私人照片", "诚实、尊重并经同意地使用"], "answer": 3, "explain": "合乎伦理地使用技术尊重他人，也尊重学术诚信。", "src": "UNESCO"}, {"ch": 4, "q": "什么是能力框架？", "options": ["学习者应获得的技能和知识清单", "一种有多层楼和房间的学校建筑", "可以参加的学校体育、游戏和社团清单", "只针对考试和测验、没有其他学习的计划"], "answer": 0, "explain": "能力框架规定学习者应该能够做到什么。", "src": "UNESCO"}, {"ch": 4, "q": "为什么创业与SDG 4有关？", "options": ["与就业或解决问题完全无关", "它培养创造就业机会和解决问题的技能", "只教授销售和商店管理", "使人们永远找不到任何工作"], "answer": 1, "explain": "创业培养主动性和解决问题的能力。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "什么是技能缺口？", "options": ["学校墙上需要本学期紧急维修的裂缝", "忙碌的上学日里两节长课之间的休息", "人们所具备的技能与工作需求之间的不匹配", "本学期学校课表中缺少的一场考试"], "answer": 2, "explain": "技能缺口使人们难以找到工作，雇主也难以招满岗位。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "为什么职业技术教育与培训（TVET）对青年就业很重要？", "options": ["它取代所有学术学习", "它只适用于成年人", "它从来没有用处", "它提供与工作相关的实用技能"], "answer": 3, "explain": "TVET为青年提供可直接就业的技能和通向工作的途径。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "什么是基于性别的学习障碍？", "options": ["使某一性别的学习更加困难的规则或规范", "帮助每位学生更好学习的障碍", "只影响学校教师的障碍", "对学习没有任何实际影响的障碍"], "answer": 0, "explain": "基于性别的障碍包括限制女童或男童学习的规范和做法。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "缺乏卫生设施会如何影响学校里的女童？", "options": ["在任何国家都与学校出勤无关", "没有私人厕所和卫生用品，女童可能会缺课", "只影响在同一所学校学习的男童", "是九年级学生学习的一门课程"], "answer": 1, "explain": "获得卫生设施和私人厕所有助于女童留在学校。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "童工政策的目标是什么？", "options": ["强迫儿童每天在田里长时间劳动", "停止村里和镇上所有儿童的教育", "保护儿童免受损害其学习和健康的工作", "付钱让儿童逃学并每天待在家里"], "answer": 2, "explain": "童工政策保护儿童学习和健康成长的权利。", "src": "UNESCO"}, {"ch": 5, "q": "教育中的少数群体指什么？", "options": ["总是最富有的群体", "在考试中总是表现最好的群体", "从不上学的群体", "比主体人口规模小的群体"], "answer": 3, "explain": "少数群体是人口中规模较小的群体，可能面临障碍。", "src": "UNESCO"}, {"ch": 5, "q": "为什么土著学习者通常需要与文化相关的教育？", "options": ["尊重他们的身份并提高学习效果", "完全用另一种语言取代他们的语言", "任何地方的任何学校都不需要", "只影响学校里的体育和游戏"], "answer": 0, "explain": "与文化相关的教育帮助土著学习者感到被重视，并更好地学习。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "公平政策中的精准帮扶是什么？", "options": ["把资源给最富有的人", "将资源集中用于被落下的群体", "只把相同的资源给最强的人", "忽视有需要的群体"], "answer": 1, "explain": "精准帮扶将力量集中在最需要帮助的群体上。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "什么是性别敏感课程？", "options": ["只针对男童、在每所学校都教授的课程", "传授关于女童和男童的刻板印象的课程", "避免刻板印象、平等对待所有学习者的课程", "对任何学生都没有学科的课程"], "answer": 2, "explain": "性别敏感课程挑战刻板印象，并支持所有学习者。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "交叉性歧视描述的是什么？", "options": ["只发生在一个地方的歧视", "总是公平的歧视", "只针对教师的歧视", "多种相互重叠的歧视形式"], "answer": 3, "explain": "交叉性歧视是指多种身份相互叠加，造成不利处境。", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "目标4.c中的教师供应是什么？", "options": ["可用的合格教师数量", "假期的数量", "上下课铃声的数量", "课桌的数量"], "answer": 0, "explain": "目标4.c侧重于增加合格教师的供应。", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "为什么各国需要招聘更多教师？", "options": ["因为不需要教师", "为了满足不断增长的需求并替代离职的教师", "为了把班级规模降到零", "为了关闭学校"], "answer": 1, "explain": "招聘是为了跟上学生人数增长和教师退休的步伐。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是合同制教学？", "options": ["凭终身承诺任教", "没有报酬的教学", "以短期临时合同任教", "只通过电话教学"], "answer": 2, "explain": "合同制教师通常缺乏保障，这可能影响他们的留任。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是职前教师教育？", "options": ["退休之后的培训", "只针对校长的培训", "针对家长的培训", "开始任教之前的培训"], "answer": 3, "explain": "职前培训使人们在开始任教之前做好准备。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是在职培训？", "options": ["在已经任教期间进行的培训", "针对非教师人员的培训", "依法只在假期进行的培训", "取代全部教学工作的培训"], "answer": 0, "explain": "在职培训帮助教师在工作中不断提升。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是教师行为准则？", "options": ["只有教职员工使用的教师秘密用语", "规定专业行为预期的规则", "全年教师假期的清单", "只适用于教师的学校着装规定"], "answer": 1, "explain": "行为准则规定了教师应如何对待学习者。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "为什么教师需要接受融合教学方面的培训？", "options": ["没有必要", "为了可以回避学习者", "为了支持有不同需求的学习者", "为了可以教授更少的科目"], "answer": 2, "explain": "融合教学培训帮助教师满足学习者的各种需求。", "src": "UN CRPD (2006), Article 24"}, {"ch": 6, "q": "什么是教师职业倦怠？", "options": ["过于精力充沛的教师", "教得太好的教师", "薪水过高的教师", "因压力工作而导致的长期疲惫"], "answer": 3, "explain": "职业倦怠降低幸福感，并可能促使教师离开教职。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "SDG 4的资金缺口衡量的是什么？", "options": ["在当前支出之外仍需的额外资金", "花在体育上的资金", "存在银行里的资金", "支付给学校供应商的资金"], "answer": 0, "explain": "资金缺口显示要实现教育目标还需要多少额外投入。", "src": "UNESCO GEM Report 2026"}, {"ch": 7, "q": "税收收入对教育有什么贡献？", "options": ["只用来支付假期的资金", "政府用来资助学校的资金", "用来取代教师的资金", "总是被浪费的资金"], "answer": 1, "explain": "税收收入是政府教育经费的主要来源。", "src": "UNESCO"}, {"ch": 7, "q": "教育的预算外资金是什么？", "options": ["花在假期上的资金", "藏在床底下的钱", "在正式预算之外支出的资金", "花在私人飞机上的资金"], "answer": 2, "explain": "预算外资金可能使教育总支出难以追踪。", "src": "UNESCO"}, {"ch": 7, "q": "捐助者为什么有时资助教育？", "options": ["通过经营儿童学校获取巨额利润", "每年关闭最贫穷国家的学校", "阻止儿童在任何学校学习", "为资源较少的国家的儿童提供支持"], "answer": 3, "explain": "捐助者经常资助教育，以帮助需要额外支持的国家。", "src": "UNESCO"}, {"ch": 7, "q": "债务如何影响教育支出？", "options": ["高额的债务偿还可能减少用于学校的资金", "债务自动为学校提供资金", "债务完全没有影响", "债务只影响体育"], "answer": 0, "explain": "在偿债上支出大量资金的政府，用于教育的钱可能会更少。", "src": "UNESCO"}, {"ch": 7, "q": "教育领域的物有所值审计是什么？", "options": ["检查校服的价格和质量", "检查支出是否取得良好成效", "检查每位教师请假休息多少天", "检查每天午餐提供的学校食品"], "answer": 1, "explain": "物有所值审计检查教育经费是否带来学习成果。", "src": "UNESCO"}, {"ch": 7, "q": "为什么学校需要稳定的资金？", "options": ["以便改变天气", "以便不需要任何教师", "以便规划教师、教材和维修", "以便提前关门"], "answer": 2, "explain": "稳定的资金使学校能够提前规划并保持学习的持续进行。", "src": "UNESCO"}, {"ch": 7, "q": "校级拨款有什么作用？", "options": ["给教师放假", "只给儿童发奖品", "给家庭发汽车", "为学校提供满足当地需要的资金"], "answer": 3, "explain": "学校拨款使学校能够回应当地的优先事项。", "src": "UNESCO"}, {"ch": 8, "q": "哪项1994年的宣言推动了为所有儿童提供包容性学校？", "options": ["《萨拉曼卡宣言》", "《东京宣言》", "《开罗条约》", "《利马计划》"], "answer": 0, "explain": "1994年的《萨拉曼卡宣言》推动了为所有儿童提供包容性学校。", "src": "UN CRPD (2006), Article 24"}, {"ch": 8, "q": "《萨拉曼卡宣言》是哪一年通过的？", "options": ["1948年", "1994年", "1989年", "2015年"], "answer": 1, "explain": "《萨拉曼卡宣言》于1994年通过。", "src": "UN CRPD (2006), Article 24"}, {"ch": 8, "q": "1990年宗滕会议在学校教育之外还呼吁什么？", "options": ["只为成年人提供学校教育", "只有体育", "为儿童、青年和成年人提供学习", "十岁以后就不再学习"], "answer": 2, "explain": "宗滕会议强调所有人的终身学习。", "src": "UNESCO"}, {"ch": 8, "q": "《达喀尔行动框架》为“全民教育”设定了几个目标？", "options": ["三个", "十个", "十七个", "六个"], "answer": 3, "explain": "《达喀尔行动框架》为全民教育设定了六个目标。", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "1948年《世界人权宣言》对教育有何规定？", "options": ["教育是一项人权", "教育是一种奢侈品", "教育只针对男童", "教育是可选的"], "answer": 0, "explain": "《世界人权宣言》规定教育是一项人权。", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "1990年宗滕会议为什么重要？", "options": ["禁止了全国所有学校", "确立了全民教育的全球承诺", "为全镇所有商店规定了书价", "当年结束了大多数国家的教师培训"], "answer": 1, "explain": "宗滕会议确立了全民教育的全球承诺。", "src": "UNESCO"}, {"ch": 8, "q": "重大全球教育承诺有什么共同点？", "options": ["它们从未被执行", "它们只适用于私立学校", "它们设定各国政府同意努力实现的目标", "它们只适用于一个国家"], "answer": 2, "explain": "全球承诺设定了各国政府同意努力实现的共同目标。", "src": "UNESCO"}, {"ch": 8, "q": "国际教育日是哪一天？", "options": ["5月1日", "10月31日", "12月25日", "1月24日"], "answer": 3, "explain": "联合国教科文组织每年1月24日纪念国际教育日。", "src": "UNESCO"}, {"ch": 9, "q": "什么是“照护框架”（Nurturing Care Framework）？", "options": ["将幼儿期的健康、营养、照护和学习结合起来的框架", "只在全国大城市修建学校的计划", "针对幼儿的校规和惩罚清单", "每周在操场上进行体育和游戏的计划"], "answer": 0, "explain": "该框架将幼儿期的健康、营养、回应性照护、安全和学习联系起来。", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "幼儿期的“大脑构建”是什么意思？", "options": ["学校建筑的形状", "生命早期大脑连接形成的方式", "学校课桌的设计", "城市的布局"], "answer": 1, "explain": "早期经历塑造了构成大脑结构的连接。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "早期学习中的家长参与是什么？", "options": ["家长从不参加任何学校活动", "家长付钱请教师为孩子私下授课", "家长积极参与孩子的学习", "家长完全回避孩子和他们的功课"], "answer": 2, "explain": "有参与的家长在家里和学校都支持学习。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "幼儿期的游戏和探索是什么？", "options": ["在课堂上连续几个小时一动不动地坐着", "整节课都在抄写黑板上的内容", "学校里每天重复的无声操练", "帮助儿童发现想法的实践活动"], "answer": 3, "explain": "游戏和探索帮助儿童认识世界。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "什么使幼儿教育具有高质量？", "options": ["训练有素的工作人员、良好的空间和温暖的互动", "教室里没有成年人的大班", "只发放练习纸而没有教学", "没有成年人或活动的长时间安静"], "answer": 0, "explain": "质量取决于熟练的工作人员、安全的空间和温暖的关系。", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "幼儿期的依恋是什么？", "options": ["一种玩具", "儿童与照护者之间的安全纽带", "固定的学校课表", "对家庭征收的税"], "answer": 1, "explain": "安全的依恋支持儿童的情感和社会性发展。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "入学准备除学业技能外还包括什么？", "options": ["每天大声朗读单词", "在纸上写字母和数字几个小时", "健康、情绪幸福感和社交技能", "每学期比赛中的体力和速度"], "answer": 2, "explain": "入学准备包括健康、社交和情感技能，以及学业技能。", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "家庭中的识字环境是什么？", "options": ["没有书的安静房间", "只有电视", "与家人完全没有接触", "家中的书籍、交谈和阅读习惯"], "answer": 3, "explain": "家庭中的识字环境有助于提高阅读能力。", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "什么是阅读文化？", "options": ["共同的习惯以及对阅读的重视", "在学校礼堂里表演的一种舞蹈", "在学校操场上进行的一种运动", "全天使用的学校铃声系统"], "answer": 0, "explain": "阅读文化使阅读成为日常生活的一部分。", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "为什么识字水平低的成年人难以找到工作？", "options": ["工作从来不需要阅读", "许多工作需要阅读和写作能力", "成年人无论如何都找不到工作", "雇主更喜欢文盲"], "answer": 1, "explain": "识字水平低可能限制获得许多工作和培训的机会。", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "什么是小学后识字教育？", "options": ["出生前的识字教育", "只在幼儿园进行的识字教育", "小学之后的读写能力", "只针对教师的识字教育"], "answer": 2, "explain": "小学后识字教育在小学之后培养并维持阅读和写作能力。", "src": "UNESCO"}, {"ch": 10, "q": "阅读困难的一个原因是什么？", "options": ["一种饮食方式", "一种考试", "一种天气", "阅读障碍"], "answer": 3, "explain": "部分阅读困难是由阅读障碍引起的，需要专门的支持。", "src": "UN CRPD (2006), Article 24"}, {"ch": 10, "q": "什么有助于农村社区获得书籍？", "options": ["附近的图书馆或图书配送", "禁止书籍", "以非常高的价格出售书籍", "只把书籍放在城市里"], "answer": 0, "explain": "通过图书馆和流动服务，可以改善农村地区获得书籍的条件。", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "什么是流动图书馆？", "options": ["只设在停车场里的图书馆", "深入社区的图书馆", "出售手机的图书馆", "对公众关闭的图书馆"], "answer": 1, "explain": "流动图书馆把书籍送到住在远离图书馆的人们身边。", "src": "UNESCO"}, {"ch": 11, "q": "《联合国残疾人权利公约》第24条涵盖什么？", "options": ["面向所有学生的体育和游戏", "家庭在家中的烹饪和饮食", "教育，包括包容性教育", "学校团体的假期和旅游"], "answer": 2, "explain": "《残疾人权利公约》第24条规定了包容性教育的权利。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "对学校而言，无障碍是什么意思？", "options": ["只有建筑前面的一扇门供所有人使用", "只有教师才被允许阅读的材料", "对学生家庭保密的信息", "每个人都能使用的建筑、材料和信息"], "answer": 3, "explain": "无障碍使学校的空间和信息能够为所有人使用。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "什么是包容性教学法？", "options": ["旨在让每位学习者都能参与的教学方法", "每天只教每个班级最优秀的学习者", "用一种固定方式教学，希望适合所有学习者", "在教室里没有任何教材或资源的教学"], "answer": 0, "explain": "包容性教学法调整教学，使所有学习者都能参与并学习。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "为什么学校需要支持人员来促进融合？", "options": ["不需要支持人员", "帮助学习者参与课程和日常生活", "用来取代所有教师", "用来把学习者隔开"], "answer": 1, "explain": "支持人员帮助残疾学习者参与学校生活。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "什么是最少限制环境？", "options": ["整座学校教学楼里最拥挤的教室", "离所有其他教室最远的房间", "学习者能够在最大程度的融合中学习的环境", "没有窗户、没有光线也没有座位的房间"], "answer": 2, "explain": "最少限制环境支持尽可能多融合的学习。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "对残疾学习者而言，充分参与是什么意思？", "options": ["只在特殊日子上学", "在外面观看", "被安排在单独的房间", "平等地参与学校生活的各个方面"], "answer": 3, "explain": "充分参与意味着学习者可以参加所有活动和学习。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "残疾的社会模式是什么？", "options": ["残疾是由社会中的障碍塑造的", "残疾是个人的过错", "学校里可以忽略残疾", "残疾只影响工作"], "answer": 0, "explain": "社会模式认为，限制参与的是社会中的障碍，而不仅仅是损伤本身。", "src": "UN CRPD (2006), Article 24"}, {"ch": 0, "q": "SDG 4与SDG 5（性别平等）之间有什么联系？", "options": ["两者没有联系", "女童的教育支持性别平等", "性别平等会减少学习", "女童不应该上学"], "answer": 1, "explain": "教育是实现性别平等的关键工具，而性别平等是第5目标。", "src": "UN 2030 Agenda (2015)"}], "11": [{"ch": 0, "q": "2030年议程如何描述各目标之间的关系？", "options": ["相互关联、不可分割", "彼此独立、互不相关", "相互竞争、彼此冲突", "可选择、可忽略"], "answer": 0, "explain": "《2030年议程》将各目标描述为相互关联、不可分割的整体。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "国家教育监测系统提供什么？", "options": ["只有每所学校一年中的假期日期", "定期数据，用于跟踪进展并找出差距", "只有每个班级优秀学生的考试奖品", "只有镇上新学校的建筑设计"], "answer": 1, "explain": "监测系统收集数据，让政府了解进展和差距。", "src": "UNESCO GEM Report 2026"}, {"ch": 0, "q": "什么是EMIS？", "options": ["学校乐队使用的一套电子乐器", "只供教师在期末使用的阅卷工具", "收集学校数据的教育管理信息系统", "所有校舍的能源管理计划"], "answer": 2, "explain": "EMIS即教育管理信息系统，用于记录学校和学习者数据。", "src": "UNESCO GEM Report 2026"}, {"ch": 0, "q": "什么是可持续发展的政策一致性？", "options": ["各部门互不理会、完全单独行事", "每年都有意相互冲突的政策", "恰好止步于每个区边界的政策", "让各部门政策相互配合、彼此支持"], "answer": 3, "explain": "政策一致性指不同政策领域共同朝着同一目标努力。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "SDG 4的本地化是什么意思？", "options": ["根据当地优先事项和情况调整目标", "原样照搬某一国的计划", "忽视当地需求", "把学校搬到月球"], "answer": 0, "explain": "本地化帮助社区把全球目标调整为适合自身的情况。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "教育政策中的问责是什么？", "options": ["逃避学校结果的一切责任", "要求领导者对结果和支出负责", "向公众和媒体隐瞒结果", "把每一次失败都归咎于学习者"], "answer": 1, "explain": "问责指领导者需对教育资源的使用方式作出说明。", "src": "UNESCO"}, {"ch": 0, "q": "教育中的多利益相关方参与是什么？", "options": ["每项决定都只让政府官员参与", "只让私营企业及其员工参与", "让政府、家庭、教师和社区都参与进来", "每项决定都不让学生以外的任何人参与"], "answer": 2, "explain": "多利益相关方方式把各方聚在一起共同规划和监测教育。", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "什么是教育部门规划？", "options": ["只针对每个城镇体育场和游乐场的计划", "某一学区某一所学校一学期的课表", "每年全国假期日期的列表", "规定教育优先事项和行动的计划"], "answer": 3, "explain": "部门规划指导政府在整个教育领域如何投入和行动。", "src": "UNESCO"}, {"ch": 1, "q": "什么是校外儿童调查？", "options": ["找出未入学儿童的调查", "对城里主要道路上校车的调查", "对全国教师假期的调查", "对每年各城镇校服穿着情况的调查"], "answer": 0, "explain": "校外儿童调查帮助政府找到需要入学的儿童。", "src": "UNESCO"}, {"ch": 1, "q": "为什么普及入学需要的不仅是建校？", "options": ["仅仅建校对每个人来说总是足够的", "成本、距离、歧视和质量也很重要", "入学只取决于每个季节的天气", "任何地区的任何家庭都从不存在入学问题"], "answer": 1, "explain": "入学取决于许多因素，而不仅仅是校舍数量。", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "什么是与年龄相符的入学？", "options": ["儿童无论年龄都可以就读任何年级", "儿童从未入学", "儿童就读于与其年龄相匹配的年级", "儿童只在大学就读"], "answer": 2, "explain": "与年龄相符的入学有助于儿童在适宜的水平上学习。", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "什么是超龄学习者？", "options": ["太老而无法在任何教室任教的教师", "提前读完年级后离开学校的学习者", "档案中没有记录出生日期的学习者", "年龄超过其年级正常年龄的学习者"], "answer": 3, "explain": "超龄学习者往往需要灵活的项目来补上落下的课程。", "src": "UNESCO"}, {"ch": 1, "q": "学校停课期间的远程学习是什么？", "options": ["利用技术或材料在远处学习", "每天只在教师所在的同一房间里学习", "完全安静、不说话地学习", "学校关闭后只在夜间学习"], "answer": 0, "explain": "远程学习让学校无法开放时教育仍能继续进行。", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "停课为什么会损害学习？", "options": ["没有任何影响", "儿童失去时间，可能落后", "总是能提高学习效果", "只影响教师"], "answer": 1, "explain": "长期停课会造成学习损失，尤其对弱势儿童影响更大。", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "什么是学习者的数字包容？", "options": ["在日常生活和每项学习任务中都不使用任何技术", "每天所有课程都只用纸和铅笔", "获得设备、网络连接和使用技能", "拥有汽车并每天和朋友开车上学"], "answer": 2, "explain": "数字包容意味着每个人都能获取和使用数字学习工具。", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "为什么一些学习者在家难以学习？", "options": ["他们更喜欢长时间感到无聊和乏味", "家里的环境总是比学校更加理想舒适", "他们从来都不想在任何情况下学习", "家中没有安静的空间、设备或支持"], "answer": 3, "explain": "家庭条件会影响学习者远程学习的效果。", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "年级之间的衔接是什么意思？", "options": ["不离开学校，逐级升入下一年级", "永远重读同一年级，从不升级", "永久离校，再也不回到任何班级", "每年转入另一国家的新学校"], "answer": 0, "explain": "衔接指学习者稳步地逐级升学。", "src": "UNESCO"}, {"ch": 2, "q": "什么是辍学预防政策？", "options": ["开除那些经常缺勤的学习者的措施", "让有风险的学习者留在学校的措施", "关闭学校以减少学生辍学人数的措施", "无视学生缺勤情况的常规措施"], "answer": 1, "explain": "辍学预防政策侧重于为有风险的学习者提供早期支持。", "src": "UNESCO"}, {"ch": 2, "q": "女孩与男孩之间的完成率差距说明了什么？", "options": ["哪一群体每所学校平均更高", "哪一群体每节课阅读更快", "某一群体是否较不可能完成学业", "哪一群体远比其他群体喜爱体育"], "answer": 2, "explain": "完成率差距揭示了需要有针对性政策加以解决的不平等。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 2, "q": "什么是针对前学习者的重返学校项目？", "options": ["把学习者送往国外工作的安排项目", "终止所有学习者继续学业的项目", "仅针对教师群体开展的培训项目", "帮助前学习者重返学校的项目"], "answer": 3, "explain": "重返学校项目支持学习者重新回到教育体系中。", "src": "UNESCO"}, {"ch": 2, "q": "良好的衔接政策对在不同体系间转换的学习者有什么作用？", "options": ["让学校或学段之间的转换更顺畅", "让每位学习者的转换都更加困难", "停止学校和学段之间的一切转换", "取消每学年结束时的考试"], "answer": 0, "explain": "良好的衔接政策降低了学习者在学段之间辍学的风险。", "src": "UNESCO"}, {"ch": 2, "q": "学校中的早期分流是什么？", "options": ["用GPS定位器追踪每个儿童的位置", "在幼年就把学习者分到不同的道路上", "在所有年龄段都教授完全相同的内容", "每天认真记录和统计当地天气情况"], "answer": 1, "explain": "早期分流可能限制以后的机会，并扩大不平等。", "src": "UNESCO"}, {"ch": 2, "q": "为什么能力分流会引发公平问题？", "options": ["它总是能够帮助班里最弱的学习者", "它对教育公平几乎没有任何影响", "它可能把弱势学习者锁在较低的路径上", "它让所有学习者的学习变得更加容易"], "answer": 2, "explain": "如果缺乏灵活性，早期分流可能固化劣势。", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "“完成学业还不够”这句话是什么意思？", "options": ["完成学业是唯一的目标", "只要完成学业，学习质量就无关紧要", "学习本身并不重要，可以忽略", "还必须保证学习质量"], "answer": 3, "explain": "完成学业很重要，但学习者也需要学得好。", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "学习测量中的增值是什么？", "options": ["学校在学习者起点之上所增加的进步", "学校每年加入年度预算的资金", "学校书架上所有书籍的重量", "学校每年招聘的教师人数"], "answer": 0, "explain": "增值衡量学校在多大程度上帮助学习者进步。", "src": "UNESCO"}, {"ch": 3, "q": "与家庭收入相关的学习差距叫什么？", "options": ["天气状况差距", "社会经济学习差距", "体育运动差距", "鞋子款式差距"], "answer": 1, "explain": "与家庭收入相关的学习差距说明机会并不平等。", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "各国为什么要对学习成果进行对标？", "options": ["为了完全避免在课堂上教学", "依据教师身高为他们进行排名", "比较进展并设定切合实际的目标", "为了对学习者进行严厉惩罚"], "answer": 2, "explain": "对标帮助各国相互比较成果并相互学习。", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "母语教学支持什么？", "options": ["只使用英语进行所有写作练习", "整个学年只进行唱歌和游戏活动", "完全不进行任何形式的学习活动", "理解和早期阅读"], "answer": 3, "explain": "母语教学帮助学习者理解内容，并建立早期阅读能力。", "src": "UNESCO, International Mother Language Day"}, {"ch": 3, "q": "课程与评估的一致性是什么？", "options": ["测评的内容与课程所教授的内容相符", "测评内容从不与课堂教学相符合", "测评涵盖从未教过的内容", "测评从不评分"], "answer": 0, "explain": "良好的一致性确保测评衡量的是课程所要达到的学习目标。", "src": "UNESCO"}, {"ch": 3, "q": "什么是学习分析？", "options": ["统计教室里所有课桌的准确数量", "利用学习数据改进教学", "每天凭感觉猜测明天的天气情况", "把学生的个人数据卖给商业公司"], "answer": 1, "explain": "学习分析利用数据来理解学习并指导支持。", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "什么是元认知？", "options": ["只思考和谈论体育运动的话题", "把自己所有的念头全部忘掉", "对自己的思维进行思考", "只能用一种语言进行思考"], "answer": 2, "explain": "元认知帮助学习者规划、监控并改进自己的学习。", "src": "UNESCO"}, {"ch": 3, "q": "教育中的深度学习是什么？", "options": ["在游泳池里尽可能深入地学习", "不理解地死记硬背", "只在黑暗的房间里学习", "理解观点到足以应用的程度"], "answer": 3, "explain": "深度学习超越死记硬背，走向理解和应用观点。", "src": "UNESCO"}, {"ch": 4, "q": "教育中的就业能力是什么？", "options": ["帮助人们找到并保住工作的技能", "无法胜任任何工作或行业", "拥有公司却从不参与工作", "一生都回避任何类型的工作"], "answer": 0, "explain": "就业能力融合了支持工作的技能、知识和态度。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "教育与劳动力市场的相关性是什么？", "options": ["学习完全无视现实中的各类工作", "学习内容符合经济所需要的技能", "学习只专门为艺术家和作家而设计", "学习的内容和方法从不发生任何变化"], "answer": 1, "explain": "相关的教育使学习者为现有或新兴的工作做好准备。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "什么是学徒制？", "options": ["每年末参加的一种标准化学校考试", "每学期中间教师所休的一段假期", "在有经验者指导下边干边学", "每天每节课都穿着的一种统一校服"], "answer": 2, "explain": "学徒制把在岗培训与正规学习结合起来。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "教师和学习者的数字素养是什么？", "options": ["在日常学习和生活中完全避免技术", "所有学习任务只用纸笔完成", "故意把学校的电脑全部弄坏", "安全且有效地使用数字工具"], "answer": 3, "explain": "数字素养帮助人们利用技术学习、工作和沟通。", "src": "UNESCO"}, {"ch": 4, "q": "什么是人工智能素养？", "options": ["理解人工智能能做什么、不能做什么", "相信人工智能总是正确的", "拒绝学习有关人工智能的知识", "认为人工智能取代了所有思考"], "answer": 0, "explain": "人工智能素养帮助学习者负责任地使用人工智能，并审视其输出。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "终身学习政策旨在做什么？", "options": ["学校教育结束后便终止一切学习", "在人生的每个阶段创造学习机会", "把所有学习限制在城里的年轻人身上", "全国停止所有成人教育项目"], "answer": 1, "explain": "终身学习政策支持从童年到老年的学习。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "非正式获得的技能如何被认可？", "options": ["忽视多年来在工作中学到的所有技能", "每年只统计书面学校考试的分数", "为在校外学到的技能给予正式学分", "撤销人们在工作中已经获得的证书"], "answer": 2, "explain": "认可帮助人们利用通过工作和社区生活获得的技能。", "src": "UNESCO"}, {"ch": 4, "q": "教育中的创新是什么？", "options": ["永远保留并沿用过去的所有旧方法", "原样照搬以前使用过的旧教科书", "停止接受和推行一切新的理念", "改进学习的新理念"], "answer": 3, "explain": "教育创新引入改进学习的新方法。", "src": "UNESCO"}, {"ch": 5, "q": "教育中的性别回应型预算是什么？", "options": ["考虑女孩和男孩需求的预算", "在每项决定中完全忽视性别的预算", "只为某区每所学校的男孩设立的预算", "只用于教师薪酬和假期的预算"], "answer": 0, "explain": "性别回应型预算为满足不同需求而规划资金。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "中学女生的留存是什么意思？", "options": ["让女生离开学校，不再继续入学", "让女生一直入学直至完成学业", "把女生长期留在同一个班级", "让女生在家庭中长期留守不上学"], "answer": 1, "explain": "女生留存指她们一直留在学校直到完成学业。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "对贫困家庭的社会保护有什么作用？", "options": ["把孩子带离家庭和住所", "给该地区每个贫困家庭增加新的学费", "帮助家庭应对冲击，并让孩子继续上学", "停止每天为贫困儿童提供免费午餐"], "answer": 2, "explain": "社会保护可以帮助家庭在困难时期让孩子继续上学。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "什么是儿童贫困？", "options": ["家里的玩具和游戏机太多", "身体长得比同龄人高很多", "智力水平明显高于同龄人", "童年时期生活在贫困之中"], "answer": 3, "explain": "儿童贫困限制了获得食物、医疗、住房和学习的机会。", "src": "UNESCO"}, {"ch": 5, "q": "学校中的族群隔离是什么？", "options": ["不同族群的学习者被分开", "所有学习者共用一个操场", "所有学习者说同一种语言", "所有学习者穿同样的校服"], "answer": 0, "explain": "隔离使学习者分离，限制了共同学习和相互理解。", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "为什么政策应覆盖游牧和流动社区？", "options": ["他们从不需要任何学校，也不想要学校", "缺乏灵活选择，他们常常错过学校教育", "他们总是很富裕，没有教育需求", "他们一生都宁愿完全不上学"], "answer": 1, "explain": "流动社区需要灵活的学校教育才能接受教育。", "src": "UNESCO"}, {"ch": 5, "q": "教育中的优先配额是什么？", "options": ["禁止弱势群体入学的一种配额制度", "只专门针对教师群体的配额制度", "为弱势群体预留的固定比例名额", "只专门针对体育活动的配额制度"], "answer": 2, "explain": "配额可以帮助弱势学习者获得原本可能错过的名额。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "冲突地区女孩的平等入学机会意味着什么？", "options": ["下令关闭所有专门面向女生的学校", "把所有女孩送往遥远的他乡居住", "完全忽视女孩在学习上的具体需求", "安全、受保护的路线和学校"], "answer": 3, "explain": "受保护的空间和安全的路线帮助女孩在冲突中继续学习。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 6, "q": "教师流失的常见原因是什么？", "options": ["薪资低、条件差、缺乏职业发展", "人人都升职很快、职业发展迅速", "所有员工都有很高的工作保障和长期合同", "每位教师都有长假和很短的工作时间"], "answer": 0, "explain": "当薪资、条件和职业前景薄弱时，教师就会离职。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是教师质量保障？", "options": ["一种把所有现任教师全部辞退的制度", "检查教学是否达到既定标准的制度", "一种专门用来规定教师假期的制度", "一种完全忽视学生学习需求的制度"], "answer": 1, "explain": "质量保障有助于保持教学的高水平。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是教师评估？", "options": ["测试教师在学校跑道上的跑步速度", "在教工室按身高给教师排名", "对教师表现进行审查，以支持其改进", "检查教师整个夏天的假期计划"], "answer": 2, "explain": "如果公平进行，评估能帮助教师反思并提升。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是教师教育课程？", "options": ["儿童每天在学校的具体课程表", "全校学生需要统一穿着的校服清单", "学校食堂每周提供的餐食菜单", "向未来教师教授的学科和技能"], "answer": 3, "explain": "教师教育课程使教师具备学科知识和教学法。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "为什么教师需要接受评估方面的培训？", "options": ["为了准确判断学习并给予支持", "这样他们就可以避免打分", "这样他们就可以停止测试", "这样他们就可以在没有依据的情况下打分"], "answer": 0, "explain": "评估培训帮助教师利用证据支持学习者。", "src": "UNESCO GEM Report 2026"}, {"ch": 6, "q": "什么是教师能动性？", "options": ["毫无思考地服从一切命令的教师", "教师塑造自身实践的能力", "从不做计划的教师", "只在夜间工作的教师"], "answer": 1, "explain": "教师能动性指教师能够做出改善学习的决定。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是教师专业学习共同体？", "options": ["争相获得最多假期的群体", "只出售教学材料的俱乐部", "教师共同学习以改进实践", "负责教学的学生群体"], "answer": 2, "explain": "学习共同体帮助教师分享想法并共同提升。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "教师的使命感影响什么？", "options": ["只影响学校采购的粉笔价格", "只影响学校校舍的建造造价", "对教学和学习几乎没有任何影响", "对学习者的动力和投入"], "answer": 3, "explain": "使命感和投入影响教师与学习者互动的方式。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "教育中的公私伙伴关系是什么？", "options": ["政府与私营提供者之间的合作", "私营公司依法经营所有学校", "政府放弃全部职责", "学校向政府付费"], "answer": 0, "explain": "伙伴关系可以扩大服务，但必须加以监管以保障质量和公平。", "src": "UNESCO"}, {"ch": 7, "q": "什么是民办学校的监管？", "options": ["在国家法律中默认禁止所有民办学校", "确保民办学校达到质量和安全标准", "让民办学校自由制定自己的规则", "完全忽视民办学校，从不检查"], "answer": 1, "explain": "监管保护民办学校中的学习者。", "src": "UNESCO"}, {"ch": 7, "q": "什么是教育的财政空间？", "options": ["在市中心建造汽车和卡车的空间", "学校走廊里放置新储物柜和长椅的空间", "政府预算中可以增加支出的空间", "每年夏天乡村露营活动的场地"], "answer": 2, "explain": "财政空间是政府为教育提供资金时所拥有的灵活度。", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "什么是教育方面的税收支出？", "options": ["每年用于学校考试、阅卷和印刷的支出", "每年用于教师假期和休假的支出", "每学期用于体育器材和学校运动会的支出", "减少政府教育收入的税收优惠"], "answer": 3, "explain": "税收支出是可能减少教育可用资金的税收优惠。", "src": "UNESCO"}, {"ch": 7, "q": "教育中的成本效益是什么？", "options": ["以最低成本取得学习成效", "不惜代价地投入尽可能多的资金", "把所有资金都只花在校舍建设上", "完全避免任何形式的教育支出"], "answer": 0, "explain": "具有成本效益的项目能用每一单位资金取得更多学习成效。", "src": "UNESCO"}, {"ch": 7, "q": "什么是学费减免？", "options": ["为新入学家庭设立的逾期入学费", "为无力支付的家庭免除学费", "每季度为教师的优秀工作发放的奖金", "整个学期乘坐校车的收费"], "answer": 1, "explain": "学费减免帮助贫困家庭让孩子继续上学。", "src": "UNESCO"}, {"ch": 7, "q": "教育预算的可信度是什么？", "options": ["一整年里资金从未真正用于学校", "预算由少数人秘密编制", "规划的教育资金确实用于学校", "预算每小时都在变，没有明确理由"], "answer": 2, "explain": "预算可信度指规划的教育资金真正落实到位。", "src": "UNESCO"}, {"ch": 7, "q": "家长教师协会在学校筹资中能发挥什么作用？", "options": ["独自承担并支付全部教师的工资", "完全取代政府的全部公共教育拨款", "直接决定关闭学校并停止全部教学", "筹资或提供支持，帮助满足学校需要"], "answer": 3, "explain": "家长协会可以帮助学校，但不应取代公共资金。", "src": "UNESCO"}, {"ch": 8, "q": "哪一项2006年的公约涉及残疾人？", "options": ["《联合国残疾人权利公约》", "《日内瓦贸易与关税公约》", "《东京体育与运动员培训协定》", "《利马农业与土地利用公约》"], "answer": 0, "explain": "《残疾人权利公约》（CRPD）于2006年通过，并包含受教育权。", "src": "UN CRPD (2006), Article 24"}, {"ch": 8, "q": "《残疾人权利公约》于哪一年通过？", "options": ["1994年", "2006年", "1989年", "2015年"], "answer": 1, "explain": "联合国《残疾人权利公约》于2006年通过。", "src": "UN CRPD (2006), Article 24"}, {"ch": 8, "q": "《儿童权利公约》第29条对教育有何规定？", "options": ["教育应当收费昂贵，由家庭全额承担", "教育只应面向男孩，女孩不得入学", "发展每个儿童的个性和才能", "应禁止残疾儿童接受任何形式的教育"], "answer": 2, "explain": "第29条规定了教育的目标，包括尊重权利和文化。", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 8, "q": "全民教育（Education for All）的常用缩写是什么？", "options": ["ELA", "EAL", "EFR", "EFA"], "answer": 3, "explain": "EFA是全民教育的常用缩写。", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "2015年《仁川宣言》对终身学习有何表述？", "options": ["应成为各个年龄段教育的一部分", "应在14岁时结束，之后不再接受教育", "应当被全面禁止，不得在任何地方实施", "应只适用于教师群体，不惠及其他人"], "answer": 0, "explain": "《仁川宣言》推动为所有人提供终身学习机会。", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "哪个机构发布全球教育数据？", "options": ["世界足球协会（负责国际足球赛事）", "联合国教科文组织统计研究所", "国际酒店理事会（负责酒店行业标准）", "全球音乐基金（负责音乐教育项目）"], "answer": 1, "explain": "联合国教科文组织统计研究所发布全球教育数据。", "src": "UNESCO GEM Report 2026"}, {"ch": 8, "q": "MDG与SDG之间有什么联系？", "options": ["SDG没有取代任何东西，两者并行不悖", "SDG取消了之前制定的所有目标和承诺", "SDG以MDG的经验教训为基础", "MDG目前仍然完全有效，并继续执行"], "answer": 2, "explain": "SDG以MDG为基础，并扩展了议程。", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "全球教育伙伴关系成立的目的是什么？", "options": ["在全世界范围内销售教科书和辅导材料", "组织国际体育赛事和运动员训练活动", "资助私人企业的太空旅行和探索项目", "支持低收入国家的教育"], "answer": 3, "explain": "全球教育伙伴关系帮助低收入国家提高学习质量。", "src": "UNESCO GEM Report 2026"}, {"ch": 8, "q": "《世界人权宣言》对父母与教育有何表述？", "options": ["父母对为子女选择教育拥有优先权", "父母在子女上学方面没有任何作用", "父母只能为子女选择体育和游戏", "父母必须为本镇所有学校付费"], "answer": 0, "explain": "第26条规定，父母对子女接受何种教育拥有优先选择权。", "src": "UN General Assembly (1948)"}, {"ch": 9, "q": "什么是幼儿教育与保育（ECEC）？", "options": ["只面向在职人员的成人教育与培训课程", "面向入小学前幼儿的学习与保育服务", "面向新教师的国家教师培训课程", "面向所有学生的中学考试和期末评估"], "answer": 1, "explain": "ECEC涵盖支持幼儿发展和学习的各项服务。", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "幼儿教育中的多部门方法是什么？", "options": ["只有教育在每所学校和教室里单独运作", "只有卫生在每家社区诊所和医院里单独运作", "卫生、营养、教育和保护共同合作", "只有体育在操场和场地里单独运作"], "answer": 2, "explain": "多部门方法统筹应对儿童在各项服务中的需求。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "什么是儿童与工作人员的比例？", "options": ["每个儿童平均拥有的玩具数量", "一个房间里窗户的具体数量", "休假中工作人员的总人数", "每位成人负责照看的儿童人数"], "answer": 3, "explain": "较低的比例可以让每个儿童获得更多关注和互动。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "为什么幼儿需要稳定一致的照护人？", "options": ["稳定的关系支持情感和认知发展", "一致性对幼儿根本不重要", "幼儿更喜欢许多陌生人而不是亲近的家人", "照护人每天都应更换以增加多样性"], "answer": 0, "explain": "稳定、一致的照护人帮助幼儿感到安全并学习。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "对残疾儿童的早期支持是什么？", "options": ["等到上学以后才开始提供任何帮助", "尽早提供帮助，培养技能与发展", "让残疾儿童长期远离其他人群和同伴", "完全忽视他们的成长和发展需求"], "answer": 1, "explain": "早期干预帮助残疾儿童更快地培养技能。", "src": "UN CRPD (2006), Article 24"}, {"ch": 9, "q": "什么是发展筛查？", "options": ["为每位学生挑选合适学校鞋的一项测试", "教师每年年末必须通过的考试", "快速检查，找出可能需要支持的儿童", "当地学校每年假期计划的检查"], "answer": 2, "explain": "筛查有助于识别可能需要进一步评估或帮助的儿童。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "什么是童年逆境经历（ACE）？", "options": ["每年夏天全家人一起的快乐旅行", "每学期颁发给优秀作业和努力的学校奖品", "小学生每年都要参加的一种标准化考试", "童年时期可能影响发展的有害事件"], "answer": 3, "explain": "ACE可能影响健康和学习，因此早期支持非常重要。", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "什么是国家识字战略？", "options": ["旨在全国提高识字水平的规划", "旨在销售报纸和杂志的商业规划", "旨在关闭城市图书馆的规划方案", "只针对某一所学校的一次性规划"], "answer": 0, "explain": "国家识字战略为提高阅读和写作能力设定目标与行动。", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "数字时代的识字是什么？", "options": ["在每节课上都避免使用屏幕和数字设备", "阅读、写作并理解数字形式的信息", "在任何时候都只阅读纸质书，不读其他内容", "在每个科目中都只用铅笔在纸上写作"], "answer": 1, "explain": "数字素养把阅读和写作扩展到网络环境中。", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "什么是成人识字调查？", "options": ["每年调查成人的假期和旅行计划", "调查每个城镇成人的汽车及车主情况", "衡量成人阅读和计算能力的调查", "调查每个城镇成人的体育和健身习惯"], "answer": 2, "explain": "成人识字调查衡量技能，为政策提供依据。", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "为什么图书馆对成人识字很重要？", "options": ["只为本镇的儿童和年轻学生服务", "只出售书籍，从不外借", "全天任何时候都对所有成年人关闭", "免费提供图书资源和学习支持服务"], "answer": 3, "explain": "图书馆支持想要阅读、学习和提升技能的成年人。", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "识字中的语言多样性是什么？", "options": ["一个社区中使用的各种不同语言", "无论何处都只使用一种共同语言", "禁止在学校使用任何当地语言", "只教授手语，不教授其他语言"], "answer": 0, "explain": "语言多样性很重要，因为学习者要用多种语言阅读和学习。", "src": "UNESCO, International Mother Language Day"}, {"ch": 10, "q": "学习者的阅读投入是什么？", "options": ["学习者走路的速度有多快，步伐如何", "学习者喜爱阅读并主动选择阅读的程度", "学习者说话的声音有多响亮，语速如何", "图书一共卖出了多少本，销量如何"], "answer": 1, "explain": "阅读投入显示学习者阅读的积极性有多高。", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "什么是识字过渡项目？", "options": ["在河流和公路上建造真正桥梁的项目", "每年定期关闭全市所有公共图书馆的项目", "帮助学习者从基础识字走向更高水平的项目", "只有体育和游戏、完全没有阅读的项目"], "answer": 2, "explain": "识字过渡项目帮助学习者超越基本阅读能力。", "src": "UNESCO, International Literacy Day"}, {"ch": 11, "q": "什么是包容性教育体系？", "options": ["学习者按残疾类型被分开安置的体系", "完全没有教师和教学人员的体系", "没有任何规则的体系", "所有学习者都纳入主流教育的体系"], "answer": 3, "explain": "包容性体系接纳学习者，并让主流教育适应他们。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "教育中的非歧视是什么？", "options": ["不分残疾、性别或背景，公平对待学习者", "在每所学校都按群体区别对待学习者", "仅因学习者所属群体而拒绝其进入学校", "根据学习者背景向部分学习者收取额外费用"], "answer": 0, "explain": "非歧视是包容性教育的基本原则。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "通用学习设计（UDL）的呈现原则是什么？", "options": ["只以单一的一种形式呈现内容", "以多种不同的形式呈现信息内容", "把信息对学习者隐藏起来不展示", "只在安静的环境中呈现"], "answer": 1, "explain": "多种呈现方式帮助学习者以不同方式获取内容。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "为什么残疾学习者应在决策中有发言权？", "options": ["他们永远不应被征求意见", "只有成年人可以决定", "他们最了解自己的需求", "决策应在没有他们参与的情况下做出"], "answer": 2, "explain": "应就影响残疾学习者的决定征求他们的意见。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "学习者参与学校决策是什么？", "options": ["学习者保持沉默，不发表任何意见", "学习者独自做出学校的所有决定", "学习者从来不参加任何学校会议", "学习者参与影响自身的决策"], "answer": 3, "explain": "学习者参与有助于培养责任感并尊重其权利。", "src": "UN Convention on the Rights of the Child (1989), Article 12"}, {"ch": 11, "q": "什么是校园氛围？", "options": ["学习者和教职工在学校中的感受", "仅指学校内部的室内温度高低", "学校里能照射进来的阳光多少", "学校拥有的校车数量有多少辆"], "answer": 0, "explain": "校园氛围决定学习者是否感到安全、受尊重并有动力。", "src": "UNESCO GEM Report 2026"}, {"ch": 11, "q": "什么是反欺凌政策？", "options": ["在每所学校都鼓励学生之间欺凌的规则", "制止欺凌并保护学习者的规则和行动", "在每所学校都完全无视欺凌的政策", "每学期都惩罚欺凌受害者的政策"], "answer": 1, "explain": "反欺凌政策保护学习者，支持安全的学习环境。", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "为什么包容性教育对社会有益？", "options": ["它制造社会分裂，加剧群体隔阂", "它会减少所有人的学习机会与质量", "它建立公平与社会凝聚力", "它只对少数人有用，对大多数人无益"], "answer": 2, "explain": "包容性教育为每个人建立社会凝聚力与公平。", "src": "UN CRPD (2006), Article 24"}], "12": [{"ch": 0, "q": "《2030年教育行动框架》主要是什么？", "options": ["指导各国落实SDG 4的指南", "学校比赛的体育规则手册", "国家银行的银行法", "所有校服的学校着装规定"], "answer": 0, "explain": "它为各国落实SDG 4提供指导。", "src": "Incheon Framework for Action (2015)"}, {"ch": 0, "q": "SDG全球指标框架是什么？", "options": ["每所学校一年中假期日期的列表", "一套商定的、用于衡量进展的指标", "每个学校图书馆禁止借阅的书籍清单", "显示所有校舍位置的地图"], "answer": 1, "explain": "全球指标框架提供共同指标，用于跟踪SDG的进展。", "src": "UN SDG Report 2026"}, {"ch": 0, "q": "SDG指标的层级分类显示了什么？", "options": ["每个学生在学年开始时有多高", "一个国家随时间建了多少所学校", "每项指标的方法论有多成熟", "一所学校每年通过活动筹集了多少钱"], "answer": 2, "explain": "层级反映了指标的方法论成熟度和数据可得性。", "src": "UN SDG Report 2026"}, {"ch": 0, "q": "为什么SDG 4指标要按财富水平分组？", "options": ["为了按身高给家庭排名", "为了选择校服", "为了确定假期日期", "为了揭示富裕与贫困学习者之间的差距"], "answer": 3, "explain": "按财富分组可以显示进展是否惠及较贫困的学习者。", "src": "UNESCO GEM Report 2026"}, {"ch": 0, "q": "SDG 4的融资追踪衡量什么？", "options": ["投入了多少资金以及资金流向何处", "种植了多少棵树", "存在多少个体育俱乐部", "印刷了多少本书"], "answer": 0, "explain": "融资追踪显示投资水平，以及资金是否到达优先群体。", "src": "Incheon Framework for Action (2015)"}, {"ch": 0, "q": "教育政策评估是什么？", "options": ["选择新的校园颜色", "评估政策是否实现了其目标", "数学校的窗户", "写关于假期的诗"], "answer": 1, "explain": "评估有助于决定政策应继续、调整还是停止。", "src": "UNESCO"}, {"ch": 0, "q": "什么是循证政策？", "options": ["完全不依据任何数据制定的政策", "凭猜测制定的政策", "以研究和数据为依据的政策", "从电影中照搬的政策"], "answer": 2, "explain": "循证政策利用研究来指导决策。", "src": "UNESCO"}, {"ch": 0, "q": "政府为什么需要教育数据系统？", "options": ["为了避免做出决策", "为了隐藏信息", "为了取代教师", "为了规划、监测和改进教育"], "answer": 3, "explain": "数据系统支持规划、监测和问责。", "src": "UNESCO GEM Report 2026"}, {"ch": 0, "q": "SDG 4与其他目标存在协同效应意味着什么？", "options": ["教育进步有助于推动其他目标的进展", "教育阻碍所有其他目标", "教育与其他目标毫无关系", "其他目标只影响体育"], "answer": 0, "explain": "教育支持健康、性别平等、就业和气候等目标。", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "什么是未入学（non-enrolment）？", "options": ["注册了却不上学", "处于学龄却未注册入学", "只在国外上学", "无偿教学"], "answer": 1, "explain": "未入学指学龄儿童没有在学校登记注册。", "src": "UNESCO"}, {"ch": 1, "q": "什么是有效的教育机会？", "options": ["只存在于纸面上的机会", "没有任何教师的机会", "不仅能入学，还能带来真正学习的机会", "只持续一天的机会"], "answer": 2, "explain": "有效机会意味着儿童既上学又学习，而不只是注册入学。", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "对于学业中断的儿童，什么是补救途径？", "options": ["让他们离开学校的途径", "跳过年级却没有学习的途径", "关闭学校的途径", "帮助他们补上落下的课程并重返学校的途径"], "answer": 3, "explain": "补救途径帮助失学儿童重新回到教育之中。", "src": "UNESCO"}, {"ch": 1, "q": "受教育权对国家提出什么要求？", "options": ["使教育可得、可及、可接受、可调适", "只为本国富裕家庭提供教育", "只在本国大城市提供教育", "让每个家庭都可以完全自由选择是否接受教育"], "answer": 0, "explain": "四个“A”描述了受教育权的核心义务。", "src": "UN Special Rapporteur on the Right to Education"}, {"ch": 1, "q": "受教育权中的“可得性”（availability）是什么意思？", "options": ["学校在一年中从不向任何学生开放", "有足够数量的运作中的学校和项目", "学校只在周末和公共假日向家庭开放", "学校只在某些日子供教师使用"], "answer": 1, "explain": "可得性指有足够多正常运作的机构和项目。", "src": "UN Special Rapporteur on the Right to Education"}, {"ch": 1, "q": "受教育权中的“可接受性”（acceptability）是什么意思？", "options": ["总是让学生感到枯燥乏味的教育形式", "对家长和社会公众刻意保密的教育", "优质且文化上适宜的教育", "只用单一语言开展的教学和课程"], "answer": 2, "explain": "可接受性指教育切合相关性、安全性并具有良好质量。", "src": "UN Special Rapporteur on the Right to Education"}, {"ch": 1, "q": "受教育权中的“适应性”（adaptability）是什么意思？", "options": ["从不随时代需求变化的教育", "忽视学习者和家庭需求的教育", "在所有学校中永远保持不变的教育", "能够适应学习者和社会需求的教育"], "answer": 3, "explain": "适应性指教育能够回应不断变化的需求。", "src": "UN Special Rapporteur on the Right to Education"}, {"ch": 1, "q": "为什么教育的个人自付支出令人担忧？", "options": ["家庭直接承担费用，可能使儿童被迫离开学校", "家庭在教育方面从来不需要支付任何费用", "个人自付支出总是能帮助学校改善各项条件", "只影响教师的工资待遇和日常的工作安排"], "answer": 0, "explain": "高昂的直接费用可能使贫困家庭无法送子女上学。", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "什么是人道主义教育应对？", "options": ["只在和平稳定、没有危机的时期开展的教育", "在紧急情况和危机中对教育的支持", "直接关闭受影响地区学校的应对措施", "只限于体育领域开展的各种应对措施"], "answer": 1, "explain": "人道主义教育应对在危机中维持学习的延续。", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "从中学到高等教育的学习路径是什么？", "options": ["永久离开教育且不再返回的路径", "只为已经离校的成年人设计的路径", "从中学通向继续学习的路径", "每位学生放学后进入体育俱乐部的路径"], "answer": 2, "explain": "学习路径将中等教育与高等学习和培训连接起来。", "src": "UNESCO"}, {"ch": 2, "q": "什么是高等教育（tertiary education）？", "options": ["幼儿园之前为幼儿提供的教育", "只针对教师培训课程的教育", "只针对体育和俱乐部运动员训练的教育", "中学之后的教育，如大学或学院"], "answer": 3, "explain": "高等教育包括大学、学院和高级技术培训。", "src": "UNESCO"}, {"ch": 2, "q": "教育完成的公平性是什么？", "options": ["各群体之间的完成率相近", "完成率只偏向富人", "完成率从不被衡量", "完成率始终为零"], "answer": 0, "explain": "完成率的公平意味着各群体完成学业的比例相近。", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "哪些人被称为早期离校者（early leavers）？", "options": ["因假期而提前离校的青年", "未完成中等教育便离开的青年", "提前离开的教师", "最先完成学业的学生"], "answer": 1, "explain": "早期离校者指没有获得中等教育资格就离开的青年。", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "高中阶段的职业课程是什么？", "options": ["只在家里教授的烹饪和烘焙课程", "历史、法律和政治的大学学位课程", "提供实用技能和资格证书的课程", "夏季为幼儿举办的假期营地"], "answer": 2, "explain": "高中阶段的职业课程提供实用技能和资格证书。", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "完成学业对以后的生活为什么重要？", "options": ["以后的生活中几乎没有任何明显影响", "只会影响每年的假期安排和休息时间", "只会影响学生参加体育活动的情况", "对健康、就业和收入有重要影响"], "answer": 3, "explain": "完成学业与更好的健康、就业和福祉相关联。", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "什么是终身完成学业（lifelong completion）？", "options": ["在任何年龄完成学习", "只在十岁之前完成学习", "学校毕业后停止学习", "只为教师而学习"], "answer": 0, "explain": "终身完成学业意味着人们可以在任何年龄完成学习。", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "辍学的逆转是什么？", "options": ["学习者离校速度更快", "学习者离开后重返教育并完成学业", "学习者只在考试中倒退", "学习者每年减免学费"], "answer": 1, "explain": "辍学逆转指学习者重新入学并完成教育。", "src": "UNESCO"}, {"ch": 3, "q": "各国的基础技能目标是什么？", "options": ["确保儿童在整个小学阶段只学习音乐和唱歌", "确保儿童在小学阶段从不学习阅读和写作", "确保多数儿童在小学末尾掌握基本读写和算术", "确保儿童在小学阶段逃学并长期待在家中"], "answer": 2, "explain": "许多国家致力于确保儿童在小学初期就掌握基本技能。", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "学习质量是什么意思？", "options": ["只在每节课上快速匆忙完成的学习", "对每位学生来说只是漫长而累人的学习", "对每位学生都避免一切考试和测验的学习", "相关、有效且公平的学习"], "answer": 3, "explain": "优质学习满足学习者的需要，并带来真正的进步。", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "课程相关性是什么？", "options": ["将学习与学习者的生活和未来工作联系起来", "教授在现实中永远不会被用到的各种内容", "完全忽视学习者的日常生活与个人经验", "只使用已经消亡的古代语言来开展教学"], "answer": 0, "explain": "相关的课程把课堂与现实生活和未来需求联系起来。", "src": "UNESCO"}, {"ch": 3, "q": "什么是成果导向的教育政策？", "options": ["根据学校规模设定目标", "根据学习者能够做到的事情设定目标", "根据教师身高设定目标", "根据假期长短设定目标"], "answer": 1, "explain": "成果导向政策关注学习者所取得的技能和成就。", "src": "UNESCO"}, {"ch": 3, "q": "课堂上的跨语言教学（translanguaging）是什么？", "options": ["禁止学校里除一种语言以外的所有语言", "在每节课上只使用手语", "利用学习者的所有语言来支持学习", "在任何课上都保持沉默、不说话地教学"], "answer": 2, "explain": "跨语言教学利用学习者的全部语言资源来帮助他们学习。", "src": "UNESCO, International Mother Language Day"}, {"ch": 3, "q": "什么是认知负荷？", "options": ["每天上学时背在身上的书包的实际重量", "一本书中包含的全部页数与插图数量", "教室里自然光线照射进来的实际数量", "完成某项任务所需要的心智努力程度"], "answer": 3, "explain": "认知负荷关系到学习者如何加工并记住信息。", "src": "Harvard Center on the Developing Child"}, {"ch": 3, "q": "什么是间隔练习（spaced practice）？", "options": ["将学习时段分散在不同时间以提高记忆", "在考试前的最后一晚把全部内容集中塞进脑子", "同样的学习材料在任何时候都不再重复练习", "只在每年漫长的学校假期期间才集中练习"], "answer": 0, "explain": "间隔练习有助于随时间更好地记住信息。", "src": "UNESCO"}, {"ch": 3, "q": "什么是提取练习（retrieval practice）？", "options": ["反复抄写笔记却从不尝试去回忆内容", "从记忆中提取信息以加强学习", "只阅读每一章节的标题而不读正文", "完全忽略课堂上老师刚刚讲授的内容"], "answer": 1, "explain": "提取练习通过回忆所学内容来加强记忆。", "src": "UNESCO"}, {"ch": 3, "q": "什么是评估偏差？", "options": ["对所有学生始终保持绝对公平的测试", "从不真正衡量学习者实际学到什么的测试", "对某些群体不公平地有利的测试", "只用来测量学生身高与体重的测试"], "answer": 2, "explain": "评估中的偏差可能因与能力无关的原因而使学习者处于不利地位。", "src": "UNESCO GEM Report 2026"}, {"ch": 4, "q": "什么是跨学科技能（transversal skills）？", "options": ["只适用于某一门学科的专门性技能", "用于帮助人们保持良好睡眠的技能", "只用于安全过马路的基本技能", "在许多学科和工作中都有用的技能"], "answer": 3, "explain": "沟通和团队合作等跨学科技能到处都适用。", "src": "UNESCO"}, {"ch": 4, "q": "什么是数字教学法？", "options": ["善于利用技术的教学方法", "完全不使用任何技术手段的教学方式", "只使用已经损坏的机器进行的教学", "只在完全沉默的状态下进行的教学"], "answer": 0, "explain": "数字教学法利用技术来支持学习，而不只是取代纸张。", "src": "UNESCO"}, {"ch": 4, "q": "教育技术中的数据隐私是什么？", "options": ["与陌生人分享学习者的数据", "保护学习者的个人信息", "出售学习者的数据", "无视隐私规则"], "answer": 1, "explain": "数据隐私保护学习者免受其个人信息被滥用。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "什么是技能提升（upskilling）？", "options": ["在工作时失去已有的技能", "每年只为小学生学习", "学习新技能以跟上不断变化的工作", "一开始新工作或新职业就停止所有培训"], "answer": 2, "explain": "技能提升帮助工作者适应新技术和新工作。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "什么是技能再培训（reskilling）？", "options": ["忘记过去所有的技能和知识", "只为了休闲娱乐而学习体育和游戏", "彻底停止工作并永远待在家里", "学习新技能以转向另一种类型的工作"], "answer": 3, "explain": "技能再培训在旧工作改变时为人们准备新的角色。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "什么是绿色就业培训？", "options": ["为有益于环境的工作做准备", "培训从事破坏自然的工作", "只培训如何粉刷墙壁", "培训如何参加体育运动"], "answer": 0, "explain": "绿色就业培训为人们从事可持续的工作做准备。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "什么是全球胜任力？", "options": ["完全忽视其他国家及其人民", "理解世界和其他文化并与之互动", "只了解一个国家的历史而别无所知", "拒绝旅行或与其他国家的人接触"], "answer": 1, "explain": "全球胜任力帮助学习者理解全球性问题并跨文化交流。", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "什么是社会与情感学习（SEL）？", "options": ["学习在任何情况下都避免一切感受和情绪", "每天在学校只学数学，别无其他", "学习管理情绪并与他人良好相处", "学习在进入的每一个社交场合都保持沉默"], "answer": 2, "explain": "社会与情感学习培养自我认知、同理心和人际关系技能。", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "什么是性别规范？", "options": ["学校食堂中孩子们吃什么的规定", "全市每座学校建筑的大小测量", "只针对教师和员工的假期规定", "社会对女孩和男孩应如何行事的共同期待"], "answer": 3, "explain": "性别规范塑造了女孩和男孩的角色与机会。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "让女孩留在学校与童婚有什么关系？", "options": ["这是推迟童婚最有效的方法之一", "每年鼓励女孩很早结婚", "与任何社区任何年龄的婚姻都没有关系", "每个学期都关闭社区的女子学校"], "answer": 0, "explain": "让女孩留在学校是推迟童婚最有效的方法之一。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "青少年怀孕对就学有什么影响？", "options": ["总是改善就学情况", "可能中断女孩的教育", "与学校毫无关系", "只影响男孩"], "answer": 1, "explain": "怀孕可能中断学业，因此重返学校和支持性政策十分重要。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "学校中的包容性卫生设施是什么？", "options": ["只供教师和学校员工使用的厕所", "没有给任何学生提供厕所或洗手设施", "满足每个人需求的厕所和洗手设施", "白天总是对学生上锁的厕所"], "answer": 2, "explain": "包容性卫生设施包括为女孩和残疾学习者提供的设施。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "除了金钱，学习者贫困还包括什么？", "options": ["每晚在家要读的书太多", "放学后可以玩耍的朋友太多", "每天放学后有太多空闲时间玩耍", "缺乏食物、交通、学习材料和安静的学习空间"], "answer": 3, "explain": "学习者贫困包括缺乏食物、交通、学习材料和安静的学习空间。", "src": "UNESCO"}, {"ch": 5, "q": "什么是多重劣势？", "options": ["同时面临多重障碍", "完全没有遇到任何形式的障碍和困难", "只遇到一个很小的、不影响的障碍", "获得了远超实际需要的过多支持"], "answer": 0, "explain": "多重劣势指多种障碍叠加，需要综合应对。", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "难民纳入国家系统是什么意思？", "options": ["永久隔离难民学习者", "将难民学习者纳入国家教育体系", "拒绝接收难民学习者", "只在网上教授难民"], "answer": 1, "explain": "难民纳入国家系统有助于他们获得教育和得到承认的资格证书。", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "什么是游牧教育？", "options": ["始终固定在同一栋楼房里进行的教育", "只为城市儿童设计的教育", "为流动社区设计的教育", "没有教师的教育"], "answer": 2, "explain": "游牧教育根据流动家庭调整教学和时间安排。", "src": "UNESCO"}, {"ch": 5, "q": "教育公平指数衡量什么？", "options": ["学校建筑的高度与当地的建筑风格", "学校每天打铃的次数与时间安排", "教师每年享受假期的具体天数长度", "不同群体之间的入学或结果对比情况"], "answer": 3, "explain": "公平指数概括了教育分配的公平程度。", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "教师中的性别平衡是什么意思？", "options": ["男女教师人数比例均衡", "这里的学校只允许男性任教", "这里的学校只允许女性任教", "这里的学校根本不需要任何教师"], "answer": 0, "explain": "教师中的性别平衡会影响榜样作用和学校文化。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 6, "q": "什么是教师供需分析？", "options": ["比较教师每年喜欢的颜色和服装", "比较所需教师数量与可用教师数量", "统计教师每年休假和请假的天数", "比较教师办公室里每年教师的身高"], "answer": 1, "explain": "供需分析帮助政府规划教师招聘。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是教师教育改革？", "options": ["取消所有教师培训", "结束教师的职业生涯", "改变教师的培养方式", "只关闭教师培训机构"], "answer": 2, "explain": "教师教育改革更新培训内容，使之与现代课堂相匹配。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是学校领导力发展？", "options": ["培训领导者不进入自己所访问的任何课堂教学", "只培训学校的体育与游戏领导", "培训领导者每学期提前关闭学校", "培训校长以指导教学与学习"], "answer": 3, "explain": "发展领导力可以提升学校质量。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "教师职业发展包括什么？", "options": ["提升技能与责任的清晰阶梯", "教师在职业中没有任何上升的阶梯", "每年只有假期和长时间的休息", "每学期只有减薪和人员减少"], "answer": 0, "explain": "清晰的职业发展阶梯帮助教师成长并留在这一行业。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是师生关系？", "options": ["完全没有任何直接接触的一种关系", "支持学习的积极纽带", "只是单纯的利益交换和买卖关系", "阻碍学习并使学习者不断退缩的敌对关系"], "answer": 1, "explain": "良好的关系帮助学习者感到安全并受到激励。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "什么是教师工作时间？", "options": ["只计算一个完整学校日中的总分钟数", "用于度假、休息与各种休假的时间", "教师用于教学和相关工作的总时间", "每天上下班在公交车上的通勤时间"], "answer": 2, "explain": "工作时间包括备课、批改作业以及课外的其他职责。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "为什么一些教师在危机地区需要额外支持？", "options": ["他们在日常工作中没有遇到任何困难", "他们在教学实践中从不需要任何支持", "他们每年享有过多的假期和休息时间", "他们面临不安全的环境和创伤"], "answer": 3, "explain": "危机中的教师可能需要培训和心理健康支持。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "什么是每生教育支出？", "options": ["每位学习者的平均支出", "每所学校的书籍数量", "一次考试的费用", "一条校车路线的费用"], "answer": 0, "explain": "每生支出有助于比较各系统之间的资源。", "src": "UNESCO"}, {"ch": 7, "q": "为什么费用分担会对入学构成问题？", "options": ["总是降低家庭的费用", "可能把费用转嫁给无力负担的家庭", "对入学没有任何影响", "取消了所有费用"], "answer": 1, "explain": "如果管理不当，费用分担可能给贫困家庭造成障碍。", "src": "UNESCO"}, {"ch": 7, "q": "教育债务减免是什么？", "options": ["增加公共债务，只用于资助学校体育", "立即关闭全国所有的公立学校", "减少债务偿还，使资金可用于学校", "强迫教师代替政府偿还各种债务"], "answer": 2, "explain": "债务减免可以释放资金用于教育。", "src": "UNESCO GEM Report 2026"}, {"ch": 7, "q": "教育的创新融资是什么？", "options": ["只用黄金支付教师工资", "只出售学校的课桌", "只关闭学校", "为教育筹集资金的新途径"], "answer": 3, "explain": "创新融资包括调动资金的新机制。", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "什么是教育融资计划？", "options": ["显示教育如何在一段时间内获得资金的计划", "只针对假期安排而完全没有教学课程的计划", "为学校全体员工统一购买汽车和货车的计划", "没有任何数字、成本或日期的计划"], "answer": 0, "explain": "融资计划将教育目标与实现这些目标所需的资金联系起来。", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "教育财政分权是什么？", "options": ["每年把所有资金都转移到首都", "让地方政府对教育资金有更大控制权", "禁止地方政府做出任何决定", "逐一关闭地方学校直到一所不剩"], "answer": 1, "explain": "分权有助于地方回应，但需要保障公平的机制。", "src": "UNESCO"}, {"ch": 7, "q": "什么是均衡拨款（equalisation grant）？", "options": ["每年让富裕地区更加富有的资金", "只用于每个夏天教师假期的资金", "帮助贫困地区赶上富裕地区的额外资金", "每年用于在贫困地区关闭学校的资金"], "answer": 2, "explain": "均衡拨款缩小了各地区之间的差距。", "src": "UNESCO"}, {"ch": 7, "q": "教育资助中的日落条款（sunset clause）是什么？", "options": ["一项专门规定日落时分校园开放时间的条款", "一项规定学校舞会和晚会安排的规则", "一项每天自动把资助金额翻倍的规则", "在设定期限后终止资助，除非重新批准"], "answer": 3, "explain": "日落条款会终止项目，除非经过审查并重新批准。", "src": "UNESCO"}, {"ch": 7, "q": "教育的政府收入是什么？", "options": ["政府从税收和其他来源征收的资金", "全国体育场每年售票的收入", "只来自家庭学费而不含税收的资金", "只来自旅游和出行的收入"], "answer": 0, "explain": "政府收入是公共教育资金的主要基础。", "src": "UNESCO"}, {"ch": 8, "q": "《萨拉曼卡宣言》推动什么？", "options": ["只为被隔离的儿童设立的学校", "为所有儿童提供的包容性学校", "只为成年人设立的学校", "只为教师设立的学校"], "answer": 1, "explain": "《萨拉曼卡宣言》推动为有特殊需要的儿童提供包容性教育。", "src": "UN CRPD (2006), Article 24"}, {"ch": 8, "q": "《世界人权宣言》是哪一年通过的？", "options": ["1989年", "1990年", "1948年", "2015年"], "answer": 2, "explain": "《世界人权宣言》于1948年由联合国大会通过。", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "哪项公约规定了包括教育在内的儿童权利？", "options": ["《日内瓦国际贸易与关税条约》", "《日内瓦国际体育与运动员宪章》", "《东京国际航运与港口管理守则》", "《儿童权利公约》"], "answer": 3, "explain": "《儿童权利公约》于1989年通过，规定了包括受教育权在内的儿童权利。", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 8, "q": "达喀尔目标对幼儿阶段作出了什么承诺？", "options": ["扩大并改善幼儿保育和教育", "在全国范围内关闭所有幼儿服务机构", "完全忽视幼儿以及他们家庭的需求", "禁止每个城镇和乡村设立任何幼儿园"], "answer": 0, "explain": "达喀尔目标包括扩大和改善幼儿保育与教育。", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "《仁川宣言》为2030年确立了什么目标？", "options": ["只为每年最优秀学生提供的高等教育", "包容、公平、优质的教育与终身学习", "只为全国每所学校提供体育和游戏", "只在夏季各地区开设的暑期学校"], "answer": 1, "explain": "《仁川宣言》为2030年确立了这一目标。", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "为什么2015年的可持续发展目标比千年发展目标走得更远？", "options": ["它们只适用于世界上的贫穷国家，不适用其他国家", "它们在全世界只涵盖教育，别无其他", "它们具有普遍性，涵盖气候和不平等等更广泛问题", "它们结束了对世界最贫穷国家的一切援助"], "answer": 2, "explain": "可持续发展目标适用于所有国家，涵盖的问题比千年发展目标更多。", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "教育促进可持续发展（ESD）的目标是什么？", "options": ["只讲授与环境保护相关的各项法律条文", "取消所有学校的科学实验与探究课程", "停止在所有年级学习环境相关的全部内容", "让学习者为可持续的未来而行动"], "answer": 3, "explain": "可持续发展教育帮助学习者理解可持续性并采取行动。", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "联合国关于受教育权的特别报告员做什么？", "options": ["报告全球受教育权的情况", "负责经营一所学校并管理其教职员工", "担任各国职业足球比赛的专职裁判", "负责管理一家国际银行并监督其运营"], "answer": 0, "explain": "联合国特别报告员负责报告全球受教育权的情况。", "src": "UN Special Rapporteur on the Right to Education"}, {"ch": 9, "q": "早年大脑发育主要受什么影响？", "options": ["孩子们玩具的颜色与外观样式", "经历和人际关系", "全市每天运行的校车数量统计", "每年购买校服的平均价格水平"], "answer": 1, "explain": "人际关系和经历塑造了生命早期的大脑发育。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "为什么幼儿政策需要跨部门协调？", "options": ["儿童只需要课堂教育就能学好", "儿童只需要医疗保健就能成长", "儿童的需求涵盖健康、照护、营养和学习", "儿童不需要任何服务或家庭的帮助"], "answer": 2, "explain": "协调有助于在不同服务中满足儿童的需求。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "什么是幼儿发展指数？", "options": ["衡量学校建筑的规模与基础设施状况", "统计教师家中宠物的数量与种类", "列出全年全部国家和地方假期的清单", "衡量儿童在关键领域准备程度的指标"], "answer": 3, "explain": "发展指数追踪儿童在各个领域的准备情况。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "幼儿阶段的丰富语言互动是什么？", "options": ["能够建立词汇和理解力的交谈", "在房间里一言不发、只玩玩具的静默游戏", "在家中一整天不停地对孩子大喊大叫", "每天花数小时只看电视"], "answer": 0, "explain": "丰富的语言互动支持后续的阅读和学习。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "什么是早期识别与转介？", "options": ["无视在学校和家里需要帮助的儿童", "找出需要帮助的儿童并将他们与服务连接起来", "永久地给儿童贴上固定而严厉的标签", "每当儿童表现出需要帮助时就把他们送回家"], "answer": 1, "explain": "转介系统及早将儿童与合适的支持连接起来。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "什么是幼儿阶段的家庭支持？", "options": ["让儿童脱离家庭和居所", "全年禁止家长到学校探访", "帮助家庭照顾和教育幼儿的支持", "在每个学校决定中完全忽视家庭"], "answer": 2, "explain": "家庭支持强化家庭学习和幸福感。", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "儿童健康与学习有什么关系？", "options": ["健康与任何学校的学习都没有关系", "生病的孩子在课堂上比健康的孩子学得更快", "健康只在学校的一天结束后才重要", "良好的健康有利于出勤、注意力和发育"], "answer": 3, "explain": "儿童健康与学习成果密切相关。", "src": "UN 2030 Agenda (2015)"}, {"ch": 10, "q": "什么是终身识字？", "options": ["在一生中持续发展阅读和写作能力", "只在童年阅读，之后再也不读", "只在学校阅读，从不在家或校外阅读", "一生中只为工作而阅读，别无其他"], "answer": 0, "explain": "终身识字意味着在一生中持续阅读和写作。", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "什么是信息阅读技能？", "options": ["只阅读各类小说和虚构的故事作品", "在文本中查找和使用事实", "只阅读古典诗歌和诗集类作品", "毫无目的地随意翻阅各类书籍"], "answer": 1, "explain": "信息阅读帮助学习者找到事实，从而做出决定。", "src": "UNESCO"}, {"ch": 10, "q": "什么是文本的可读性（readability）？", "options": ["一本书拿在手中感觉有多沉重", "一本书究竟有多少页、多少章节", "文本被阅读和理解的难易程度", "购买一本新书需要花费多少钱"], "answer": 2, "explain": "可读性取决于语言、句子长度和词汇。", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "什么是识字中的性别差距？", "options": ["女孩和男孩在身高上的差异", "女孩和男孩在鞋码上的差异", "女孩和男孩在喜欢颜色上的差异", "女孩和男孩在阅读能力上的差异"], "answer": 3, "explain": "识字中的性别差距因国家而异，需要有针对性的应对。", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 10, "q": "在资源匮乏环境中获取印刷材料是什么？", "options": ["获得供阅读的印刷材料", "完全禁止印刷任何形式的书面材料", "只印刷国家使用的纸币和硬币", "只印刷精细的月球表面地图"], "answer": 0, "explain": "获取印刷材料帮助资源匮乏地区的学习者练习阅读。", "src": "UNESCO"}, {"ch": 10, "q": "什么是母语识字政策？", "options": ["禁止所有学校使用母语的政策", "用儿童所说的语言教授初始阅读的政策", "在所有学校的每个班级只教英语的政策", "从六岁起在所有班级只教手语的政策"], "answer": 1, "explain": "母语识字有助于早期阅读和身份认同。", "src": "UNESCO, International Mother Language Day"}, {"ch": 10, "q": "什么是发展性识字？", "options": ["在日常生活或工作中没有任何目的的识字", "只为每年来访的游客提供的识字", "利用识字能力改善健康、就业和社区生活", "在每个儿童满十岁时结束的识字"], "answer": 2, "explain": "识字能力促进健康、工作和公民生活等方面的发展。", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "什么是阅读兴趣培养项目？", "options": ["禁止故事书的项目", "只测试拼写的项目", "十岁后停止阅读教学的项目", "鼓励儿童为了乐趣而阅读的项目"], "answer": 3, "explain": "阅读兴趣培养项目帮助建立支持终身识字的动机和习惯。", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 11, "q": "教育中作为人权原则的包容是什么意思？", "options": ["每位学习者都有归属感并参与其中", "一些学习者被有意地与其他人分开", "学习者按照能力高低被分隔开来", "学习者被有意设计成被排除在外"], "answer": 0, "explain": "包容是一项人权原则，保障归属感与参与权。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "什么是包容性教师教育？", "options": ["培训教师只教授最优秀的学习者", "培训教师教育所有学习者", "培训教师回避残疾学习者", "培训教师只教体育"], "answer": 1, "explain": "包容性教师培训使教师能够应对多元化的课堂。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "包容性学校中的个别支持意味着什么？", "options": ["只为整所学校的整体运行提供的支持", "只为每个年级里表现最好的学生提供", "针对每位学习者具体需要提供的帮助", "一概不提供任何形式的支持和帮助"], "answer": 2, "explain": "个别支持使帮助适应每位学习者。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "课程中的残疾包容是什么？", "options": ["将残疾排除在课堂的每一门课程之外", "把残疾当作对行为不良学生的惩罚来教授", "每周只在体育课上教授残疾相关内容", "将残疾纳入关于多样性的学习内容"], "answer": 3, "explain": "课程中的残疾包容促进尊重与理解。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "包容的参与式评估是什么？", "options": ["让学习者参与评判自己的进步", "对学习者秘密评估而不告诉他们", "忽视学习者对自己作品的看法", "只根据学习者的身高来评估"], "answer": 0, "explain": "参与式评估培养自我认知和包容。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "什么是包容性教师招聘？", "options": ["只从单一群体中挑选和招聘教师", "从多元群体中招聘教师", "一律拒绝所有前来应聘的申请人员", "只凭借家庭和亲属关系来招聘人员"], "answer": 1, "explain": "包容性招聘帮助学校反映其所服务的社区。", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 11, "q": "残疾包容数据是什么？", "options": ["对公众完全隐藏残疾的数据", "每个季节只在体育和游戏中涉及残疾的数据", "包括残疾人及其需求的数据", "在任何学校或地区都从未收集的数据"], "answer": 2, "explain": "包容性数据帮助政策回应残疾问题。", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "为什么教育权被称为“倍增权”？", "options": ["因为它使书本价格成倍地上涨和增加", "因为它使学费在每年都翻上一番", "因为它只适用于教师群体而非其他人", "因为它帮助人们获得其他权利"], "answer": 3, "explain": "教育帮助人们获得健康、工作、政治参与和其他权利。", "src": "UN Special Rapporteur on the Right to Education"}]};
